package com.guess34.lendingtracker;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class LendingTrackerPluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(LendingTrackerPlugin.class);
		RuneLite.main(args);
	}
}

package com.guess34.lendingtracker.model;

import lombok.AllArgsConstructor;
import lombok.Data;
import lombok.NoArgsConstructor;

@Data
@NoArgsConstructor
@AllArgsConstructor
public class GroupMember {
    private String name;
    private String role; // owner, admin, moderator, member

    // When this member (last) joined, epoch millis. Used against the group's
    // removed-member tombstones: a kick recorded AFTER this time removes the
    // member everywhere; a re-join after the kick gets a fresh joinedAt and
    // survives. Members saved before this field existed deserialize to 0, so
    // any tombstone wins for them (correct - they joined before any kick).
    private long joinedAt;

    // When this member's ROLE last changed, epoch millis. Roles used to ride the
    // single whole-roster stamp, so a demoted owner whose client had not seen the
    // demotion would republish their old role and the newer roster stamp would
    // restore it - undoing the demotion for everyone. Versioning each row means a
    // stale republish loses to the change it never saw. 0 on members saved before
    // this existed, so any explicit role change beats them.
    private long roleUpdatedAt;
    // This member's Discord user ID, so loan posts can tag them. Only there if
    // they turned "Ping me" on; sealed with the group key (WebhookSeal) because
    // the roster is stored on the relay. Set by the member's own client. Its own
    // stamp, newest wins; empty with a newer stamp means they turned it off.
    private String discordSealed;
    private long discordUpdatedAt;

    public GroupMember(String name, String role) {
        this.name = name;
        this.role = role;
        this.joinedAt = System.currentTimeMillis();
        this.roleUpdatedAt = System.currentTimeMillis();
    }
}

package com.guess34.lendingtracker.model;

import lombok.AllArgsConstructor;
import lombok.Data;
import lombok.NoArgsConstructor;

import java.util.ArrayList;
import java.util.List;

/**
 * ItemSet - A collection of items that can be lent/borrowed together as a set.
 * Examples: Full armor sets, gear loadouts, boss gear packages, etc.
 */
@Data
@NoArgsConstructor
@AllArgsConstructor
public class ItemSet {

    private String id;
    private String name;
    private String description;
    private String groupId;
    private List<ItemSetEntry> items = new ArrayList<>();

    /**
     * Inner class representing a single item in the set
     */
    @Data
    @NoArgsConstructor
    @AllArgsConstructor
    public static class ItemSetEntry {
        private int itemId;
        private String itemName;
        private int quantity;
        private long value; // Per-item value

        public ItemSetEntry(int itemId, String itemName, int quantity) {
            this.itemId = itemId;
            this.itemName = itemName;
            this.quantity = quantity;
            this.value = 0;
        }
    }
}

package com.guess34.lendingtracker.model;

import lombok.AllArgsConstructor;
import lombok.Data;
import lombok.NoArgsConstructor;

import java.security.SecureRandom;
import java.util.*;
import java.util.concurrent.CopyOnWriteArrayList;

@Data
@NoArgsConstructor
@AllArgsConstructor
public class LendingGroup {
    private String id;
    private String name;
    private String description;
    private String inviteCode; // Single-use group code (one per person)
    private String clanCode; // Multi-use clan code
    private boolean clanCodeEnabled = true;
    // When the single-use code was generated (epoch millis). The relay expires
    // stored codes after 24h, so past that the code is dead everywhere — the UI
    // shows EXPIRED and hasActiveInviteCode() stops matching it.
    private long inviteCodeGeneratedAt;
    // Who redeemed the last single-use code (display name), so staff on every
    // machine see "USED by X" instead of a code that silently vanished.
    private String inviteCodeUsedByName;
    // Version stamp for ALL code state above + clanCode/clanCodeEnabled. Code
    // state is GROUP data: every staff member must see the same code and the
    // same open/closed status. Newer stamp wins wholesale on sync, so a joiner
    // consuming a code, or one staff member rotating it, propagates to all.
    private long codeStateUpdatedAt;
    private Set<String> usedGroupCodes = new HashSet<>(); // Track who used group codes
    private int clanCodeUseCount = 0; // Track clan code usage
    // Who used the multi-use group code (lower-cased names). Unlike the raw count,
    // a name set union-merges cleanly across machines, so the owner sees joins that
    // happened on other clients. The count is kept in step for display.
    private Set<String> clanCodeUsedBy = new HashSet<>();
    // Kick tombstones: lower-cased name -> when they were removed (epoch millis).
    // Roster sync only ever ADDS members (so a stale peer can't erase a fresh
    // join); these tombstones are how a kick propagates without reopening that
    // hole. A member is dropped when a tombstone is NEWER than their joinedAt;
    // re-joining after a kick gets a fresh joinedAt and survives.
    private Map<String, Long> removedMembers = new HashMap<>();
    // CopyOnWriteArrayList: the roster is read on the EDT while sync threads may
    // add members, so reads must never throw ConcurrentModificationException.
    private List<GroupMember> members = new CopyOnWriteArrayList<>();

    // Version stamp for the roster, epoch millis. A relayed group state only
    // replaces the local roster when its stamp is newer, so a member with a
    // stale roster can't erase someone who just joined on another client.
    private long membersUpdatedAt;

    // Set when the group is disbanded. Additive fields, so a client that
    // predates them simply ignores both and still honours the disband -
    // the roster arrives empty with everyone tombstoned, which the existing
    // union merge already understands.
    private long disbandedAt;
    private String disbandedBy;

    // The player who created this group. A group may have up to 5 owners, and
    // owners can promote each other but never DEMOTE each other - without a
    // founder a single rogue owner could promote allies without limit and nobody
    // could undo it. The founder is the one member who can demote an owner, and
    // cannot themselves be demoted. Null on groups made before this existed;
    // backfilled to the sole owner on load.
    private String founderName;

    // Version stamp for founderName alone. It must NOT ride membersUpdatedAt: that
    // is bumped by every roster action (join, kick, role change, permission toggle,
    // invite redemption), so a peer who merely flipped a checkbox would out-stamp a
    // founder transfer and silently restore the previous founder. Set only where the
    // founder actually changes.
    private long founderUpdatedAt;

    // ADDED: Shared secret for HMAC-SHA256 message signing on relay sync
    private String syncSecret;

    // The group's Discord webhook, set by staff in the group settings. Sealed with
    // a key derived from syncSecret (see WebhookSeal): the relay stores group JSON
    // where anyone who knows the group id can read it, and a webhook link lets
    // whoever holds it post in that channel. Members hold the key; nobody else
    // does, the relay included. Its own stamp, newest wins; an empty value with a
    // newer stamp means it was removed. Clients that predate it drop these fields
    // when they relay the group, which the stamp makes harmless - absence never
    // clears it.
    private String webhookSealed;
    private long webhookUpdatedAt;
    private String webhookSetBy;
    // The webhookUpdatedAt the "connected" test was sent for. Equal means the
    // current webhook has been tested, so the Test button locks for all staff
    // until the webhook changes. Merged by max: a value from an older webhook is
    // always smaller than the current stamp, so it can't lock a new one.
    private long webhookTestedFor;

    // The in-game clan this group belongs to, chosen by staff - independent of the
    // group's own name. Lets members recognise clan-mates who can't run the plugin
    // (mobile players) from the game's own clan list. Public information, so not
    // sealed. Same newest-stamp-wins rule as the webhook.
    private String linkedClan;
    private long linkedClanUpdatedAt;
    private String linkedClanSetBy;

    // Whose loans this group tracks and posts: "CLAN" (both players in the linked
    // clan), "GROUP" (both in this group) or "ANYONE". Chosen by staff. Null on
    // groups that predate it, which read as CLAN when a clan is linked and ANYONE
    // otherwise - exactly how they behaved before. Newest stamp wins.
    private String loanScope;
    private long loanScopeUpdatedAt;

    // Permission settings - which roles can kick members
    // Default: co-owner, admin, mod can all kick (true)
    private boolean coOwnerCanKick = true;
    private boolean adminCanKick = true;
    private boolean modCanKick = true;

    // Permission settings - which roles can generate invite codes
    // Default: co-owner and admin can generate (true), mod cannot (false)
    private boolean coOwnerCanInvite = true;
    private boolean adminCanInvite = true;
    private boolean modCanInvite = false;

    public LendingGroup(String id, String name, String description) {
        this.id = id;
        this.name = name;
        this.description = description;
        // FIXED: No auto-generated codes - codes are generated on demand from group settings
        this.inviteCode = null;
        this.clanCode = null;
        this.clanCodeEnabled = false;
        this.usedGroupCodes = new HashSet<>();
        this.clanCodeUseCount = 0;
        this.members = new CopyOnWriteArrayList<>();
        // ADDED: Generate sync secret for HMAC message signing
        this.syncSecret = generateSyncSecret();
        // Default kick permissions - all staff can kick
        this.coOwnerCanKick = true;
        this.adminCanKick = true;
        this.modCanKick = true;
        // Default invite permissions - co-owner and admin can invite, mod cannot
        this.coOwnerCanInvite = true;
        this.adminCanInvite = true;
        this.modCanInvite = false;
    }

    // Generate formatted code like "ABC-123-XYZ"
    private String generateFormattedCode() {
        String uuid = UUID.randomUUID().toString().replace("-", "").toUpperCase();
        return uuid.substring(0, 3) + "-" + uuid.substring(3, 6) + "-" + uuid.substring(6, 9);
    }

    // Matches the relay's stored-code TTL: past this the code is dead everywhere.
    public static final long INVITE_CODE_TTL_MS = 24L * 60 * 60 * 1000;

    /** Stamp the code state so this change wins over older state on sync. */
    public void touchCodeState() {
        this.codeStateUpdatedAt = System.currentTimeMillis();
    }

    /**
     * Generate a new single-use invite code.
     * This code will be voided after one person uses it.
     */
    public String generateSingleUseCode() {
        this.inviteCode = generateFormattedCode();
        this.inviteCodeGeneratedAt = System.currentTimeMillis();
        this.inviteCodeUsedByName = null;
        // Clear previous code usage since this is a new code
        this.usedGroupCodes.clear();
        touchCodeState();
        return this.inviteCode;
    }

    /**
     * Mark invite code as used by a player.
     * Single-use codes become void after use - the code is cleared.
     */
    public void markGroupCodeUsed(String playerName) {
        usedGroupCodes.add(playerName.toLowerCase());
        // FIXED: Single-use code - void the code after use
        this.inviteCode = null;
        this.inviteCodeUsedByName = playerName;
        touchCodeState();
    }

    /**
     * Check if an invite code is currently active: present AND younger than the
     * relay's 24h expiry. Codes saved before the generated-at field existed
     * deserialize to 0 and read as expired — correct, since their relay copy is
     * long gone and only a stale local shortcut could still match them.
     */
    public boolean hasActiveInviteCode() {
        return this.inviteCode != null && !this.inviteCode.isEmpty()
            && this.inviteCodeGeneratedAt > 0
            && System.currentTimeMillis() - this.inviteCodeGeneratedAt < INVITE_CODE_TTL_MS;
    }

    /** The single-use code exists but has aged past the relay's 24h expiry. */
    public boolean isInviteCodeExpired() {
        return this.inviteCode != null && !this.inviteCode.isEmpty() && !hasActiveInviteCode();
    }

    public void addMember(GroupMember member) {
        if (!hasMember(member.getName())) {
            members.add(member);
        }
        // A (re)join always clears any old kick tombstone for this name, so a
        // legitimately re-invited member isn't immediately re-removed by sync.
        clearRemoval(member.getName());
    }

    public void removeMember(String memberName) {
        members.removeIf(m -> m.getName().equalsIgnoreCase(memberName));
    }

    /** Record a kick tombstone so the removal propagates across machines. */
    /** Names appear with spaces or underscores; key tombstones on one form. */
    private static String nameKey(String s) {
        return s == null ? null : s.toLowerCase().replace('_', ' ').trim();
    }

    public void recordRemoval(String memberName) {
        if (memberName == null || memberName.isEmpty()) return;
        if (removedMembers == null) removedMembers = new HashMap<>();
        removedMembers.put(nameKey(memberName), System.currentTimeMillis());
    }

    /**
     * Record a removal at a GIVEN time rather than now.
     *
     * A tombstone only removes a member when it is newer than their joinedAt, and
     * those two stamps come from different machines. Disbanding needs to outrank
     * every member at once, including anyone whose clock ran ahead of the
     * disbander's - otherwise they quietly survive it and keep the group.
     */
    public void recordRemovalAt(String memberName, long at) {
        if (memberName == null || memberName.isEmpty()) return;
        if (removedMembers == null) removedMembers = new HashMap<>();
        removedMembers.merge(nameKey(memberName), at, Math::max);
    }

    /** Drop the kick tombstone for a name (member re-joined). */
    public void clearRemoval(String memberName) {
        if (memberName == null || removedMembers == null) return;
        removedMembers.remove(nameKey(memberName));
    }

    /** Null-safe view of the kick tombstones (name may predate this field in saved data). */
    public Map<String, Long> getRemovedMembersSafe() {
        return removedMembers != null ? removedMembers : Collections.emptyMap();
    }

    /**
     * Record that a player used the multi-use group code. Tracked as a name set so
     * it survives cross-machine merges; the display count follows the set size
     * (same person re-joining doesn't double-count).
     */
    public void recordClanCodeUse(String playerName) {
        if (playerName == null || playerName.isEmpty()) return;
        if (clanCodeUsedBy == null) clanCodeUsedBy = new HashSet<>();
        clanCodeUsedBy.add(playerName.toLowerCase());
        clanCodeUseCount = Math.max(clanCodeUseCount, clanCodeUsedBy.size());
    }

    /** Null-safe view of who used the group code. */
    public Set<String> getClanCodeUsedBySafe() {
        return clanCodeUsedBy != null ? clanCodeUsedBy : Collections.emptySet();
    }

    public boolean hasMember(String memberName) {
        return members.stream()
            .anyMatch(m -> m.getName().equalsIgnoreCase(memberName));
    }

    // ADDED: Generate a cryptographically random sync secret (32 bytes, hex-encoded)
    private static String generateSyncSecret() {
        byte[] bytes = new byte[32];
        new SecureRandom().nextBytes(bytes);
        StringBuilder sb = new StringBuilder(64);
        for (byte b : bytes) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }

    /**
     * Ensure this group has a sync secret.
     * Call this on groups loaded from config that were created before HMAC was added.
     */
    public void ensureSyncSecret() {
        if (syncSecret == null || syncSecret.isEmpty()) {
            syncSecret = generateSyncSecret();
        }
    }
}

package com.guess34.lendingtracker.model;

import lombok.Data;
import lombok.NoArgsConstructor;

/**
 * A direct lending request between two group members:
 * either a borrow request (borrower asks a lender for an item)
 * or a lend offer (lender offers an item to someone looking for it).
 *
 * Requests are stored in the per-group data snapshot so they sync
 * across machines through the relay and reach recipients who were
 * offline when the request was made.
 */
@Data
@NoArgsConstructor
public class LendingRequest
{
	public static final String TYPE_BORROW_REQUEST = "BORROW_REQUEST";
	public static final String TYPE_LEND_OFFER = "LEND_OFFER";
	// Loan-removal governance: MUTUAL = the loan's counterparty must approve
	// (first course of action); STAFF = an uninvolved owner/co-owner adjudicates,
	// only for loans whose counterparty was never a group member (mobile/no-plugin
	// borrowers) or as escalation after a mutual request failed.
	public static final String TYPE_REMOVAL_MUTUAL = "REMOVAL_MUTUAL";
	public static final String TYPE_REMOVAL_STAFF = "REMOVAL_STAFF";
	// A "Looking For" post: addressed to nobody (to = ""), visible to the whole
	// group. These used to live only in the poster's own config, so nobody else
	// ever saw them. Riding on requests gets them synced, expired after two weeks
	// and pruned like everything else. Older clients only ever list requests
	// addressed to them or sent by them, so they carry these without showing them.
	public static final String TYPE_LOOKING_FOR = "LOOKING_FOR";

	public static final String STATUS_PENDING = "PENDING";
	public static final String STATUS_ACCEPTED = "ACCEPTED";
	public static final String STATUS_DECLINED = "DECLINED";
	public static final String STATUS_CANCELLED = "CANCELLED";

	private String id;
	private String groupId;
	private String type;         // one of the TYPE_* constants
	private String from;         // player who created the request
	private String to;           // player the request is addressed to ("" for staff review)
	private String entryId;      // the loan this request refers to (removal types)
	private String itemName;
	private int itemId;
	private int quantity;
	private int durationDays;
	private String message;
	private String status;       // STATUS_* constants
	// Cancelled because nobody ever answered it, rather than because somebody
	// decided to. A separate flag rather than a new STATUS_ value on purpose:
	// a status they don't recognise makes older clients announce "declined your
	// request", inventing a decision nobody made. An unknown FIELD they simply
	// ignore, and they read the status as a plain cancellation, which is true.
	private boolean expired;
	private long createdAt;
	private long updatedAt;

	public boolean isPending()
	{
		return STATUS_PENDING.equals(status);
	}

	public boolean isBorrowRequest()
	{
		return TYPE_BORROW_REQUEST.equals(type);
	}

	public boolean isRemoval()
	{
		return TYPE_REMOVAL_MUTUAL.equals(type) || TYPE_REMOVAL_STAFF.equals(type);
	}

	public boolean isLookingFor()
	{
		return TYPE_LOOKING_FOR.equals(type);
	}

	public boolean isStaffRemoval()
	{
		return TYPE_REMOVAL_STAFF.equals(type);
	}
}

package com.guess34.lendingtracker.model;

import lombok.AllArgsConstructor;
import lombok.Data;
import lombok.NoArgsConstructor;

/**
 * Core lending data model.
 */
@Data
@NoArgsConstructor
@AllArgsConstructor
public class LendingEntry {

    // Core identity
    private String id;

    // Players
    private String lender;
    private String borrower;

    // Item
    private String item;
    private int itemId;
    private int quantity;

    // Value / collateral
    private long value;
    private Integer collateralValue;
    private String collateralType;
    private String collateralItems;
    // Machine-readable collateral: "itemId:qty,itemId:qty". Lets the guards treat
    // collateral the lender is holding like borrowed items (the lender is
    // responsible for it until the loan settles). collateralItems above is the
    // human-readable label only.
    private String collateralItemIds;
    private boolean agreedNoCollateral;

    // Group / party
    private String groupId;

    // Time fields (epoch millis)
    private long lendTime;
    private long dueTime;
    private long returnedAt;

    // Last time this row was mutated, epoch millis. Drives last-write-wins
    // reconciliation when the same entry arrives from another client via sync.
    private long updatedAt;

    // --- Running-tally return tracking ---
    // A loan settles piece by piece: the borrower owes the lent item(s) back, and
    // the lender owes the collateral back. Each completed trade decrements
    // whatever actually came home, on either side; the loan only closes when BOTH
    // sides reach zero. All three are wrappers so records saved before this
    // feature deserialize to null and the accessors below fall back to the old
    // all-or-nothing semantics — no migration, no broken saved data.
    private Integer lentOutstanding;         // qty of the lent item still with the borrower
    private String collateralOutstandingIds; // "itemId:qty,..." still held by the lender
    private Long collateralGpOutstanding;    // GP collateral still held by the lender

    // Lender chose a one-time loan: recorded and tracked like any loan, but the
    // item is never (re)listed on the marketplace when it comes home.
    private Boolean oneTime;

    // Misc
    private String notes;

    // Item set this listing belongs to, if any. Both live on the listing itself,
    // not in a separate set record: a set is simply whichever listings carry the
    // same setId, so lending one piece out delists only that piece and the rest
    // stay a set. The name rides along so peers need nothing else to draw it.
    // New fields, not a new status - clients that predate sets ignore them and
    // show the pieces as ordinary listings.
    private String setId;
    private String setName;

    // The BORROWER's client keeps this loan: the lender can't run the plugin (a
    // clan-mate on mobile, say) so theirs can't record it, track its returns or
    // post it. Exactly one client is ever the keeper - the lender's normally,
    // the borrower's for these - so nothing is counted twice. A field, not a
    // status; the merge treats it as a one-way latch because clients that predate
    // it drop it when they relay the row.
    private Boolean keptByBorrower;

    // Convenience

    public long getDueDate() { return this.dueTime; }
    public long getLendDate() { return this.lendTime; }
    public boolean isReturned() { return this.returnedAt > 0; }

    // --- Null-safe outstanding accessors (legacy records fall back to the old
    // all-or-nothing model: everything outstanding while active, nothing after) ---

    /** Quantity of the lent item the borrower still holds. */
    public int outstandingLentQty() {
        if (lentOutstanding != null) return Math.max(0, lentOutstanding);
        return isReturned() ? 0 : Math.max(1, quantity);
    }

    /** Collateral items ("itemId:qty,...") the lender still holds. Empty = none. */
    public String outstandingCollateralIds() {
        if (collateralOutstandingIds != null) return collateralOutstandingIds;
        if (isReturned()) return "";
        return collateralItemIds != null ? collateralItemIds : "";
    }

    /** GP collateral the lender still holds. */
    public long outstandingCollateralGp() {
        if (collateralGpOutstanding != null) return Math.max(0, collateralGpOutstanding);
        if (isReturned()) return 0;
        return collateralValue != null && "GP".equals(collateralType) ? Math.max(0, collateralValue) : 0;
    }

    /**
     * Close out every running tally. Archiving sets returnedAt, but the
     * outstanding accessors only fall back to the returned-means-zero shortcut
     * when the field is NULL - so a partially-returned loan archived with 2 still
     * outstanding reported 2 forever, and anything asking "is this settled?" said
     * no for the rest of time. Call this wherever an entry is archived.
     */
    public void markSettled() {
        this.lentOutstanding = 0;
        this.collateralOutstandingIds = "";
        this.collateralGpOutstanding = 0L;
    }

    /** True when nothing is outstanding on EITHER side — item home AND collateral home. */
    public boolean isFullySettled() {
        return outstandingLentQty() == 0
            && outstandingCollateralIds().isEmpty()
            && outstandingCollateralGp() == 0;
    }

    public boolean isOneTimeLoan() { return Boolean.TRUE.equals(oneTime); }

    public boolean isInSet() { return setId != null && !setId.isEmpty(); }

    public boolean isKeptByBorrower() { return Boolean.TRUE.equals(keptByBorrower); }

    public boolean isOverdue() {
        return returnedAt == 0 && dueTime > 0 && System.currentTimeMillis() > dueTime;
    }

    public LendingEntry(LendingEntry other) {
        if (other == null) return;
        this.id = other.id;
        this.lender = other.lender;
        this.borrower = other.borrower;
        this.item = other.item;
        this.itemId = other.itemId;
        this.quantity = other.quantity;
        this.value = other.value;
        this.collateralValue = other.collateralValue;
        this.collateralType = other.collateralType;
        this.collateralItems = other.collateralItems;
        this.collateralItemIds = other.collateralItemIds;
        this.agreedNoCollateral = other.agreedNoCollateral;
        this.groupId = other.groupId;
        this.lendTime = other.lendTime;
        this.dueTime = other.dueTime;
        this.returnedAt = other.returnedAt;
        this.updatedAt = other.updatedAt;
        this.lentOutstanding = other.lentOutstanding;
        this.collateralOutstandingIds = other.collateralOutstandingIds;
        this.collateralGpOutstanding = other.collateralGpOutstanding;
        this.oneTime = other.oneTime;
        this.notes = other.notes;
        this.setId = other.setId;
        this.setName = other.setName;
        this.keptByBorrower = other.keptByBorrower;
    }

    public String getPlayerName() { return borrower != null ? borrower : lender; }
    public String getItemName() { return item; }
    public void setItemName(String name) { this.item = name; }
}

package com.guess34.lendingtracker.services;

import java.util.Collections;
import java.util.HashSet;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.clan.ClanMember;
import net.runelite.api.clan.ClanSettings;
import net.runelite.client.util.Text;

/**
 * The player's in-game clan roster, as the game itself reports it: every member,
 * on any platform, mobile included. Read locally - nothing is fetched from
 * anywhere - which is what lets a group recognise clan members who can't run
 * the plugin.
 *
 * The game only exposes the clan the player is IN, so a member's client can only
 * vouch for the clan it belongs to; asked about any other clan it says "unknown",
 * never "no".
 */
@Singleton
public class ClanRoster
{
	/** Answer to "is this player in that clan?" */
	public enum Membership { YES, NO, UNKNOWN }

	private final Client client;

	private volatile String clanName;
	private volatile Set<String> members = Collections.emptySet();

	@Inject
	public ClanRoster(Client client)
	{
		this.client = client;
	}

	/** Re-read the roster. Client thread only. */
	public void refresh()
	{
		ClanSettings settings = client.getClanSettings();
		if (settings == null || settings.getName() == null)
		{
			clanName = null;
			members = Collections.emptySet();
			return;
		}
		Set<String> names = new HashSet<>();
		for (ClanMember m : settings.getMembers())
		{
			if (m != null && m.getName() != null)
			{
				names.add(key(m.getName()));
			}
		}
		members = Collections.unmodifiableSet(names);
		clanName = Text.removeTags(settings.getName()).replace('\u00A0', ' ').trim();
	}

	/** Has the game given us this player's clan list yet? */
	public boolean isLoaded()
	{
		return clanName != null;
	}

	/** The clan this player is in right now, or null. */
	public String currentClanName()
	{
		return clanName;
	}

	/** Is player in the named clan, as far as this client can tell? */
	public Membership check(String clan, String player)
	{
		String mine = clanName;
		if (clan == null || clan.trim().isEmpty() || player == null || mine == null
			|| !mine.equalsIgnoreCase(clan.trim()))
		{
			return Membership.UNKNOWN;
		}
		return members.contains(key(player)) ? Membership.YES : Membership.NO;
	}

	// Jagex treats spaces, underscores, hyphens and non-breaking spaces in a name
	// as the same character, and names are case-insensitive.
	private static String key(String name)
	{
		return Text.toJagexName(Text.removeTags(name)).toLowerCase();
	}
}

package com.guess34.lendingtracker.services;

import java.nio.ByteBuffer;
import java.nio.charset.StandardCharsets;
import java.security.SecureRandom;
import java.util.Base64;
import javax.crypto.Cipher;
import javax.crypto.Mac;
import javax.crypto.spec.GCMParameterSpec;
import javax.crypto.spec.SecretKeySpec;

/**
 * Locks a group's Discord webhook link with the group's own key, so it can travel
 * inside the group's synced data without the relay - or anyone who fetches the
 * group's stored record - being able to read it.
 *
 * The key is derived from the group's syncSecret, which only members hold (it
 * reaches a joiner through their invite). AES-GCM, so a tampered value fails to
 * open instead of opening to something else.
 */
final class WebhookSeal
{
	private static final String PREFIX = "v1:";
	private static final int IV_BYTES = 12;
	private static final int TAG_BITS = 128;
	private static final SecureRandom RANDOM = new SecureRandom();

	private WebhookSeal()
	{
	}

	/** The sealed form of url, or null if it can't be sealed. */
	static String seal(String url, String syncSecret)
	{
		if (url == null || syncSecret == null || syncSecret.isEmpty())
		{
			return null;
		}
		try
		{
			byte[] iv = new byte[IV_BYTES];
			RANDOM.nextBytes(iv);
			Cipher cipher = Cipher.getInstance("AES/GCM/NoPadding");
			cipher.init(Cipher.ENCRYPT_MODE, key(syncSecret), new GCMParameterSpec(TAG_BITS, iv));
			byte[] sealed = cipher.doFinal(url.getBytes(StandardCharsets.UTF_8));
			byte[] out = ByteBuffer.allocate(iv.length + sealed.length).put(iv).put(sealed).array();
			return PREFIX + Base64.getEncoder().encodeToString(out);
		}
		catch (Exception e)
		{
			return null;
		}
	}

	/** The url inside, or null if it is empty, damaged, or sealed with another key. */
	static String open(String sealed, String syncSecret)
	{
		if (sealed == null || !sealed.startsWith(PREFIX) || syncSecret == null || syncSecret.isEmpty())
		{
			return null;
		}
		try
		{
			byte[] all = Base64.getDecoder().decode(sealed.substring(PREFIX.length()));
			if (all.length <= IV_BYTES)
			{
				return null;
			}
			Cipher cipher = Cipher.getInstance("AES/GCM/NoPadding");
			cipher.init(Cipher.DECRYPT_MODE, key(syncSecret), new GCMParameterSpec(TAG_BITS, all, 0, IV_BYTES));
			byte[] url = cipher.doFinal(all, IV_BYTES, all.length - IV_BYTES);
			return new String(url, StandardCharsets.UTF_8);
		}
		catch (Exception e)
		{
			return null;
		}
	}

	// A key of its own, derived from the group secret, so the webhook seal and
	// the message signatures never share one.
	private static SecretKeySpec key(String syncSecret) throws Exception
	{
		Mac mac = Mac.getInstance("HmacSHA256");
		mac.init(new SecretKeySpec(syncSecret.getBytes(StandardCharsets.UTF_8), "HmacSHA256"));
		byte[] derived = mac.doFinal("lending-tracker/discord-webhook".getBytes(StandardCharsets.UTF_8));
		return new SecretKeySpec(derived, "AES");
	}
}

package com.guess34.lendingtracker.services;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import lombok.extern.slf4j.Slf4j;
import okhttp3.*;

import com.guess34.lendingtracker.LendingTrackerConfig;

import javax.crypto.Mac;
import javax.crypto.spec.SecretKeySpec;
import javax.inject.Inject;
import javax.inject.Singleton;
import java.nio.charset.StandardCharsets;
import java.util.concurrent.*;
import java.util.function.Consumer;

/**
 * Manages WebSocket connection to the relay server for cross-machine group sync.
 * Also provides REST methods for invite code create/lookup/consume.
 *
 * ADDED: HMAC-SHA256 message signing and verification to prevent forged sync events.
 * Every outgoing sync message includes a signature computed from the group's shared secret.
 * Incoming messages are verified before being passed to the event handler.
 */
@Slf4j
@Singleton
public class RelaySyncService
{
	private static final int CLOSE_NORMAL = 1000;
	private static final long INITIAL_RECONNECT_DELAY_MS = 1000;
	private static final long MAX_RECONNECT_DELAY_MS = 30000;
	private static final MediaType JSON_MEDIA = MediaType.parse("application/json; charset=utf-8");
	private static final String HMAC_ALGORITHM = "HmacSHA256";
	// Max age for sync messages, a coarse replay/ancient-message bound. Kept
	// generous (24h) because timestamps are the sender's wall clock: a tight
	// window silently dropped ALL live sync between members whose clocks differed
	// by more than a few minutes. Fine-grained replay of state is additionally
	// blocked by the per-publisher monotonic timestamp gate below.
	private static final long MAX_MESSAGE_AGE_MS = 24L * 60 * 60 * 1000;

	// Newest state timestamp APPLIED per "groupId:publisher". A state strictly older
	// than this is dropped as a replay — the timestamp is inside the signed payload,
	// so a captured old signed snapshot can't be re-injected to revert a publisher's
	// marketplace/lent rows (applyPublisherRows adopts the publisher's rows
	// wholesale, so it has no per-row recency of its own).
	private final java.util.concurrent.ConcurrentHashMap<String, Long> lastStateTs =
		new java.util.concurrent.ConcurrentHashMap<>();
	// Content hash of the last state applied per "groupId:publisher", so an IDENTICAL
	// repeat (the re-announce burst when a member joins, or the periodic heartbeat)
	// is skipped without reprocessing. Recorded only AFTER a best-effort apply so a
	// failed apply doesn't permanently dedup the publisher's retry.
	private final java.util.concurrent.ConcurrentHashMap<String, Integer> lastStateHash =
		new java.util.concurrent.ConcurrentHashMap<>();
	// Keepalive cadence: ping ~every 12 min, never sooner than 2 min apart
	private static final long KEEPALIVE_INTERVAL_MS = 12 * 60 * 1000;
	private static final long KEEPALIVE_MIN_DELAY_MS = 2 * 60 * 1000;
	// Websocket ping cadence. Keeps the relay socket warm (so it isn't idle-closed)
	// and lets OkHttp detect a dead socket and fail over to a reconnect.
	private static final long WS_PING_INTERVAL_S = 25;
	// Render free tier takes 30-60s to wake from spindown — shared OkHttpClient's
	// default 10s timeout would give up before the server responds, so the
	// REST client used for relay calls needs its own longer timeouts.
	private static final long REST_CONNECT_TIMEOUT_S = 30;
	private static final long REST_READ_TIMEOUT_S = 60;

	@Inject private OkHttpClient httpClient;
	@Inject private Gson gson;
	@Inject private LendingTrackerConfig config;

	// Serializes every transition of webSocket / connected / intentionalClose /
	// reconnectExecutor / reconnectDelay. These are touched from the EDT
	// (connect/disconnect), the OkHttp ws-callback thread (onOpen/onClosing/
	// onFailure), and the reconnect executor thread; without a single lock they
	// race — e.g. a ws-thread close could null a socket a concurrent reconnect just
	// created, or a reconnect could resurrect a socket after an intentional close.
	private final Object connLock = new Object();
	private volatile WebSocket webSocket;
	// The one scheduled reconnect attempt, if any. Guarded by connLock. Cancelled
	// when connect() opens a socket directly so a stale timer can't spawn a second
	// concurrent connection attempt.
	private java.util.concurrent.ScheduledFuture<?> pendingReconnect;
	// Room identity: written by joinRoom/leaveRoom/disconnect (EDT or sync executor)
	// and read on the ws thread (onOpen rejoin, signature verification) — volatile
	// so a join is immediately visible to a concurrently-opening socket.
	private volatile String currentGroupId;
	private volatile String currentPlayerName;
	// Current group's sync secret for HMAC signing
	private volatile String currentSyncSecret;
	private volatile boolean connected = false;
	private volatile boolean intentionalClose = false;
	private long reconnectDelay = INITIAL_RECONNECT_DELAY_MS;
	private ScheduledExecutorService reconnectExecutor;
	private ScheduledExecutorService keepaliveExecutor;
	private volatile OkHttpClient restClient;
	private volatile OkHttpClient wsClient;
	private Consumer<GroupService.SyncEvent> onEventReceived;
	private Consumer<Boolean> onConnectionChanged;
	private StateHandler onStateReceived;
	private volatile Runnable onConnected;
	private volatile Consumer<java.util.Map<String, Integer>> onPresenceReceived;
	// Supplies the local player's current world so the relay can report it to peers
	// as part of presence. Read lazily at each join so a world hop (which triggers a
	// reconnect + rejoin) reports the fresh world.
	private volatile java.util.function.IntSupplier localWorldSupplier;

	/** Callback for relay state messages (join catch-up or live broadcast). */
	@FunctionalInterface
	public interface StateHandler
	{
		void accept(String groupJson, String dataJson, String publisher);
	}

	// --- Connection Lifecycle ---

	/**
	 * True while a connection attempt is in flight or a retry is queued. The relay
	 * sleeps after 15 minutes idle and takes 30-60s to wake, so reporting a flat
	 * "Offline" during that window made a perfectly healthy setup look broken.
	 */
	public boolean isConnecting()
	{
		synchronized (connLock)
		{
			return !connected && !intentionalClose && (webSocket != null || pendingReconnect != null);
		}
	}

	public void connect()
	{
		if (config == null || !config.enableRelaySync()) return;

		String url = config.relayServerUrl();
		if (url == null || url.isEmpty()) return;

		synchronized (connLock)
		{
			// A non-null socket means connected OR a handshake already in flight
			// (onClosing/onFailure/disconnect all null the field under this lock).
			// Skipping the in-flight case matters: at login two triggers call
			// startSync back-to-back, and connecting again during the first
			// attempt's handshake would orphan a socket and churn the relay.
			if (webSocket != null)
			{
				log.debug("Relay already connected/connecting, skipping connect");
				return;
			}

			intentionalClose = false;
			reconnectDelay = INITIAL_RECONNECT_DELAY_MS;

			// We're connecting right now — a previously scheduled retry would only
			// race this attempt and orphan one of the two sockets.
			if (pendingReconnect != null)
			{
				pendingReconnect.cancel(false);
				pendingReconnect = null;
			}

			if (reconnectExecutor == null || reconnectExecutor.isShutdown())
			{
				reconnectExecutor = Executors.newSingleThreadScheduledExecutor();
			}

			doConnectLocked(url);
		}
	}

	/** Open a websocket. MUST be called while holding {@link #connLock}. */
	private void doConnectLocked(String url)
	{
		if (config == null || !config.enableRelaySync()) return;
		// Don't resurrect a socket after an intentional close (a concurrent
		// disconnect() may have set this while a reconnect task was queued).
		if (intentionalClose) return;

		try
		{
			log.debug("Connecting to relay: {}", url);
			Request request = new Request.Builder().url(url).build();
			webSocket = getWsClient().newWebSocket(request, new RelayWebSocketListener());
		}
		catch (Exception e)
		{
			log.warn("Failed to connect to relay: {}", e.getMessage());
			scheduleReconnectLocked();
		}
	}

	public void disconnect()
	{
		WebSocket ws;
		synchronized (connLock)
		{
			intentionalClose = true;
			connected = false;

			// Null the field so any in-flight/stale callback sees ws != webSocket.
			ws = webSocket;
			webSocket = null;
			// Clear the room AND its secret so a socket that somehow (re)opens can't
			// rejoin the group we just left, and a late response for the old group
			// (e.g. an in-flight catch-up fetch) fails signature verification instead
			// of being applied after we've moved on.
			currentGroupId = null;
			currentSyncSecret = null;

			pendingReconnect = null; // shutdownNow below cancels the task itself

			if (reconnectExecutor != null && !reconnectExecutor.isShutdown())
			{
				reconnectExecutor.shutdownNow();
				reconnectExecutor = null;
			}
		}

		// Full teardown (logout / group switch) — the per-publisher dedup floors
		// belong to the room we just left; drop them so they can't grow unbounded
		// across group switches. (The auto-reconnect path never comes through here,
		// so a mid-session reconnect keeps its replay floors.)
		lastStateTs.clear();
		lastStateHash.clear();

		if (ws != null)
		{
			try
			{
				ws.close(CLOSE_NORMAL, "Plugin shutdown");
			}
			catch (Exception ignored) { }
		}

		notifyConnectionChanged(false);
	}

	// --- Room Management ---

	/**
	 * Join a sync room for the given group.
	 * CHANGED: Now accepts syncSecret for HMAC message signing.
	 */
	public void joinRoom(String groupId, String playerName, String syncSecret)
	{
		if (config == null || !config.enableRelaySync()) return;

		// Under connLock so this serializes with onOpen: without it, joinRoom could
		// set the room just after onOpen read a null room, while onOpen flips
		// connected just after we read false — neither side sends the join and the
		// socket sits connected but never in the room (no presence in or out).
		synchronized (connLock)
		{
			this.currentGroupId = groupId;
			this.currentPlayerName = playerName;
			this.currentSyncSecret = syncSecret;

			if (connected && webSocket != null)
			{
				sendJoinMessage(groupId, playerName);
			}
		}
	}

	/**
	 * @deprecated Use {@link #joinRoom(String, String, String)} with syncSecret instead.
	 */
	@Deprecated
	public void joinRoom(String groupId, String playerName)
	{
		joinRoom(groupId, playerName, null);
	}

	private void sendJoinMessage(String groupId, String playerName)
	{
		if (config == null || !config.enableRelaySync()) return;

		WebSocket ws = webSocket;
		if (ws == null) return;

		JsonObject msg = new JsonObject();
		msg.addProperty("type", "join");
		msg.addProperty("groupId", groupId);
		msg.addProperty("playerName", playerName);
		// Report our current world so peers can show it next to our name. Read lazily
		// here so a reconnect after a world hop reports the new world.
		int world = 0;
		try
		{
			java.util.function.IntSupplier supplier = localWorldSupplier;
			if (supplier != null) { world = supplier.getAsInt(); }
		}
		catch (Exception ignored) { /* world stays 0 */ }
		msg.addProperty("world", world);
		ws.send(gson.toJson(msg));
	}

	public void leaveRoom(String groupId)
	{
		if (config == null || !config.enableRelaySync()) return;

		// Under connLock like joinRoom: an unlocked leave could race onOpen's
		// rejoin and re-enter the room being left. ws.send is a non-blocking
		// enqueue, safe under the lock.
		synchronized (connLock)
		{
			if (connected && webSocket != null && groupId != null)
			{
				JsonObject msg = new JsonObject();
				msg.addProperty("type", "leave");
				msg.addProperty("groupId", groupId);
				webSocket.send(gson.toJson(msg));
			}

			if (groupId != null && groupId.equals(currentGroupId))
			{
				currentGroupId = null;
				currentSyncSecret = null;
			}
		}
	}

	// --- Sync Events ---

	/**
	 * Send a sync event to the relay server.
	 * CHANGED: Now signs the event payload with HMAC-SHA256 using the group's sync secret.
	 */
	public void sendEvent(String groupId, GroupService.SyncEvent event)
	{
		if (config == null || !config.enableRelaySync()) return;
		// Cache the volatile field — see leaveRoom for why.
		WebSocket ws = webSocket;
		if (!connected || ws == null || groupId == null) return;

		JsonObject eventJson = gson.toJsonTree(event).getAsJsonObject();

		JsonObject msg = new JsonObject();
		msg.addProperty("type", "sync");
		msg.addProperty("groupId", groupId);
		msg.add("event", eventJson);

		// ADDED: Sign the message if we have a sync secret
		if (currentSyncSecret != null && !currentSyncSecret.isEmpty())
		{
			String payload = buildSignaturePayload(groupId, eventJson);
			String signature = computeHmac(payload, currentSyncSecret);
			if (signature != null)
			{
				msg.addProperty("signature", signature);
			}
		}

		ws.send(gson.toJson(msg));
	}

	public boolean isConnected()
	{
		return connected;
	}

	// --- HMAC Signing & Verification ---

	/**
	 * ADDED: Build the canonical payload string for HMAC signing.
	 * Uses groupId + event type + timestamp + publisher to create a deterministic string.
	 */
	private String buildSignaturePayload(String groupId, JsonObject eventJson)
	{
		String type = eventJson.has("type") ? eventJson.get("type").getAsString() : "";
		String timestamp = eventJson.has("timestamp") ? eventJson.get("timestamp").getAsString() : "0";
		String publisher = eventJson.has("publisher") && !eventJson.get("publisher").isJsonNull()
			? eventJson.get("publisher").getAsString() : "";
		// dataId drives targeted mutations (e.g. archiving a loan by id), so it must
		// be signed too — otherwise a tampered id would pass verification.
		String dataId = eventJson.has("dataId") && !eventJson.get("dataId").isJsonNull()
			? eventJson.get("dataId").getAsString() : "";
		return groupId + ":" + type + ":" + timestamp + ":" + publisher + ":" + dataId;
	}

	/**
	 * ADDED: Compute HMAC-SHA256 signature for the given payload using the shared secret.
	 */
	private String computeHmac(String payload, String secret)
	{
		try
		{
			Mac mac = Mac.getInstance(HMAC_ALGORITHM);
			SecretKeySpec keySpec = new SecretKeySpec(
				secret.getBytes(StandardCharsets.UTF_8), HMAC_ALGORITHM);
			mac.init(keySpec);
			byte[] hmacBytes = mac.doFinal(payload.getBytes(StandardCharsets.UTF_8));

			StringBuilder sb = new StringBuilder(hmacBytes.length * 2);
			for (byte b : hmacBytes)
			{
				sb.append(String.format("%02x", b));
			}
			return sb.toString();
		}
		catch (Exception e)
		{
			log.warn("Failed to compute HMAC: {}", e.getMessage());
			return null;
		}
	}

	/**
	 * ADDED: Verify the HMAC signature on an incoming relay message.
	 * Returns true if the signature is valid, false otherwise.
	 */
	private boolean verifySignature(JsonObject msg, JsonObject eventJson)
	{
		// If we don't have a sync secret, we can't verify — reject the message
		if (currentSyncSecret == null || currentSyncSecret.isEmpty())
		{
			log.warn("Rejecting relay message: no sync secret configured for current group");
			return false;
		}

		// If the message has no signature, reject it
		if (!msg.has("signature"))
		{
			log.warn("Rejecting relay message: missing HMAC signature");
			return false;
		}

		String groupId = msg.has("groupId") ? msg.get("groupId").getAsString() : "";
		String expectedPayload = buildSignaturePayload(groupId, eventJson);
		String expectedSignature = computeHmac(expectedPayload, currentSyncSecret);

		if (expectedSignature == null)
		{
			return false;
		}

		String receivedSignature = msg.get("signature").getAsString();
		// ADDED: Constant-time comparison to prevent timing attacks
		return constantTimeEquals(expectedSignature, receivedSignature);
	}

	/**
	 * ADDED: Constant-time string comparison to prevent timing side-channel attacks.
	 */
	private boolean constantTimeEquals(String a, String b)
	{
		if (a == null || b == null || a.length() != b.length())
		{
			return false;
		}
		int result = 0;
		for (int i = 0; i < a.length(); i++)
		{
			result |= a.charAt(i) ^ b.charAt(i);
		}
		return result == 0;
	}

	/**
	 * ADDED: Check if a sync event's timestamp is within the acceptable window.
	 * Rejects messages older than MAX_MESSAGE_AGE_MS to prevent replay attacks.
	 */
	private boolean isTimestampValid(JsonObject eventJson)
	{
		if (!eventJson.has("timestamp"))
		{
			return false;
		}

		long eventTime = eventJson.get("timestamp").getAsLong();
		long now = System.currentTimeMillis();
		long age = Math.abs(now - eventTime);

		if (age > MAX_MESSAGE_AGE_MS)
		{
			log.warn("Rejecting relay message: timestamp too old (age={}ms, max={}ms)", age, MAX_MESSAGE_AGE_MS);
			return false;
		}

		return true;
	}

	// --- REST: Invite Codes ---

	public void publishInviteCode(String code, String groupId, String groupJson)
	{
		if (config == null || !config.enableRelaySync()) return;

		String baseUrl = getRestBaseUrl();
		if (baseUrl == null)
		{
			log.warn("Cannot publish invite code: relay URL is not configured");
			return;
		}

		log.debug("Publishing invite code {} for group {} to relay at {}", code, groupId, baseUrl);

		JsonObject body = new JsonObject();
		body.addProperty("code", code);
		body.addProperty("groupId", groupId);
		body.addProperty("groupJson", groupJson);

		RequestBody requestBody = RequestBody.create(JSON_MEDIA, body.toString());
		Request request = new Request.Builder()
			.url(baseUrl + "/api/invite")
			.post(requestBody)
			.build();

		getRestClient().newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, java.io.IOException e)
			{
				log.warn("Failed to publish invite code to relay: {}", e.getMessage());
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				if (response.isSuccessful())
				{
					log.debug("Invite code {} published to relay successfully", code);
				}
				else
				{
					log.warn("Relay returned {} when publishing invite code {}", response.code(), code);
				}
				response.close();
			}
		});
	}

	/**
	 * Publish an invite code to the relay SYNCHRONOUSLY, retrying through a Render cold-start.
	 * Returns true only once the relay confirms it stored the code (HTTP 2xx).
	 *
	 * The fire-and-forget {@link #publishInviteCode} could silently fail against a sleeping
	 * server, leaving the owner sharing a code that was never stored - which is exactly why
	 * a freshly generated code could come back "invalid/expired" for a joiner seconds later.
	 * Code generation now uses this and warns the owner if the code did not land.
	 * Blocking - callers must run it off the EDT.
	 */
	public boolean publishInviteBlocking(String code, String groupId, String groupJson)
	{
		if (config == null || !config.enableRelaySync()) return false;

		String baseUrl = getRestBaseUrl();
		if (baseUrl == null)
		{
			log.warn("Cannot publish invite code: relay URL is not configured");
			return false;
		}

		JsonObject body = new JsonObject();
		body.addProperty("code", code);
		body.addProperty("groupId", groupId);
		body.addProperty("groupJson", groupJson);
		RequestBody requestBody = RequestBody.create(JSON_MEDIA, body.toString());
		Request request = new Request.Builder()
			.url(baseUrl + "/api/invite")
			.post(requestBody)
			.build();

		int maxAttempts = 3;
		for (int attempt = 1; attempt <= maxAttempts; attempt++)
		{
			try (Response response = getRestClient().newCall(request).execute())
			{
				if (response.isSuccessful())
				{
					log.debug("Invite code {} published to relay (attempt {})", code, attempt);
					return true;
				}
				log.warn("Publish attempt {} for code {} got HTTP {}", attempt, code, response.code());
			}
			catch (Exception e)
			{
				log.warn("Publish attempt {} for code {} failed: {}", attempt, code, e.getMessage());
			}
			// No delay between attempts: Thread.sleep is not permitted in Plugin Hub plugins, and
			// the REST client's long read timeout already holds the request open through a Render
			// cold-start, so the server's eventual 200 is normally received on the first attempt.
		}
		return false;
	}

	/**
	 * What became of a tombstone publish.
	 *
	 * NOT_SENT  - never reached the wire, so nothing was broadcast to anyone and
	 *             nothing has changed for anybody. The only safe abort point.
	 * SENT      - on the wire, but we could not verify the server stored it. Every
	 *             member who was online has already dropped the group; members who
	 *             were offline read the stored record, so they may not.
	 * CONFIRMED - on the wire and our tombstone is what the server holds.
	 */
	public enum PublishOutcome { NOT_SENT, SENT, CONFIRMED }

	/**
	 * Publish a group tombstone and find out how completely it took effect.
	 *
	 * dataJson is deliberately null - a disbanded group publishes no listings, no
	 * loans and no requests, so the stored record keeps nothing but the tombstone.
	 *
	 * The confirmation checks that OUR tombstone is the stored record, not merely
	 * that something newer exists. Comparing timestamps alone passes on any peer's
	 * heartbeat that crossed ours - and on our own, since this client keeps
	 * publishing state on a timer throughout - which would report success for a
	 * tombstone that was overwritten moments later.
	 *
	 * Blocking - callers must run it off the EDT.
	 */
	public PublishOutcome publishTombstoneBlocking(String groupId, String tombstoneJson, String publisher)
	{
		long sentAt = publishState(groupId, tombstoneJson, null, publisher);
		if (sentAt == 0L)
		{
			log.warn("Could not publish the tombstone for group {}: not connected", groupId);
			return PublishOutcome.NOT_SENT;
		}

		String baseUrl = getRestBaseUrl();
		if (baseUrl == null) return PublishOutcome.SENT;

		for (int attempt = 1; attempt <= 3; attempt++)
		{
			try
			{
				// Built inside the try: a malformed relay URL throws here, and an
				// escape would leak past the caller's bookkeeping after the
				// tombstone has already gone out.
				Request request = new Request.Builder()
					.url(baseUrl + "/api/state/" + groupId).get().build();
				try (Response response = getRestClient().newCall(request).execute())
				{
					if (response.isSuccessful() && response.body() != null)
					{
						if (storedRecordIsTombstone(response.body().string(), publisher))
						{
							log.debug("Tombstone for group {} confirmed stored (attempt {})", groupId, attempt);
							return PublishOutcome.CONFIRMED;
						}
						log.debug("Stored record for group {} is not our tombstone yet (attempt {})",
							groupId, attempt);
					}
					else
					{
						log.warn("Tombstone check for group {} got HTTP {}", groupId, response.code());
					}
				}
			}
			catch (Exception e)
			{
				log.warn("Tombstone check {} for group {} failed: {}", attempt, groupId, e.getMessage());
			}
		}
		return PublishOutcome.SENT;
	}

	/** Is the server holding a disband tombstone published by this player? */
	private boolean storedRecordIsTombstone(String body, String publisher)
	{
		try
		{
			JsonObject stored = gson.fromJson(body, JsonObject.class);
			if (stored == null || !stored.has("groupJson") || stored.get("groupJson").isJsonNull())
			{
				return false;
			}
			if (publisher != null && stored.has("publisher") && !stored.get("publisher").isJsonNull()
				&& !publisher.equalsIgnoreCase(stored.get("publisher").getAsString()))
			{
				return false;
			}
			JsonObject group = gson.fromJson(stored.get("groupJson").getAsString(), JsonObject.class);
			if (group == null || !group.has("disbandedAt") || group.get("disbandedAt").isJsonNull())
			{
				return false;
			}
			return group.get("disbandedAt").getAsLong() > 0;
		}
		catch (Exception e)
		{
			log.debug("Could not read the stored record back: {}", e.getMessage());
			return false;
		}
	}

	/**
	 * Outcome of a relay invite-code lookup.
	 * FOUND       - code exists, groupJson populated
	 * NOT_FOUND   - relay responded 404 (code invalid/expired/consumed)
	 * UNREACHABLE - relay not configured, timed out, or returned a server error
	 *               (e.g. Render cold-start exceeded the timeout) - worth retrying
	 */
	public enum InviteStatus { FOUND, NOT_FOUND, UNREACHABLE }

	public static final class InviteLookupResult
	{
		public final InviteStatus status;
		public final String groupJson;

		public InviteLookupResult(InviteStatus status, String groupJson)
		{
			this.status = status;
			this.groupJson = groupJson;
		}
	}

	/**
	 * Look up an invite code on the relay, distinguishing "not found" from "couldn't reach
	 * the server". The old String-returning lookupInviteCode collapsed both into null, so a
	 * cold-start timeout looked identical to a genuinely invalid code.
	 */
	/**
	 * Joining hits a single blocking call, and the relay sleeps after 15 minutes
	 * idle - so the first person to touch it waits out a 30-60s cold start. One
	 * attempt meant a join simply failed while the server was waking up. Retry a
	 * few times before giving up; only a genuinely unreachable relay should read
	 * as unreachable.
	 */
	public InviteLookupResult lookupInvite(String code)
	{
		// No sleep between attempts: Thread.sleep is not permitted in Plugin Hub
		// plugins, and the REST client already carries a 30s connect / 60s read
		// timeout which holds the request open right through a Render cold start.
		// Retrying immediately covers the case where the first call fails outright
		// (socket refused while the instance is still spinning up) rather than
		// waiting - the same pattern publishInviteBlocking already uses.
		InviteLookupResult result = lookupInviteOnce(code);
		for (int attempt = 1; attempt < 4 && result.status == InviteStatus.UNREACHABLE; attempt++)
		{
			log.debug("Invite lookup retry {} (relay may be cold-starting)", attempt);
			result = lookupInviteOnce(code);
		}
		return result;
	}

	private InviteLookupResult lookupInviteOnce(String code)
	{
		if (config == null || !config.enableRelaySync()) return new InviteLookupResult(InviteStatus.UNREACHABLE, null);

		String baseUrl = getRestBaseUrl();
		if (baseUrl == null)
		{
			log.warn("Cannot lookup invite code: relay URL is not configured");
			return new InviteLookupResult(InviteStatus.UNREACHABLE, null);
		}

		log.debug("Looking up invite code {} from relay at {}", code, baseUrl);

		Request request = new Request.Builder()
			.url(baseUrl + "/api/invite/" + code)
			.get()
			.build();

		try (Response response = getRestClient().newCall(request).execute())
		{
			log.debug("Relay returned {} for invite code lookup {}", response.code(), code);
			if (response.isSuccessful() && response.body() != null)
			{
				String responseBody = response.body().string();
				JsonObject json = gson.fromJson(responseBody, JsonObject.class);
				String groupJson = json != null && json.has("groupJson")
					? json.get("groupJson").getAsString() : null;
				return groupJson != null
					? new InviteLookupResult(InviteStatus.FOUND, groupJson)
					: new InviteLookupResult(InviteStatus.NOT_FOUND, null);
			}
			if (response.code() == 404)
			{
				return new InviteLookupResult(InviteStatus.NOT_FOUND, null);
			}
			// 5xx / unexpected status - treat as transient so the user is told to retry
			return new InviteLookupResult(InviteStatus.UNREACHABLE, null);
		}
		catch (Exception e)
		{
			log.warn("Failed to lookup invite code from relay: {}", e.getMessage());
			return new InviteLookupResult(InviteStatus.UNREACHABLE, null);
		}
	}

	/**
	 * @deprecated Use {@link #lookupInvite(String)} which distinguishes not-found from
	 * unreachable. Retained for any callers that only need the group JSON.
	 */
	@Deprecated
	public String lookupInviteCode(String code)
	{
		return lookupInvite(code).groupJson;
	}

	public void consumeInviteCode(String code)
	{
		if (config == null || !config.enableRelaySync()) return;

		String baseUrl = getRestBaseUrl();
		if (baseUrl == null) return;

		Request request = new Request.Builder()
			.url(baseUrl + "/api/invite/" + code)
			.delete()
			.build();

		getRestClient().newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, java.io.IOException e)
			{
				log.warn("Failed to consume invite code on relay: {}", e.getMessage());
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				response.close();
			}
		});
	}

	// --- Group State (catch-up sync) ---

	/**
	 * Push the latest group + data state to the relay. The relay stores it for
	 * catch-up (served by GET /api/state) AND broadcasts it live to other members.
	 *
	 * The live broadcast is HMAC-signed with the group secret so peers can verify
	 * it really came from a member before applying it — without this a client that
	 * only knows the groupId could push a forged state and wipe everyone's data.
	 *
	 * @param publisher this client's player name; receivers treat the publisher as
	 *                  authoritative for their own rows when merging the snapshot
	 */
	public long publishState(String groupId, String groupJson, String dataJson, String publisher)
	{
		if (config == null || !config.enableRelaySync()) return 0L;
		// Cache the volatile field — see leaveRoom for why.
		WebSocket ws = webSocket;
		if (!connected || ws == null || groupId == null) return 0L;

		long timestamp = System.currentTimeMillis();

		JsonObject msg = new JsonObject();
		msg.addProperty("type", "state");
		msg.addProperty("groupId", groupId);
		msg.addProperty("groupJson", groupJson);
		if (dataJson != null)
		{
			msg.addProperty("dataJson", dataJson);
		}
		if (publisher != null)
		{
			msg.addProperty("publisher", publisher);
		}
		msg.addProperty("timestamp", timestamp);

		if (currentSyncSecret != null && !currentSyncSecret.isEmpty())
		{
			String signature = computeHmac(
				buildStateSignaturePayload(groupId, publisher, timestamp, groupJson, dataJson),
				currentSyncSecret);
			if (signature != null)
			{
				msg.addProperty("signature", signature);
			}
		}

		// send() returns false when the socket is already closing - during a relay
		// redeploy, say. Discarding that reported a timestamp for a message that
		// never left, which a caller then treats as "it went out".
		if (!ws.send(gson.toJson(msg)))
		{
			log.warn("State for group {} was not queued: the socket is closing", groupId);
			return 0L;
		}
		log.debug("Published group state to relay for group {}", groupId);
		return timestamp;
	}

	/**
	 * Fetch the stored catch-up snapshot for a group over REST and hand it to the
	 * state handler with a null publisher (authoritative full-state catch-up).
	 * This is a request the client initiates to the configured relay, so the
	 * response is trusted without a per-message signature. Blocking — run off the EDT.
	 *
	 * @return true when the fetch completed (snapshot applied, or the relay
	 *         definitively has no/invalid state for this group — nothing to retry);
	 *         false on a transport failure (timeout, cold-start, non-2xx) that the
	 *         caller should retry with backoff.
	 */
	public boolean fetchStateSnapshot(String groupId)
	{
		if (config == null || !config.enableRelaySync() || groupId == null) return true;

		String baseUrl = getRestBaseUrl();
		if (baseUrl == null) return true;

		try
		{
			// Built inside the try: url() throws IllegalArgumentException on a
			// malformed relay URL (e.g. configured without a scheme), and an
			// escape here would leak past the caller's bookkeeping.
			Request request = new Request.Builder()
				.url(baseUrl + "/api/state/" + groupId)
				.get()
				.build();

			try (Response response = getRestClient().newCall(request).execute())
			{
			if (response.code() == 404)
			{
				// Relay answered: it has no stored state for this group (new group,
				// or storage wiped). Nothing to catch up on — don't retry.
				return true;
			}
			if (!response.isSuccessful() || response.body() == null)
			{
				return false;
			}
			JsonObject json = gson.fromJson(response.body().string(), JsonObject.class);
			if (json == null) return true;

			// Verify the stored snapshot was signed by a member holding the group
			// secret. The relay stores whatever it's sent (and anyone who knows the
			// groupId could try to seed a forged snapshot), so we must not apply an
			// unsigned or tampered catch-up. Freshness is NOT enforced here — stored
			// catch-up state is legitimately old — but the signature and the merge's
			// last-write-wins still prevent forgery and stale-data damage.
			JsonObject stateMsg = new JsonObject();
			stateMsg.addProperty("groupId", groupId);
			copyIfPresent(json, stateMsg, "groupJson");
			copyIfPresent(json, stateMsg, "dataJson");
			copyIfPresent(json, stateMsg, "publisher");
			copyIfPresent(json, stateMsg, "timestamp");
			copyIfPresent(json, stateMsg, "signature");
			if (!verifyStateSignature(stateMsg))
			{
				// A snapshot the relay HAS but we can't verify won't get better on
				// retry (e.g. stored by an old client before signing was rolled out).
				log.warn("Dropping catch-up state for group {}: invalid or missing signature", groupId);
				return true;
			}

			String groupJson = json.has("groupJson") && !json.get("groupJson").isJsonNull()
				? json.get("groupJson").getAsString() : null;
			String dataJson = json.has("dataJson") && !json.get("dataJson").isJsonNull()
				? json.get("dataJson").getAsString() : null;
			if (groupJson != null && onStateReceived != null)
			{
				onStateReceived.accept(groupJson, dataJson, null);

				// The catch-up snapshot can be marginally older than a live state we
				// already applied (it was read from the store before that push), and
				// applying it can briefly revert a peer's rows. Drop the per-publisher
				// content hashes so the peer's next identical heartbeat/announce is
				// NOT deduped and re-applies their newer state — otherwise the revert
				// would stick until their content actually changed.
				String prefix = groupId + ":";
				lastStateHash.keySet().removeIf(k -> k.startsWith(prefix));
			}
			return true;
			}
		}
		catch (Exception e)
		{
			log.warn("Failed to fetch catch-up state from relay: {}", e.getMessage());
			return false;
		}
	}

	private void copyIfPresent(JsonObject from, JsonObject to, String key)
	{
		if (from.has(key) && !from.get(key).isJsonNull())
		{
			to.add(key, from.get(key));
		}
	}

	/**
	 * Canonical string signed for a state message. Includes the full group and
	 * data JSON so neither can be tampered with in transit.
	 */
	private String buildStateSignaturePayload(String groupId, String publisher, long timestamp,
		String groupJson, String dataJson)
	{
		return groupId + ":" + (publisher == null ? "" : publisher) + ":" + timestamp
			+ ":" + (groupJson == null ? "" : groupJson)
			+ ":" + (dataJson == null ? "" : dataJson);
	}

	/**
	 * Verify the HMAC signature on an incoming live state broadcast.
	 */
	private boolean verifyStateSignature(JsonObject msg)
	{
		if (currentSyncSecret == null || currentSyncSecret.isEmpty())
		{
			log.warn("Rejecting relay state: no sync secret configured for current group");
			return false;
		}
		if (!msg.has("signature") || msg.get("signature").isJsonNull())
		{
			log.warn("Rejecting relay state: missing HMAC signature");
			return false;
		}

		String groupId = msg.has("groupId") ? msg.get("groupId").getAsString() : "";
		String publisher = msg.has("publisher") && !msg.get("publisher").isJsonNull()
			? msg.get("publisher").getAsString() : null;
		long timestamp = msg.has("timestamp") && !msg.get("timestamp").isJsonNull()
			? msg.get("timestamp").getAsLong() : 0;
		String groupJson = msg.has("groupJson") && !msg.get("groupJson").isJsonNull()
			? msg.get("groupJson").getAsString() : null;
		String dataJson = msg.has("dataJson") && !msg.get("dataJson").isJsonNull()
			? msg.get("dataJson").getAsString() : null;

		String expected = computeHmac(
			buildStateSignaturePayload(groupId, publisher, timestamp, groupJson, dataJson),
			currentSyncSecret);
		if (expected == null) return false;
		return constantTimeEquals(expected, msg.get("signature").getAsString());
	}

