/**
 * TradeLoanTracker - records loans and returns directly from the player-to-player
 * trade window, and guards borrowed items against being traded away.
 *
 * Flow (mirrors the old pendingLending two-phase pattern):
 *  1. Trade screen 1 (group 335) opens -> new session, partner name read from the
 *     "Trading with: X" title.
 *  2. The player right-clicks their offered items and picks "Mark as Loan".
 *  3. Confirm screen (group 334) opens -> final offers are snapshotted and, when
 *     relevant, a proof screenshot of the confirm screen is cached in memory.
 *  4. "Accepted trade." chat message -> marked items become loan records
 *     (partner = borrower, their offer = collateral); items the partner handed
 *     back that match loans they borrowed are marked returned. The cached
 *     screenshot is committed to disk. A decline discards everything.
 *
 * The guard checks run from menu clicks: offering an item you are borrowing (or
 * accepting a trade that contains one) warns or blocks per config, with Shift as
 * the override; the Wilderness ditch "Cross" click is optionally blocked while
 * carrying borrowed items.
 */
@Slf4j
@Singleton
public class TradeLoanTracker
{
	// The partner's copy of a shared container is id | 0x8000 (see the deprecated
	// net.runelite.api.InventoryID.TRADEOTHER)
	private static final int TRADEOFFER_OTHER = InventoryID.TRADEOFFER | 0x8000;

	private static final String MARK_OPTION = "Mark as Loan";
	private static final String UNMARK_OPTION = "Unmark Loan";
	private static final String TRADING_WITH_PREFIX = "Trading with:";
	private static final String ACCEPTED_TRADE_MESSAGE = "Accepted trade.";
	private static final String PARTNER_DECLINED_MESSAGE = "Other player declined trade.";

	@Inject private Client client;
	@Inject private ClientThread clientThread;
	@Inject private ItemManager itemManager;
	@Inject private LendingTrackerConfig config;
	@Inject private DataService dataService;
	@Inject private GroupService groupService;
	@Inject private ProofScreenshot proofScreenshot;
	@Inject private DiscordWebhook discordWebhook;
	@Inject private ClanRoster clanRoster;

	/** Runnable the plugin sets to refresh the side panel after a change. */
	private Runnable onLoanRecorded;

	// --- Trade session state (all accessed on the client thread) ---
	private boolean tradeOpen;
	private String partner;
	// Exact item ids marked "Lend" (NOT variation-base ids: matching by base would
	// let a different variant of the same item — e.g. a glory(4) offered after
	// unoffering a marked glory(6) — silently become a loan)
	private final Set<Integer> markedItemIds = new HashSet<>();
	private final Set<Integer> warnedBaseIds = new HashSet<>();
	private Item[] finalMyOffer;
	private Item[] finalTheirOffer;
	// True once the confirm screen (334) has loaded for this session. Used by the
	// walk-away cleanup — do NOT infer this from finalTheirOffer, which is
	// legitimately null when the partner offers nothing (a pure loan hand-over:
	// their container is never created client-side until they offer something).
	private boolean confirmLoaded;
	private boolean screenshotCached;
	// Incremented on every reset; lets delayed callbacks (partner-name reads)
	// detect that their session ended so they stop instead of retrying forever
	// or writing stale state into a newer session
	private int sessionId;

	// --- Auto-detection of loans from marketplace listings ---
	// When an item the player has listed for lending shows up in their trade
	// offer, a popup asks (once per trade) whether the trade is that loan — no
	// right-click marking needed for listed items.
	private boolean loanPromptShown;
	private Boolean autoLoanAccepted; // null until the popup is answered
	// True while a popup is on screen and unanswered — a second trade never opens
	// another popup on top of it (stacked identical modals invite wrong answers)
	private boolean promptOpen;
	// The "Loan" toggle button drawn on the trade window (group trades only).
	// When ON, EVERYTHING handed over in this trade is recorded as a loan — one
	// tap, no popup or right-click; the partner doesn't need the plugin at all.
	// The button cycles OFF -> LIST -> 1-TIME: LIST relists the item on the group
	// marketplace when it comes home, 1-TIME records the loan but never lists it
	// (a friend borrowing your axe once shouldn't become a standing offer).
	private boolean autoLoanAll;
	private boolean loanOneTime;
	private Widget loanButton;
	private Widget loanButtonBg;
	// The "Collat" toggle button, drawn under the Loan button. Pressed by the
	// BORROWER side of a trade: everything I hand over is my collateral deposit
	// for a borrow — never a lend — so none of my items may be recorded as loans
	// or trip the marketplace popup. The loan itself is recorded by the lender's
	// client (single writer), exactly like every other loan.
	private boolean collatMode;
	private Widget collatButton;
	private Widget collatButtonBg;
	// How long a loan recorded from THIS trade runs, picked with the Days button in
	// the trade window. 0 = the default from the plugin settings, NO_LIMIT = no due
	// date at all (never overdue). Mostly for trades with mobile and other
	// no-plugin players, where the trade window is the only place to say it.
	private int loanDays;
	private Widget daysButton;
	private Widget daysButtonBg;
	private static final int NO_LIMIT = -1;
	private static final int[] DAY_PRESETS = { 1, 2, 3, 4, 5, 6, 7, NO_LIMIT };
	// Last-known bank contents per variation-base id, for the fungible-duplicate
	// guard logic (see atRiskCarrying). Only populated once the bank has been
	// opened this session; cleared on logout so one account's bank can never
	// vouch for another's collateral.
	private final Map<Integer, Integer> bankQtyByBase = new HashMap<>();
	private boolean bankKnown;

	// Trades that completed before their popup was answered, keyed by session id;
	// a late "yes" records from here. Cleared on logout/shutdown so a stale stash
	// can never record loans under a different account's session.
	private final Map<Integer, PendingLoanDecision> pendingDecisions = new HashMap<>();
	private static final int MAX_PENDING_DECISIONS = 4;

	/** Snapshot of everything needed to record loans after the trade ended. */
	private static final class PendingLoanDecision
	{
		final int session;
		final String partnerName;
		final String lenderName;
		final String groupId;
		final List<StashedLoan> loans = new ArrayList<>();
		long collateralGp;
		String collateralItems;
		String collateralItemIds;
		int days;

		PendingLoanDecision(int session, String partnerName, String lenderName, String groupId)
		{
			this.session = session;
			this.partnerName = partnerName;
			this.lenderName = lenderName;
			this.groupId = groupId;
		}
	}

	private static final class StashedLoan
	{
		final int itemId;
		final int quantity;
		final String name;
		final long value;

		StashedLoan(int itemId, int quantity, String name, long value)
		{
			this.itemId = itemId;
			this.quantity = quantity;
			this.name = name;
			this.value = value;
		}
	}

	public void setOnLoanRecorded(Runnable callback)
	{
		this.onLoanRecorded = callback;
	}

	public boolean isTradeOpen()
	{
		return tradeOpen;
	}

	// --- Session lifecycle ---

	/** Trade screen 1 (group 335) loaded. */
	public void onTradeMainLoaded()
	{
		reset();
		tradeOpen = true;
		schedulePartnerRead(InterfaceID.Trademain.TITLE);
	}

	/**
	 * The trade screen 1 build script (TRADE_MAIN_INIT, 755) fired — the interface
	 * is fully populated and any rebuild that wiped a previous custom child just
	 * finished. Canonical, rebuild-safe point to (re)create the Loan button.
	 */
	public void onTradeMainBuilt()
	{
		// The build script can fire BEFORE our WidgetLoaded handler runs (observed
		// in-game). Don't start the session here — onTradeMainLoaded's reset would
		// wipe whatever we set and orphan a just-created button. Rebuilds mid-trade
		// (offer changes) arrive with tradeOpen already true and re-create safely.
		if (!tradeOpen)
		{
			return;
		}
		ensureLoanButton();
	}

	/** Confirm screen (group 334) loaded — snapshot the final agreed offers. */
	public void onTradeConfirmLoaded()
	{
		if (!tradeOpen)
		{
			// e.g. plugin was enabled mid-trade; treat the confirm screen as a session
			tradeOpen = true;
		}
		if (partner == null)
		{
			// Same tick-timing hazard as screen 1: the text may not be populated yet
			schedulePartnerRead(InterfaceID.Tradeconfirm.TRADEOPPONENT);
		}

		confirmLoaded = true;
		finalMyOffer = copyContainerItems(InventoryID.TRADEOFFER);
		finalTheirOffer = copyContainerItems(TRADEOFFER_OTHER);

		// Cache a proof screenshot while the confirm screen is still visible —
		// the "Accepted trade." message only arrives after the window closes
		if (config.enableTradeScreenshots() && screenshotRelevant())
		{
			proofScreenshot.cacheTradeFrame(ProofScreenshot.PHASE_CONFIRM_SCREEN, InterfaceID.Tradeconfirm.UNIVERSE);
			screenshotCached = true;
		}
	}

	/**
	 * Either trade-offer container changed while screen 1 is up. When the trade
	 * looks loan-relevant, (re)capture the first-screen proof frame — each
	 * re-capture overwrites the last, so the saved shot shows the FINAL offers
	 * with both usernames visible.
	 */
	public void onTradeOfferUpdated()
	{
		maybeCacheFirstScreen();
	}

	private void maybeCacheFirstScreen()
	{
		if (!tradeOpen || confirmLoaded || !config.enableTradeScreenshots() || !firstScreenRelevant())
		{
			return;
		}
		proofScreenshot.cacheTradeFrame(ProofScreenshot.PHASE_FIRST_SCREEN, InterfaceID.Trademain.UNIVERSE);
		screenshotCached = true;
	}

	/** Does the current screen-1 state look like a loan/return in progress? */
	private boolean firstScreenRelevant()
	{
		if (autoLoanAll || collatMode || !markedItemIds.isEmpty())
		{
			return true;
		}
		// A listed item in my live offer (unless the popup was answered "no")
		if (!Boolean.FALSE.equals(autoLoanAccepted))
		{
			Item[] myOffer = copyContainerItems(InventoryID.TRADEOFFER);
			if (myOffer != null)
			{
				for (Item item : myOffer)
				{
					if (item != null && item.getId() > 0 && isListedForLending(item.getId()))
					{
						return true;
					}
				}
			}
		}
		// A potential return: the partner currently borrows something from me
		String me = localPlayerName();
		if (me != null && partner != null)
		{
			for (LendingEntry e : dataService.getActiveEntries())
			{
				if (!e.isReturned() && me.equalsIgnoreCase(e.getLender())
					&& partner.equalsIgnoreCase(e.getBorrower()))
				{
					return true;
				}
			}
		}
		return false;
	}

	/** Will this trade plausibly produce a loan or return worth screenshotting? */
	private boolean screenshotRelevant()
	{
		if (!markedItemIds.isEmpty() || collatMode || hasOpenLoanWithPartner())
		{
			return true;
		}
		if (autoLoanAll && finalMyOffer != null)
		{
			for (Item item : finalMyOffer)
			{
				if (item != null && item.getId() > 0)
				{
					return true;
				}
			}
		}
		// Auto-detected loans count unless the popup was explicitly answered "no"
		return loanPromptShown && !Boolean.FALSE.equals(autoLoanAccepted)
			&& !listedItemIdsInFinalOffer().isEmpty();
	}

	/**
	 * My trade offer changed (ItemContainerChanged for the TRADEOFFER container).
	 * If it now contains items I have listed for lending and I haven't been asked
	 * yet this trade, pop the "is this a loan?" dialog — the listing already
	 * declared the intent, so no right-click marking should be needed.
	 */
	public void onMyOfferChanged(Item[] offerItems)
	{
		// No popup needed when the Loan button already covers the whole trade, and
		// never in Collat mode — those items are a deposit, not a lend.
		if (!tradeOpen || autoLoanAll || collatMode || loanPromptShown || promptOpen || offerItems == null
			|| !config.promptListedLoans())
		{
			return;
		}

		// Only prompt for trades with a member of the lending group, or of the
		// in-game clan the group is linked to (clan-mates on mobile can't join the
		// group) — selling a listed item to a stranger is a sale, not a loan. If the
		// partner name hasn't resolved yet, DON'T burn the once-per-trade prompt:
		// the resolved name triggers a re-check (see schedulePartnerRead).
		if (partner == null || !(isPartnerInActiveGroup() || isPartnerInLinkedClan()))
		{
			return;
		}

		// Items I owe back to THIS partner (I'm their borrower) are returns, not
		// new lends — a return trade must never trip the loan popup. This is the
		// role fix for "traded back and it asked/recorded like I was lending".
		Set<Integer> owedBases = baseIdsIOweTo(partner);

		List<String> listedNames = new ArrayList<>();
		for (Item item : offerItems)
		{
			if (item != null && item.getId() > 0 && isListedForLending(item.getId())
				&& !owedBases.contains(ItemVariationMapping.map(item.getId())))
			{
				listedNames.add(itemName(item.getId()));
			}
		}
		if (listedNames.isEmpty())
		{
			return;
		}

		loanPromptShown = true;
		promptOpen = true;
		final int session = sessionId;
		final String partnerName = partner;
		final String itemsText = String.join(", ", listedNames);
		javax.swing.SwingUtilities.invokeLater(() ->
		{
			int result = javax.swing.JOptionPane.showConfirmDialog(null,
				"You're offering item(s) you have listed for lending:\n" + itemsText
					+ "\n\nRecord this trade as a loan to " + partnerName + "?",
				"Lending Tracker", javax.swing.JOptionPane.YES_NO_OPTION);
			boolean accepted = result == javax.swing.JOptionPane.YES_OPTION;
			clientThread.invokeLater(() -> onLoanPromptAnswered(session, accepted));
		});
	}

	/**
	 * Add a "Loan: OFF/ON" toggle button to the middle of the trade window, for
	 * trades with a group member. One tap marks the whole trade as a loan — no
	 * popup, no right-click — and only THIS client needs the plugin, so it works
	 * when the clan mate is on mobile or vanilla.
	 */
	/**
	 * Create (or re-create) the "Loan" toggle button on the trade window. Safe to
	 * call repeatedly — it no-ops if a live button already exists, and re-builds
	 * one if the interface was rebuilt and wiped the old child. Called both when
	 * the partner name resolves and on every trade-screen build script (755), so
	 * it survives offer changes.
	 */
	public void ensureLoanButton()
	{
		if (!tradeOpen)
		{
			return;
		}

		// Resolve the partner now if the title is populated (it is, by build time)
		if (partner == null)
		{
			partner = readPartnerName(InterfaceID.Trademain.TITLE);
		}
		if (partner == null)
		{
			return;
		}

		// The button works for ANY trade partner — the loan is recorded entirely on
		// this (the lender's) client, so the borrower needn't be a group member or
		// even have the plugin. It only needs a group to file the loan under.
		LendingGroup group = groupService.getActiveGroup();
		if (group == null)
		{
			return;
		}

		// Still have live buttons attached to the interface? Keep them. (A null
		// collatButton with a live loanButton means it was deliberately skipped
		// for lack of room — don't loop trying to recreate it.)
		if (loanButton != null && loanButton.getParent() != null
			&& (collatButton == null || collatButton.getParent() != null)
			&& (daysButton == null || daysButton.getParent() != null))
		{
			return;
		}
		loanButton = null;
		loanButtonBg = null;
		collatButton = null;
		collatButtonBg = null;
		daysButton = null;
		daysButtonBg = null;

		// Prefer the middle column layer (holds Accept/Decline); fall back outward
		Widget parent = firstNonNull(
			client.getWidget(InterfaceID.Trademain.MIDDLE),
			client.getWidget(InterfaceID.Trademain.UNIVERSE),
			client.getWidget(InterfaceID.Trademain.WHOLESCREEN));
		if (parent == null)
		{
			return;
		}

		int pw = parent.getWidth();
		int ph = parent.getHeight();
		int width = Math.max(90, Math.min(pw > 0 ? pw - 4 : 120, 120));
		int height = 16;
		int x = Math.max(0, (pw - width) / 2);
		// The middle column has two clear gaps: above Accept (under the free-slots
		// box) and between Accept and Decline. Loan goes between Accept and Decline,
		// Days above Accept, Collat at the very bottom. (Second from the bottom is
		// where "Other player has accepted." appears, so nothing sits there.) With
		// no usable gap: the old stack, Loan at the bottom and Collat just above.
		int bottomY = Math.max(2, ph - height - 4);
		int[] gaps = middleGaps(parent, height);
		int loanY = gaps[1] >= 0 ? gaps[1] : bottomY;
		int collatY = gaps[1] >= 0 ? bottomY : Math.max(2, bottomY - height - 2);

		Widget[] loan = createTradeButton(parent, x, loanY, width, height,
			loanButtonText(), loanButtonColor(), this::toggleLoanMode);
		loanButtonBg = loan[0];
		loanButton = loan[1];

		// Only add the Collat button when it can't overlap the Loan button - in a
		// too-short fallback layer the two would collide, which is worse than the
		// borrower using the popup flow.
		if (Math.abs(collatY - loanY) >= height + 2)
		{
			Widget[] collat = createTradeButton(parent, x, collatY, width, height,
				collatButtonText(collatMode), collatMode ? 0x00ff00 : 0xffff00, this::toggleCollatMode);
			collatButtonBg = collat[0];
			collatButton = collat[1];

			// Days above Accept; failing that, the first other clear spot. Never on
			// top of Accept or Decline.
			int daysY = gaps[0] >= 0 ? gaps[0] : freeSlot(parent, Math.min(loanY, collatY), height);
			if (daysY >= 0)
			{
				Widget[] days = createTradeButton(parent, x, daysY, width, height,
					daysButtonText(), 0x00ffff, this::cycleLoanDays);
				daysButtonBg = days[0];
				daysButton = days[1];
			}
		}
	}

	/** Build one background+text pseudo-button pair on the trade interface. */
	private Widget[] createTradeButton(Widget parent, int x, int y, int width, int height,
		String text, int color, Runnable onClick)
	{
		Widget bg = parent.createChild(-1, WidgetType.RECTANGLE);
		bg.setOriginalX(x);
		bg.setOriginalY(y);
		bg.setOriginalWidth(width);
		bg.setOriginalHeight(height);
		bg.setFilled(true);
		bg.setTextColor(0x1e1e1e);
		bg.setOpacity(70);
		bg.setAction(0, "Toggle");
		bg.setHasListener(true);
		bg.setOnOpListener((JavaScriptCallback) ev -> onClick.run());
		bg.revalidate();

		Widget btn = parent.createChild(-1, WidgetType.TEXT);
		btn.setText(text);
		btn.setTextColor(color);
		btn.setFontId(FontID.BOLD_12);
		btn.setTextShadowed(true);
		btn.setXTextAlignment(1);
		btn.setYTextAlignment(1);
		btn.setOriginalX(x);
		btn.setOriginalY(y);
		btn.setOriginalWidth(width);
		btn.setOriginalHeight(height);
		btn.setAction(0, "Toggle");
		btn.setHasListener(true);
		btn.setOnOpListener((JavaScriptCallback) ev -> onClick.run());
		btn.revalidate();

		return new Widget[] { bg, btn };
	}

	/**
	 * Centred y positions (relative to parent) for a button of this height in the
	 * middle column's two gaps: [0] above Accept, below the free-slots box; [1]
	 * between Accept and Decline. -1 where the gap is too small or can't be seen.
	 */
	private int[] middleGaps(Widget parent, int height)
	{
		int[] out = { -1, -1 };
		int[] free = span(parent, InterfaceID.Trademain.FREESPACE_CONTAINER);
		int[] accept = span(parent, InterfaceID.Trademain.ACCEPT);
		int[] decline = span(parent, InterfaceID.Trademain.DECLINE);
		if (accept != null)
		{
			int top = free != null && free[1] <= accept[0] ? free[1] : 0;
			int gap = accept[0] - top;
			if (gap >= height + 4)
			{
				out[0] = top + (gap - height) / 2;
			}
		}
		if (accept != null && decline != null)
		{
			int gap = decline[0] - accept[1];
			if (gap >= height + 4)
			{
				out[1] = accept[1] + (gap - height) / 2;
			}
		}
		return out;
	}

	/** {top, bottom} of a widget relative to parent, or null if it isn't showing. */
	private int[] span(Widget parent, int id)
	{
		Widget w = client.getWidget(id);
		net.runelite.api.Point origin = parent.getCanvasLocation();
		if (w == null || w.isHidden() || origin == null || w.getCanvasLocation() == null)
		{
			return null;
		}
		int y = w.getCanvasLocation().getY() - origin.getY();
		return new int[] { y, y + w.getHeight() };
	}

	/**
	 * A y (relative to parent) where a button of this height fits in the trade
	 * window's middle column without covering Accept or Decline: just above
	 * `below` if that's clear of both, else above both.
	 * -1 when there's no such room - the loan then just uses the default length.
	 */
	private int freeSlot(Widget parent, int below, int height)
	{
		net.runelite.api.Point origin = parent.getCanvasLocation();
		int top = Integer.MAX_VALUE;
		int bottom = Integer.MIN_VALUE;
		for (int id : new int[] { InterfaceID.Trademain.ACCEPT, InterfaceID.Trademain.DECLINE })
		{
			Widget w = client.getWidget(id);
			if (w == null || w.isHidden() || origin == null || w.getCanvasLocation() == null)
			{
				continue;
			}
			int y = w.getCanvasLocation().getY() - origin.getY();
			top = Math.min(top, y);
			bottom = Math.max(bottom, y + w.getHeight());
		}
		int under = below - height - 2;
		if (top == Integer.MAX_VALUE)
		{
			// Can't see them - only use the lower half, where they never are
			return under >= parent.getHeight() / 2 ? under : -1;
		}
		if (under >= bottom + 2)
		{
			return under;
		}
		int over = top - height - 2;
		return over >= 2 ? over : -1;
	}

	private static Widget firstNonNull(Widget... widgets)
	{
		for (Widget w : widgets)
		{
			if (w != null)
			{
				return w;
			}
		}
		return null;
	}

	private void toggleLoanMode()
	{
		// The widget's listener can fire once more after a same-tick reset
		// (decline + click race) — never toggle a dead session
		if (!tradeOpen || partner == null)
		{
			return;
		}
		// Cycle OFF -> LIST -> 1-TIME -> OFF, so the lender picks per loan whether
		// the item goes (back) on the marketplace when it's returned.
		if (!autoLoanAll)
		{
			autoLoanAll = true;
			loanOneTime = false;
		}
		else if (!loanOneTime)
		{
			loanOneTime = true;
		}
		else
		{
			autoLoanAll = false;
			loanOneTime = false;
		}
		// You're either the lender or the borrower in a trade — not both
		if (autoLoanAll && collatMode)
		{
			collatMode = false;
			refreshCollatButton();
			addGameMessage("Collat mode off — you're lending in this trade.");
		}
		refreshLoanButton();
		if (autoLoanAll)
		{
			addGameMessage(loanOneTime
				? "One-time loan mode — everything you hand over is recorded as a loan to " + partner
					+ ", and will NOT be listed on the marketplace when returned."
				: "Loan mode ON — everything you hand over is recorded as a loan to " + partner
					+ " and relists on the group marketplace when returned.");
			maybeCacheFirstScreen();
		}
		else
		{
			addGameMessage("Loan mode off for this trade.");
		}
	}

	private void toggleCollatMode()
	{
		if (!tradeOpen || partner == null)
		{
			return;
		}
		collatMode = !collatMode;
		if (collatMode && autoLoanAll)
		{
			autoLoanAll = false;
			loanOneTime = false;
			refreshLoanButton();
			addGameMessage("Loan mode off — you're borrowing in this trade.");
		}
		refreshCollatButton();
		addGameMessage(collatMode
			? "Collat mode ON — items you hand over in this trade are your collateral deposit for a borrow from "
				+ partner + ", not a loan. They will never appear on your marketplace."
			: "Collat mode off for this trade.");
		if (collatMode)
		{
			maybeCacheFirstScreen();
		}
	}

	private void refreshLoanButton()
	{
		if (loanButton != null)
		{
			loanButton.setText(loanButtonText());
			loanButton.setTextColor(loanButtonColor());
		}
	}

	private void refreshCollatButton()
	{
		if (collatButton != null)
		{
			collatButton.setText(collatButtonText(collatMode));
			collatButton.setTextColor(collatMode ? 0x00ff00 : 0xffff00);
		}
	}

	private String loanButtonText()
	{
		if (!autoLoanAll)
		{
			return "Loan: OFF";
		}
		return loanOneTime ? "Loan: 1-TIME" : "Loan: LIST";
	}

	private int loanButtonColor()
	{
		if (!autoLoanAll)
		{
			return 0xffff00;
		}
		return loanOneTime ? 0xff9900 : 0x00ff00;
	}

	/** Loan length for this trade: the Days button's pick, else the configured default. */
	private int effectiveLoanDays()
	{
		return loanDays != 0 ? loanDays : Math.max(1, config.defaultLoanDuration());
	}

	/** Due time for a loan of this many days, or 0 (no due date) for no limit. */
	private static long dueTimeFor(int days)
	{
		return days == NO_LIMIT ? 0L : System.currentTimeMillis() + Math.max(1, days) * 86400000L;
	}

	/** "3 days" / "1 day" / "no time limit", for chat messages. */
	private static String daysLabel(int days)
	{
		return days == NO_LIMIT ? "no time limit" : days + (days == 1 ? " day" : " days");
	}

	private String daysButtonText()
	{
		int days = effectiveLoanDays();
		return days == NO_LIMIT ? "Days: No limit" : "Days: " + days;
	}

	/** Step to the next length: 1 to 7 one at a time, then No limit, then back to 1. */
	private void cycleLoanDays()
	{
		int current = effectiveLoanDays();
		int next = DAY_PRESETS[0];
		for (int i = 0; i < DAY_PRESETS.length; i++)
		{
			if (DAY_PRESETS[i] == current)
			{
				next = DAY_PRESETS[(i + 1) % DAY_PRESETS.length];
				break;
			}
		}
		loanDays = next;
		if (daysButton != null)
		{
			daysButton.setText(daysButtonText());
		}
	}

	private static String collatButtonText(boolean on)
	{
		return on ? "Collat: ON" : "Collat: OFF";
	}

	/** Popup answered — during the trade if possible, after it via the stash. */
	private void onLoanPromptAnswered(int session, boolean accepted)
	{
		promptOpen = false;

		if (session == sessionId && tradeOpen)
		{
			autoLoanAccepted = accepted;
			addGameMessage(accepted
				? "Listed items in this trade will be recorded as loans when it completes."
				: "Okay — this trade won't be recorded as a loan.");
			if (accepted)
			{
				maybeCacheFirstScreen();
			}
			return;
		}

		// The trade already completed while the dialog was open
		PendingLoanDecision stash = pendingDecisions.remove(session);
		if (stash != null && accepted)
		{
			recordStashedLoans(stash);
		}
	}

	/**
	 * Forget any stashed loan decisions and open-popup state. Called on logout and
	 * plugin shutdown so a late dialog answer can't record loans under a different
	 * account or long after the fact.
	 */
	public void clearPendingDecisions()
	{
		pendingDecisions.clear();
		promptOpen = false;
		// Logout hook: forget the bank snapshot too — guards fall back to cautious
		// until this (possibly different) account opens its own bank.
		bankQtyByBase.clear();
		bankKnown = false;
	}

	/** The bank container changed (it's open) — snapshot quantities per base id. */
	public void onBankUpdated(Item[] items)
	{
		bankQtyByBase.clear();
		bankKnown = true;
		if (items == null)
		{
			return;
		}
		for (Item item : items)
		{
			if (item != null && item.getId() > 0)
			{
				bankQtyByBase.merge(ItemVariationMapping.map(item.getId()), item.getQuantity(), Integer::sum);
			}
		}
	}

	/** Is this item (or a variant of it) listed by me on the group marketplace? */
	private boolean isListedForLending(int itemId)
	{
		// Raw GP can never be a lendable item, even when someone listed "Coins" on
		// the marketplace — treating offered coins as a loan would double-count GP
		// the return tally already consumed as collateral coming home.
		if (itemId == ItemID.COINS_995 || itemId == ItemID.PLATINUM_TOKEN)
		{
			return false;
		}
		String me = localPlayerName();
		LendingGroup group = groupService.getActiveGroup();
		if (me == null || group == null)
		{
			return false;
		}
		int baseId = ItemVariationMapping.map(itemId);
		for (LendingEntry offering : dataService.getOfferingsByOwner(group.getId(), me))
		{
			if (ItemVariationMapping.map(offering.getItemId()) == baseId)
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * Read the partner name from a trade widget, retrying for a bounded number of
	 * ticks (the text is often unpopulated on the load tick). The session id stops
	 * the retry loop the moment the session ends, so a failed read can neither
	 * retry forever nor write a stale name into a later session.
	 */
	private void schedulePartnerRead(int componentId)
	{
		final int session = sessionId;
		final int[] attempts = {0};
		clientThread.invokeLater(() ->
		{
			if (session != sessionId)
			{
				return true; // session ended — stop
			}
			String name = readPartnerName(componentId);
			if (name != null)
			{
				partner = name;
				// If the confirm screen was reached before the name resolved, the
				// screenshot-relevance check ran with partner == null (returns
				// couldn't be matched). Re-evaluate now so a return-only trade
				// still gets its proof frame while the screen is visible.
				if (confirmLoaded && !screenshotCached
					&& config.enableTradeScreenshots() && screenshotRelevant())
				{
					proofScreenshot.cacheTradeFrame(ProofScreenshot.PHASE_CONFIRM_SCREEN, InterfaceID.Tradeconfirm.UNIVERSE);
					screenshotCached = true;
				}
				// The loan popup and Loan button are gated on knowing the partner —
				// now that the name resolved, create the button and re-check the offer
				ensureLoanButton();
				onMyOfferChanged(copyContainerItems(InventoryID.TRADEOFFER));
				return true;
			}
			return ++attempts[0] >= 10; // give up after ~10 ticks
		});
	}

	/**
	 * A trade widget closed. Both accept and cancel paths fire this, and for a
	 * completed trade the "Accepted trade." message arrives AFTER the close — so
	 * don't reset immediately. Instead schedule a short-delay check: if the
	 * session is still open and neither the confirm screen loaded (335 closed by
	 * walking away / Esc) nor the completion message arrived (334 closed the same
	 * way), the trade was cancelled — clear the session so marks, partner and the
	 * cached proof frame don't linger.
	 */
	public void onTradeWidgetClosed(int groupId)
	{
		if (!tradeOpen)
		{
			return;
		}
		final int session = sessionId;
		final boolean closedConfirm = groupId == InterfaceID.TRADECONFIRM;
		final int[] ticks = {0};
		clientThread.invokeLater(() ->
		{
			if (session != sessionId)
			{
				return true; // completed, declined, or a new trade started — done
			}
			// 335 advancing to 334 loads the confirm screen within a tick or two;
			// a completed 334 produces "Accepted trade." within a few ticks.
			int waitTicks = closedConfirm ? 10 : 3;
			if (++ticks[0] < waitTicks)
			{
				return false;
			}
			if (!closedConfirm && confirmLoaded)
			{
				return true; // 335 closed because we advanced to the confirm screen
			}
			reset();
			return true;
		});
	}

	/** ChatMessageType.TRADE message — completion or partner decline. */
	public void onTradeMessage(String message)
	{
		if (ACCEPTED_TRADE_MESSAGE.equals(message))
		{
			completeTrade();
		}
		else if (PARTNER_DECLINED_MESSAGE.equals(message))
		{
			reset();
		}
	}

	public void reset()
	{
		sessionId++;
		tradeOpen = false;
		partner = null;
		markedItemIds.clear();
		warnedBaseIds.clear();
		finalMyOffer = null;
		finalTheirOffer = null;
		confirmLoaded = false;
		loanPromptShown = false;
		autoLoanAccepted = null;
		autoLoanAll = false;
		loanOneTime = false;
		collatMode = false;
		loanButton = null; // the widgets die with the trade interface
		loanButtonBg = null;
		collatButton = null;
		collatButtonBg = null;
		daysButton = null;
		daysButtonBg = null;
		loanDays = 0;
		// pendingDecisions deliberately survives reset() — it's how a popup answered
		// after its trade ended still records the loans. It IS cleared on logout and
		// shutdown via clearPendingDecisions().
		if (screenshotCached)
		{
			proofScreenshot.discardCachedFrame();
			screenshotCached = false;
		}
	}

	// --- Menu integration ---

	/**
	 * Add "Mark as Loan" / "Unmark Loan" to the player's own offered items on
	 * trade screen 1.
	 */
	public void onMenuEntryAdded(MenuEntryAdded event)
	{
		if (!tradeOpen || event.getActionParam1() != InterfaceID.Trademain.YOUR_OFFER)
		{
			return;
		}

		// The engine fires one MenuEntryAdded per vanilla option on the hovered
		// slot (Remove-1/-5/-All/...) — only add our entry once per menu build, on
		// the first of them, so it can't stack up or become the left-click default.
		for (net.runelite.api.MenuEntry existing : client.getMenuEntries())
		{
			String opt = existing.getOption();
			if ((MARK_OPTION.equals(opt) || UNMARK_OPTION.equals(opt))
				&& existing.getParam0() == event.getActionParam0()
				&& existing.getParam1() == event.getActionParam1())
			{
				return;
			}
		}

		int itemId = resolveOfferItemId(event.getActionParam0());
		if (itemId <= 0)
		{
			return;
		}

		boolean marked = markedItemIds.contains(itemId);
		client.createMenuEntry(-1)
			.setOption(marked ? UNMARK_OPTION : MARK_OPTION)
			.setTarget(event.getTarget())
			.setType(MenuAction.RUNELITE)
			.setParam0(event.getActionParam0())
			.setParam1(event.getActionParam1())
			.setIdentifier(itemId);
	}

	/**
	 * Handle a menu click: loan mark toggles, decline detection, and the borrowed
	 * item guards. Returns true when the event was fully handled (consumed).
	 */
	public boolean onMenuOptionClicked(MenuOptionClicked event)
	{
		String option = event.getMenuOption();
		if (option == null)
		{
			return false;
		}

		// Toggle loan marking (our own RUNELITE entries)
		if (MARK_OPTION.equals(option) || UNMARK_OPTION.equals(option))
		{
			int itemId = event.getId();
			if (MARK_OPTION.equals(option))
			{
				markedItemIds.add(itemId);
				addGameMessage("Marked " + itemName(itemId) + " as a loan. It will be recorded when the trade completes.");
				maybeCacheFirstScreen();
			}
			else
			{
				markedItemIds.remove(itemId);
				addGameMessage("Unmarked " + itemName(itemId) + ".");
			}
			event.consume();
			return true;
		}

		int widgetGroup = event.getParam1() >> 16;

		// Self-decline ends the session (no chat message is produced for it)
		if ("Decline".equals(option)
			&& (widgetGroup == InterfaceID.TRADEMAIN || widgetGroup == InterfaceID.TRADECONFIRM))
		{
			reset();
			return false;
		}

		// Trade guard: offering an item you're borrowing
		if (tradeOpen && widgetGroup == InterfaceID.TRADESIDE && option.startsWith("Offer"))
		{
			return guardOfferClick(event);
		}

		// Trade guard: accepting a trade whose offer contains a borrowed item
		if (tradeOpen && "Accept".equals(option)
			&& (event.getParam1() == InterfaceID.Trademain.ACCEPT
				|| event.getParam1() == InterfaceID.Tradeconfirm.TRADE2ACCEPT))
		{
			return guardAcceptClick(event);
		}

		// Wilderness guard: crossing the ditch while carrying borrowed items
		if ("Cross".equals(option) && config.wildernessGuard() == GuardMode.BLOCK
			&& Text.removeTags(event.getMenuTarget()).contains("Wilderness ditch"))
		{
			return guardWildernessCross(event);
		}

		return false;
	}

	// --- Guards ---

	private boolean guardOfferClick(MenuOptionClicked event)
	{
		if (config.tradeGuard() == GuardMode.OFF)
		{
			return false;
		}

		int itemId = event.getMenuEntry().getItemId();
		if (itemId <= 0)
		{
			itemId = resolveInventoryItemId(event.getParam0());
		}
		if (itemId <= 0)
		{
			return false;
		}

		LendingEntry borrowed = findBorrowedEntry(itemId);
		if (borrowed == null)
		{
			return false;
		}

		int baseId = ItemVariationMapping.map(itemId);

		// Giving the item back to its lender is the trade we WANT — never impede it
		if (partner != null && partner.equalsIgnoreCase(borrowed.getLender()))
		{
			if (warnedBaseIds.add(baseId))
			{
				addGameMessage("Returning " + itemName(itemId) + " to " + borrowed.getLender()
					+ " — the loan will be marked returned when the trade completes.");
			}
			return false;
		}

		boolean partnerInGroup = isPartnerInActiveGroup();

		if (partnerInGroup && config.allowLendBorrowedToGroup())
		{
			if (warnedBaseIds.add(baseId))
			{
				addGameMessage(warnPrefix() + itemName(itemId) + " is borrowed from "
					+ borrowed.getLender() + " — " + partner + " is in your lending group, so this is allowed.");
			}
			return false;
		}

		// Fungible duplicates: if the bank + what you'd still hold after this
		// trade covers everything you owe of this item, you're trading your OWN
		// spare — no warning needed.
		if (tradeAwayCovered(baseId))
		{
			if (warnedBaseIds.add(baseId))
			{
				addGameMessage(itemName(itemId) + " matches a borrowed item, but your remaining copies still cover what you owe — trading your spare is fine.");
			}
			return false;
		}

		if (config.tradeGuard() == GuardMode.BLOCK && !client.isKeyPressed(KeyCode.KC_SHIFT))
		{
			event.consume();
			addGameMessage(warnPrefix() + "Blocked: " + itemName(itemId) + " is borrowed from "
				+ borrowed.getLender() + ". Hold Shift and click again to offer it anyway.");
			return true;
		}

		if (warnedBaseIds.add(baseId))
		{
			addGameMessage(warnPrefix() + itemName(itemId) + " is borrowed from "
				+ borrowed.getLender() + " — are you sure you want to trade it away?");
		}
		return false;
	}

	private boolean guardAcceptClick(MenuOptionClicked event)
	{
		if (config.tradeGuard() != GuardMode.BLOCK || client.isKeyPressed(KeyCode.KC_SHIFT))
		{
			return false;
		}
		if (isPartnerInActiveGroup() && config.allowLendBorrowedToGroup())
		{
			return false;
		}

		Item[] myOffer = copyContainerItems(InventoryID.TRADEOFFER);
		if (myOffer == null)
		{
			return false;
		}

		for (Item item : myOffer)
		{
			LendingEntry borrowed = item != null ? findBorrowedEntry(item.getId()) : null;
			if (borrowed != null)
			{
				// Returning to the lender is fine — don't block the Accept
				if (partner != null && partner.equalsIgnoreCase(borrowed.getLender()))
				{
					continue;
				}
				// Trading a covered spare of your own is fine too
				if (tradeAwayCovered(ItemVariationMapping.map(item.getId())))
				{
					continue;
				}
				event.consume();
				addGameMessage(warnPrefix() + "Blocked: your offer contains " + itemName(item.getId())
					+ " borrowed from " + borrowed.getLender() + ". Remove it, or hold Shift and click Accept to override.");
				return true;
			}
		}
		return false;
	}

	private boolean guardWildernessCross(MenuOptionClicked event)
	{
		// Only guard crossings INTO the wilderness. Blocking the same click while
		// the player is already inside would delay their escape — the opposite of
		// protecting the borrowed items.
		if (client.getVarbitValue(net.runelite.api.Varbits.IN_WILDERNESS) == 1)
		{
			return false;
		}
		if (client.isKeyPressed(KeyCode.KC_SHIFT))
		{
			return false;
		}

		List<LendingEntry> borrowed = carriedBorrowedEntries();
		List<LendingEntry> collateral = carriedCollateralEntries();
		if (borrowed.isEmpty() && collateral.isEmpty())
		{
			return false;
		}

		event.consume();
		StringBuilder what = new StringBuilder();
		if (!borrowed.isEmpty())
		{
			long total = borrowed.stream().mapToLong(LendingEntry::getValue).sum();
			what.append(borrowed.size()).append(" borrowed item(s) worth ")
				.append(QuantityFormatter.quantityToStackSize(total)).append(" GP");
		}
		if (!collateral.isEmpty())
		{
			if (what.length() > 0)
			{
				what.append(" and ");
			}
			what.append("collateral you're holding for ").append(collateral.size()).append(" loan(s)");
		}
		addGameMessage(warnPrefix() + "Blocked: you are carrying " + what
			+ ". Hold Shift and click again to cross anyway.");
		return true;
	}

	/**
	 * Borrowed items currently in the player's inventory or equipment.
	 * Used by the wilderness guards (both the ditch block and the entry warning).
	 */
	public List<LendingEntry> carriedBorrowedEntries()
	{
		String me = localPlayerName();
		if (me == null)
		{
			return new ArrayList<>();
		}

		Map<Integer, Integer> carried = carriedQuantitiesByBase();
		Map<Integer, Integer> owedByBase = totalOwedByBase();

		List<LendingEntry> result = new ArrayList<>();
		for (LendingEntry e : dataService.getActiveEntries())
		{
			if (!e.isReturned() && me.equalsIgnoreCase(e.getBorrower())
				&& e.outstandingLentQty() > 0
				&& atRiskCarrying(carried, owedByBase, ItemVariationMapping.map(e.getItemId())))
			{
				result.add(e);
			}
		}
		return result;
	}

	/**
	 * Items are fungible: what matters is never WHICH copy you hold, only that
	 * you can still cover what you owe. Carrying a base item is AT RISK only when
	 * the bank no longer covers the TOTAL owed of that base across ALL open
	 * obligations — so someone with a spare in the bank can freely carry their
	 * own copy, but one banked spare can never vouch for two debts at once.
	 * Bank contents are only known after the bank has been opened this session;
	 * until then banked counts as 0 (the cautious old behavior).
	 */
	private boolean atRiskCarrying(Map<Integer, Integer> carried, Map<Integer, Integer> owedByBase, int baseId)
	{
		int owed = owedByBase.getOrDefault(baseId, 0);
		if (owed <= 0)
		{
			return false;
		}
		int carriedQty = carried.getOrDefault(baseId, 0);
		if (carriedQty <= 0)
		{
			return false;
		}
		int banked = bankKnown ? bankQtyByBase.getOrDefault(baseId, 0) : 0;
		return banked < owed;
	}

	/**
	 * TOTAL quantity owed per variation-base id across ALL my open obligations:
	 * items I borrowed (owed back to their lenders) plus collateral I hold (owed
	 * back to borrowers). Aggregated so coverage checks can't double-count one
	 * banked spare against several debts of the same item.
	 */
	private Map<Integer, Integer> totalOwedByBase()
	{
		Map<Integer, Integer> owed = new HashMap<>();
		String me = localPlayerName();
		if (me == null)
		{
			return owed;
		}
		for (LendingEntry e : dataService.getActiveEntries())
		{
			if (me.equalsIgnoreCase(e.getBorrower()))
			{
				int q = e.outstandingLentQty();
				if (q > 0)
				{
					owed.merge(ItemVariationMapping.map(e.getItemId()), q, Integer::sum);
				}
			}
			if (me.equalsIgnoreCase(e.getLender()))
			{
				for (int[] pair : parseIdQtyPairs(e.outstandingCollateralIds()))
				{
					owed.merge(ItemVariationMapping.map(pair[0]), pair[1], Integer::sum);
				}
			}
		}
		return owed;
	}

	/**
	 * May I trade a copy of this base item AWAY (to a non-lender) without going
	 * below what I owe? True when the bank plus what I'd still be carrying after
	 * the trade covers the total debt of that base. Offered items have already
	 * left the inventory container, so carried here is the post-trade remainder.
	 */
	private boolean tradeAwayCovered(int baseId)
	{
		if (!bankKnown)
		{
			return false;
		}
		int owed = totalOwedByBase().getOrDefault(baseId, 0);
		if (owed <= 0)
		{
			return true;
		}
		int banked = bankQtyByBase.getOrDefault(baseId, 0);
		int carried = carriedQuantitiesByBase().getOrDefault(baseId, 0);
		return banked + carried >= owed;
	}

	/** Carried (inventory + worn) quantities per variation-base id. */
	private Map<Integer, Integer> carriedQuantitiesByBase()
	{
		Map<Integer, Integer> carried = new HashMap<>();
		collectBaseQuantities(carried, InventoryID.INV);
		collectBaseQuantities(carried, InventoryID.WORN);
		return carried;
	}

	/**
	 * Active loans I LENT whose item-collateral I'm currently carrying (inventory
	 * or equipment). The lender is responsible for the borrower's collateral until
	 * the loan settles, so the wilderness guards treat it like borrowed gear.
	 */
	public List<LendingEntry> carriedCollateralEntries()
	{
		String me = localPlayerName();
		if (me == null)
		{
			return new ArrayList<>();
		}

		Map<Integer, Integer> carried = carriedQuantitiesByBase();
		Map<Integer, Integer> owedByBase = totalOwedByBase();

		List<LendingEntry> result = new ArrayList<>();
		for (LendingEntry e : dataService.getActiveEntries())
		{
			if (e.isReturned() || !me.equalsIgnoreCase(e.getLender()))
			{
				continue;
			}
			for (int[] pair : parseIdQtyPairs(e.outstandingCollateralIds()))
			{
				if (atRiskCarrying(carried, owedByBase, ItemVariationMapping.map(pair[0])))
				{
					result.add(e);
					break;
				}
			}
		}
		return result;
	}

	/** Parse an "itemId:qty,itemId:qty" string into [id, qty] pairs (qty >= 1). */
	private static List<int[]> parseIdQtyPairs(String raw)
	{
		List<int[]> pairs = new ArrayList<>();
		if (raw == null || raw.isEmpty())
		{
			return pairs;
		}
		for (String pair : raw.split(","))
		{
			try
			{
				int idx = pair.indexOf(':');
				int id = Integer.parseInt(idx > 0 ? pair.substring(0, idx) : pair);
				int qty = idx > 0 ? Integer.parseInt(pair.substring(idx + 1)) : 1;
				pairs.add(new int[] { id, Math.max(1, qty) });
			}
			catch (NumberFormatException ignored)
			{
			}
		}
		return pairs;
	}

	/** Join [id, qty] pairs back into the "itemId:qty,..." wire format. */
	private static String joinIdQtyPairs(List<int[]> pairs)
	{
		StringBuilder sb = new StringBuilder();
		for (int[] p : pairs)
		{
			if (p[1] <= 0)
			{
				continue;
			}
			if (sb.length() > 0)
			{
				sb.append(',');
			}
			sb.append(p[0]).append(':').append(p[1]);
		}
		return sb.toString();
	}

	// --- Trade completion ---

	private void completeTrade()
	{
		try
		{
			if (partner == null)
			{
				if (!markedItemIds.isEmpty())
				{
					addGameMessage(warnPrefix() + "Trade completed but the partner's name couldn't be read — the loan was NOT recorded. Add it manually from the panel.");
				}
				return;
			}
			if (finalMyOffer == null && finalTheirOffer == null)
			{
				return;
			}

			// Match this trade against open loans FIRST (running tally, both sides):
			// what came home is a return, and returns are excluded from everything
			// below so they can never be re-recorded as new lends or collateral.
			ReturnTally tally = applyReturnTallies();

			// Loans = everything I offered (Loan button ON) ∪ explicitly marked
			// items ∪ (listed items, if the popup was answered yes). An unanswered
			// popup stashes the listed items so a late "yes" can still record them.
			// Raw GP is NEVER a lendable item — coins/platinum in a loan trade are
			// collateral (or its return, or payment); recording a "Coins loan" would
			// double-count the same GP the tally just consumed.
			Set<Integer> loanItemIds = new HashSet<>(markedItemIds);
			loanItemIds.remove(ItemID.COINS_995);
			loanItemIds.remove(ItemID.PLATINUM_TOKEN);
			if (autoLoanAll && finalMyOffer != null)
			{
				for (Item item : finalMyOffer)
				{
					if (item != null && item.getId() > 0
						&& item.getId() != ItemID.COINS_995 && item.getId() != ItemID.PLATINUM_TOKEN)
					{
						loanItemIds.add(item.getId());
					}
				}
			}
			if (Boolean.TRUE.equals(autoLoanAccepted))
			{
				loanItemIds.addAll(listedItemIdsInFinalOffer());
			}

			// Collat mode: everything I handed over is my deposit for a borrow —
			// nothing of mine may be recorded as a loan.
			if (collatMode && !loanItemIds.isEmpty())
			{
				loanItemIds.clear();
			}
			// Items I owe back to this partner are returns in progress, never new
			// lends — the lender's client records the tally, mine just stays quiet.
			if (!loanItemIds.isEmpty())
			{
				Set<Integer> owedBases = baseIdsIOweTo(partner);
				if (!owedBases.isEmpty())
				{
					loanItemIds.removeIf(id -> owedBases.contains(ItemVariationMapping.map(id)));
				}
			}

			// Each group chooses whose loans it tracks (clan / group / anyone).
			// Returns above still settle - an existing loan must always be closable.
			LendingGroup activeGroup = groupService.getActiveGroup();
			String outsideWhy = activeGroup != null ? outsideLoanScope(activeGroup.getId(), partner) : null;
			boolean keepingBorrow = collatMode && !isPartnerInActiveGroup();
			if (outsideWhy != null && (!loanItemIds.isEmpty() || keepingBorrow))
			{
				addGameMessage(warnPrefix() + outsideWhy + " - this trade was NOT recorded as a loan.");
				loanItemIds.clear();
				keepingBorrow = false;
			}

			List<LendingEntry> newLoans = recordLoans(loanItemIds, tally);
			// Collat mode with someone outside the group: they can't record it, so we do.
			List<LendingEntry> keptLoans = keepingBorrow ? recordKeptLoans() : new ArrayList<>();

			PendingLoanDecision stashedNow = null;
			if (!collatMode && loanPromptShown && autoLoanAccepted == null)
			{
				stashedNow = stashPendingDecision(loanItemIds, tally);
			}

			// One Discord post per trade, whatever number of items changed hands.
			// Taken before the screenshot commit/discard below, which clear it.
			java.awt.image.BufferedImage tradePicture = discordWebhook.wantsScreenshot()
				? proofScreenshot.takeProofCrop() : null;
			discordWebhook.postBatch(DiscordWebhook.Event.LOAN, newLoans, localPlayerName(), null, tradePicture);
			discordWebhook.postBatch(DiscordWebhook.Event.LOAN, keptLoans, localPlayerName(), null, tradePicture);
			// Loans I lent and loans I kept as the borrower have opposite lender and
			// borrower, so they are separate posts even when one trade settles both.
			List<LendingEntry> closedLent = new ArrayList<>();
			List<LendingEntry> closedKept = new ArrayList<>();
			for (LendingEntry e : tally.closed)
			{
				(e.isKeptByBorrower() ? closedKept : closedLent).add(e);
			}
			discordWebhook.postBatch(DiscordWebhook.Event.RETURNED, closedLent, localPlayerName(), null, tradePicture);
			discordWebhook.postBatch(DiscordWebhook.Event.RETURNED, closedKept, localPlayerName(), null, tradePicture);
			// Anything a trade settled only part of gets its own post listing what is
			// still out. Stamped per trade, so each part-return posts once.
			List<LendingEntry> partLent = new ArrayList<>();
			List<LendingEntry> partKept = new ArrayList<>();
			for (LendingEntry e : tally.progressed)
			{
				(e.isKeptByBorrower() ? partKept : partLent).add(e);
			}
			String tradeStamp = String.valueOf(System.currentTimeMillis());
			discordWebhook.postBatch(DiscordWebhook.Event.PARTIAL, partLent, localPlayerName(), tradeStamp, tradePicture);
			discordWebhook.postBatch(DiscordWebhook.Event.PARTIAL, partKept, localPlayerName(), tradeStamp, tradePicture);

			for (LendingEntry e : tally.closed)
			{
				dataService.completeEntry(e.getId(), true);
				// A loan I kept as the borrower went home to its owner - it was
				// never mine to put on the marketplace.
				if (!e.isKeptByBorrower())
				{
					relistReturnedItem(e);
				}
				String collat = collateralDescription(e);
				addGameMessage("Return complete: " + e.getItemName() + " — loan with " + partner + " fully settled."
					+ (collat != null ? " Collateral returned in full: " + collat + "." : ""));
			}
			for (LendingEntry e : tally.progressed)
			{
				dataService.updateEntryProgress(e);
				// Not a return until EVERYTHING is back. Say exactly what's missing;
				// the rest can come in any later trade, even one where the other
				// side hands over nothing, and the loan completes on its own then.
				addGameMessage(warnPrefix() + "Return NOT complete - the " + e.getItemName() + " loan with "
					+ partner + " stays open. Missing: " + missingSummary(e)
					+ ". Trade the rest any time and it completes automatically.");
			}

			if (collatMode)
			{
				if (keptLoans.isEmpty())
				{
					addGameMessage("Collateral deposit noted — the loan record comes from " + partner + "'s client.");
				}
				// The DEPOSITOR deserves their own on-disk proof of what they handed
				// over — the lender's screenshot is no help to the borrower in a
				// dispute against that lender.
				if (config.enableTradeScreenshots())
				{
					LendingEntry deposit = provisionalDepositEntry();
					if (deposit != null)
					{
						proofScreenshot.commitCachedTrade(localPlayerName(), activeGroupName(), partner, "DEPOSIT", deposit);
						screenshotCached = false;
					}
				}
			}

			if (!newLoans.isEmpty() || tally.any())
			{
				// commitCachedTrade prefers the frame cached on the confirm screen;
				// if none was cached (e.g. the partner name resolved too late) it
				// falls back to capturing the next frame — weaker evidence, but
				// better than nothing
				if (config.enableTradeScreenshots())
				{
					LendingEntry subject = !newLoans.isEmpty() ? newLoans.get(0)
						: !tally.closed.isEmpty() ? tally.closed.get(0) : tally.progressed.get(0);
					String eventType = !newLoans.isEmpty() ? "LOAN" : "RETURN";
					proofScreenshot.commitCachedTrade(localPlayerName(), activeGroupName(), partner, eventType, subject);
				}
				else if (screenshotCached)
				{
					proofScreenshot.discardCachedFrame();
				}
			}
			else if (stashedNow != null && config.enableTradeScreenshots())
			{
				// THIS trade's popup hasn't been answered yet: commit the confirm-screen
				// frame now (a stray screenshot is harmless if they answer no; waiting
				// would lose the frame to the next trade)
				LendingEntry provisional = provisionalEntryFromStash(stashedNow);
				if (provisional != null)
				{
					proofScreenshot.commitCachedTrade(localPlayerName(), activeGroupName(), partner, "LOAN", provisional);
				}
				else if (screenshotCached)
				{
					proofScreenshot.discardCachedFrame();
				}
			}
			else if (screenshotCached)
			{
				proofScreenshot.discardCachedFrame();
			}
			screenshotCached = false;

			if ((!newLoans.isEmpty() || !keptLoans.isEmpty() || tally.any()) && onLoanRecorded != null)
			{
				onLoanRecorded.run();
			}
		}
		finally
		{
			reset();
		}
	}

	/** Outcome of matching one completed trade against the open loans with this partner. */
	private static final class ReturnTally
	{
		final List<LendingEntry> closed = new ArrayList<>();      // fully settled, both sides home
		final List<LendingEntry> progressed = new ArrayList<>();  // partial — still open, tallies updated
		// What this trade consumed as returns, per variation-base id — used to keep
		// those quantities out of new-loan / collateral aggregation.
		final Map<Integer, Integer> consumedTheirQtyByBase = new HashMap<>();
		final Map<Integer, Integer> consumedMyQtyByBase = new HashMap<>();

		boolean any()
		{
			return !closed.isEmpty() || !progressed.isEmpty();
		}
	}

	/**
	 * Collat mode with a partner who isn't in the group - a clan-mate on mobile,
	 * typically. They can't record the loan, so without this it existed nowhere.
	 * This client records it instead, as the borrower, and becomes its keeper:
	 * what I received is what I borrowed, what I handed over is my collateral.
	 * The keeper flag is what stops anyone else ever tallying or posting it too.
	 */
	private List<LendingEntry> recordKeptLoans()
	{
		List<LendingEntry> created = new ArrayList<>();
		String me = localPlayerName();
		LendingGroup group = groupService.getActiveGroup();
		if (me == null || partner == null || group == null || finalTheirOffer == null)
		{
			return created;
		}

		// What they handed me. Raw GP is never a lendable item - coins in a
		// borrow trade are theirs to count, not a loan of coins.
		Map<Integer, Integer> borrowed = new LinkedHashMap<>();
		for (Item item : finalTheirOffer)
		{
			if (item != null && item.getId() > 0
				&& item.getId() != ItemID.COINS_995 && item.getId() != ItemID.PLATINUM_TOKEN)
			{
				borrowed.merge(item.getId(), item.getQuantity(), Integer::sum);
			}
		}
		if (borrowed.isEmpty())
		{
			return created;
		}

		// What I handed them: my collateral
		long collateralGp = 0;
		List<String> collateralItems = new ArrayList<>();
		List<String> collateralIdPairs = new ArrayList<>();
		if (finalMyOffer != null)
		{
			for (Item item : finalMyOffer)
			{
				if (item == null || item.getId() <= 0)
				{
					continue;
				}
				if (item.getId() == ItemID.COINS_995)
				{
					collateralGp += item.getQuantity();
				}
				else if (item.getId() == ItemID.PLATINUM_TOKEN)
				{
					collateralGp += item.getQuantity() * 1000L;
				}
				else
				{
					collateralItems.add(itemName(item.getId()) + (item.getQuantity() > 1 ? " x" + item.getQuantity() : ""));
					collateralIdPairs.add(item.getId() + ":" + item.getQuantity());
				}
			}
		}

		long dueTime = dueTimeFor(effectiveLoanDays());
		boolean first = true;
		for (Map.Entry<Integer, Integer> got : borrowed.entrySet())
		{
			int itemId = got.getKey();
			int quantity = got.getValue();

			LendingEntry entry = new LendingEntry();
			entry.setId(UUID.randomUUID().toString());
			entry.setItem(itemName(itemId));
			entry.setItemId(itemId);
			entry.setQuantity(quantity);
			entry.setValue((long) itemManager.getItemPrice(itemId) * quantity);
			entry.setLentOutstanding(quantity);
			entry.setCollateralOutstandingIds("");
			entry.setCollateralGpOutstanding(0L);
			entry.setKeptByBorrower(true);
			// Collateral covers the whole trade - on the FIRST record only, as the
			// lender side does, so it isn't counted once per item.
			if (first)
			{
				if (collateralGp > 0)
				{
					entry.setCollateralValue((int) Math.min(collateralGp, Integer.MAX_VALUE));
					entry.setCollateralType("GP");
					entry.setCollateralGpOutstanding(collateralGp);
				}
				if (!collateralItems.isEmpty())
				{
					entry.setCollateralItems(String.join(", ", collateralItems));
					entry.setCollateralItemIds(String.join(",", collateralIdPairs));
					entry.setCollateralOutstandingIds(String.join(",", collateralIdPairs));
				}
			}
			dataService.addLoan(group.getId(), partner, me, entry, dueTime);
			created.add(entry);

			addGameMessage("Borrow recorded: " + entry.getItem()
				+ (quantity > 1 ? " x" + quantity : "") + " from " + partner
				+ " (" + daysLabel(effectiveLoanDays())
				+ (first && collateralGp > 0 ? ", collateral " + QuantityFormatter.quantityToStackSize(collateralGp) + " GP" : "")
				+ "). " + partner + " isn't in the group, so your plugin keeps this loan.");
			first = false;
		}
		return created;
	}

	/**
	 * Mirror of the lender-side tally, for loans this client keeps as the
	 * BORROWER: me handing their item back settles what I owe, them handing my
	 * deposit back settles what they owe. Runs before the lender-side pass so the
	 * same physical item can't settle two obligations.
	 */
	private void tallyKeptLoans(ReturnTally tally, String me, Map<Integer, Integer> myByBase,
		Map<Integer, Integer> theirByBase, long[] theirGp)
	{
		List<LendingEntry> kept = new ArrayList<>();
		for (LendingEntry e : dataService.getActiveEntries())
		{
			if (e.isKeptByBorrower() && !e.isFullySettled()
				&& me.equalsIgnoreCase(e.getBorrower())
				&& partner.equalsIgnoreCase(e.getLender()))
			{
				kept.add(e);
			}
		}
		kept.sort((a, b) -> Long.compare(a.getLendTime(), b.getLendTime()));

		for (LendingEntry e : kept)
		{
			boolean changed = false;

			// Borrowed side: me handing their item back
			int outLent = e.outstandingLentQty();
			if (outLent > 0)
			{
				int baseId = ItemVariationMapping.map(e.getItemId());
				int available = myByBase.getOrDefault(baseId, 0);
				int take = Math.min(available, outLent);
				if (take > 0)
				{
					myByBase.put(baseId, available - take);
					e.setLentOutstanding(outLent - take);
					tally.consumedMyQtyByBase.merge(baseId, take, Integer::sum);
					changed = true;
				}
			}

			// Collateral items side: them handing my deposit back
			List<int[]> collatPairs = parseIdQtyPairs(e.outstandingCollateralIds());
			if (!collatPairs.isEmpty())
			{
				boolean collatChanged = false;
				for (int[] pair : collatPairs)
				{
					int baseId = ItemVariationMapping.map(pair[0]);
					int available = theirByBase.getOrDefault(baseId, 0);
					int take = Math.min(available, pair[1]);
					if (take > 0)
					{
						theirByBase.put(baseId, available - take);
						pair[1] -= take;
						tally.consumedTheirQtyByBase.merge(baseId, take, Integer::sum);
						collatChanged = true;
					}
				}
				if (collatChanged)
				{
					e.setCollateralOutstandingIds(joinIdQtyPairs(collatPairs));
					changed = true;
				}
			}

			// Collateral GP side: them handing my coins back
			long outGp = e.outstandingCollateralGp();
			if (outGp > 0 && theirGp[0] > 0)
			{
				long take = Math.min(theirGp[0], outGp);
				theirGp[0] -= take;
				e.setCollateralGpOutstanding(outGp - take);
				changed = true;
			}

			if (changed)
			{
				e.setLentOutstanding(e.outstandingLentQty());
				e.setCollateralOutstandingIds(e.outstandingCollateralIds());
				e.setCollateralGpOutstanding(e.outstandingCollateralGp());
				if (e.isFullySettled())
				{
					tally.closed.add(e);
				}
				else
				{
					tally.progressed.add(e);
				}
			}
		}
	}

	/**
	 * The running-tally return engine. A loan settles piece by piece, on BOTH
	 * sides: the partner handing lent items back decrements what the borrower
	 * owes, and ME handing their collateral back decrements what I owe. Each
	 * completed trade consumes whatever matched (any quantity, oldest loan
	 * first); a loan only closes when both sides reach zero — so a partial
	 * return records progress but can never mark the loan complete, and a
	 * "return" that keeps the collateral no longer counts as settled.
	 *
	 * Runs on the lender's client (the single writer for the loan's lifecycle,
	 * same as loan recording) and syncs every change live to the group.
	 */
	private ReturnTally applyReturnTallies()
	{
		ReturnTally tally = new ReturnTally();
		String me = localPlayerName();
		if (me == null || partner == null)
		{
			return tally;
		}
		// Collat mode declares this whole trade a NEW borrow: my items are a fresh
		// deposit and the partner's items are what I'm borrowing (recorded on their
		// client). Explicit intent beats auto-matching — consuming either side as
		// returns here would fight the partner's client's interpretation.
		if (collatMode)
		{
			return tally;
		}

		// Pools of what actually changed hands, per variation-base id
		Map<Integer, Integer> theirByBase = new HashMap<>();
		if (finalTheirOffer != null)
		{
			for (Item item : finalTheirOffer)
			{
				if (item != null && item.getId() > 0)
				{
					theirByBase.merge(ItemVariationMapping.map(item.getId()), item.getQuantity(), Integer::sum);
				}
			}
		}
		Map<Integer, Integer> myByBase = new HashMap<>();
		long myGp = 0;
		if (finalMyOffer != null)
		{
			for (Item item : finalMyOffer)
			{
				if (item == null || item.getId() <= 0)
				{
					continue;
				}
				if (item.getId() == ItemID.COINS_995)
				{
					myGp += item.getQuantity();
				}
				else if (item.getId() == ItemID.PLATINUM_TOKEN)
				{
					myGp += item.getQuantity() * 1000L;
				}
				else
				{
					myByBase.merge(ItemVariationMapping.map(item.getId()), item.getQuantity(), Integer::sum);
				}
			}
		}
		if (theirByBase.isEmpty() && myByBase.isEmpty() && myGp == 0)
		{
			return tally;
		}

		// Loans this client keeps as the borrower settle first (see tallyKeptLoans)
		long[] theirGp = { 0 };
		if (finalTheirOffer != null)
		{
			for (Item item : finalTheirOffer)
			{
				if (item != null && item.getId() == ItemID.COINS_995)
				{
					theirGp[0] += item.getQuantity();
				}
				else if (item != null && item.getId() == ItemID.PLATINUM_TOKEN)
				{
					theirGp[0] += item.getQuantity() * 1000L;
				}
			}
		}
		tallyKeptLoans(tally, me, myByBase, theirByBase, theirGp);

		// Reserve quantities I owe THIS partner as their borrower: those hand-overs
		// settle MY debt on their client's records — the same physical item must
		// not also be consumed here as a collateral return on a loan I lent
		// (cross-loans with the same base item would let one item settle two
		// obligations across the two clients).
		for (LendingEntry e : dataService.getActiveEntries())
		{
			// Loans I keep myself were already settled from this pool above
			if (!e.isKeptByBorrower()
				&& me.equalsIgnoreCase(e.getBorrower())
				&& partner.equalsIgnoreCase(e.getLender()))
			{
				int owed = e.outstandingLentQty();
				if (owed > 0)
				{
					int baseId = ItemVariationMapping.map(e.getItemId());
					int pool = myByBase.getOrDefault(baseId, 0);
					if (pool > 0)
					{
						myByBase.put(baseId, Math.max(0, pool - owed));
					}
				}
			}
		}

		List<LendingEntry> candidates = new ArrayList<>();
		for (LendingEntry e : dataService.getActiveEntries())
		{
			if (!e.isFullySettled()
				&& me.equalsIgnoreCase(e.getLender())
				&& partner.equalsIgnoreCase(e.getBorrower()))
			{
				candidates.add(e);
			}
		}
		candidates.sort((a, b) -> Long.compare(a.getLendTime(), b.getLendTime()));

		for (LendingEntry e : candidates)
		{
			boolean changed = false;

			// Lent side: partner handing my item back
			int outLent = e.outstandingLentQty();
			if (outLent > 0)
			{
				int baseId = ItemVariationMapping.map(e.getItemId());
				int available = theirByBase.getOrDefault(baseId, 0);
				int take = Math.min(available, outLent);
				if (take > 0)
				{
					theirByBase.put(baseId, available - take);
					e.setLentOutstanding(outLent - take);
					tally.consumedTheirQtyByBase.merge(baseId, take, Integer::sum);
					changed = true;
				}
			}

			// Collateral items side: me handing their deposit back
			List<int[]> collatPairs = parseIdQtyPairs(e.outstandingCollateralIds());
			if (!collatPairs.isEmpty())
			{
				boolean collatChanged = false;
				for (int[] pair : collatPairs)
				{
					int baseId = ItemVariationMapping.map(pair[0]);
					int available = myByBase.getOrDefault(baseId, 0);
					int take = Math.min(available, pair[1]);
					if (take > 0)
					{
						myByBase.put(baseId, available - take);
						pair[1] -= take;
						tally.consumedMyQtyByBase.merge(baseId, take, Integer::sum);
						collatChanged = true;
					}
				}
				if (collatChanged)
				{
					e.setCollateralOutstandingIds(joinIdQtyPairs(collatPairs));
					changed = true;
				}
			}

			// Collateral GP side: me handing coins/plat back
			long outGp = e.outstandingCollateralGp();
			if (outGp > 0 && myGp > 0)
			{
				long take = Math.min(myGp, outGp);
				myGp -= take;
				e.setCollateralGpOutstanding(outGp - take);
				changed = true;
			}

			if (changed)
			{
				// Materialize all three tallies so a legacy record that just took its
				// first partial return can't fall back to the old all-or-nothing view
				e.setLentOutstanding(e.outstandingLentQty());
				e.setCollateralOutstandingIds(e.outstandingCollateralIds());
				e.setCollateralGpOutstanding(e.outstandingCollateralGp());
				if (e.isFullySettled())
				{
					tally.closed.add(e);
				}
				else
				{
					tally.progressed.add(e);
				}
			}
		}
		return tally;
	}

	/**
	 * Variation-base ids of items I still owe back to this partner (I'm their
	 * borrower). Anything matching these in MY offer is a return in progress —
	 * never a new lend, never a marketplace-popup candidate.
	 */
	private Set<Integer> baseIdsIOweTo(String partnerName)
	{
		Set<Integer> bases = new HashSet<>();
		String me = localPlayerName();
		if (me == null || partnerName == null)
		{
			return bases;
		}
		for (LendingEntry e : dataService.getActiveEntries())
		{
			if (e.outstandingLentQty() > 0
				&& me.equalsIgnoreCase(e.getBorrower())
				&& partnerName.equalsIgnoreCase(e.getLender()))
			{
				bases.add(ItemVariationMapping.map(e.getItemId()));
			}
		}
		return bases;
	}

	/** Any open (not fully settled) loan between me and this partner, either direction? */
	private boolean hasOpenLoanWithPartner()
	{
		String me = localPlayerName();
		if (me == null || partner == null)
		{
			return false;
		}
		for (LendingEntry e : dataService.getActiveEntries())
		{
			if (e.isFullySettled())
			{
				continue;
			}
			boolean meLender = me.equalsIgnoreCase(e.getLender()) && partner.equalsIgnoreCase(e.getBorrower());
			boolean meBorrower = me.equalsIgnoreCase(e.getBorrower()) && partner.equalsIgnoreCase(e.getLender());
			if (meLender || meBorrower)
			{
				return true;
			}
		}
		return false;
	}

	/** The collateral a loan was given, as recorded (GP and/or items), or null if none. */
	private static String collateralDescription(LendingEntry e)
	{
		List<String> parts = new ArrayList<>();
		if (e.getCollateralValue() != null && e.getCollateralValue() > 0 && "GP".equals(e.getCollateralType()))
		{
			parts.add(QuantityFormatter.quantityToStackSize(e.getCollateralValue()) + " GP");
		}
		if (e.getCollateralItems() != null && !e.getCollateralItems().isEmpty())
		{
			parts.add(e.getCollateralItems());
		}
		return parts.isEmpty() ? null : String.join(" + ", parts);
	}

	/** Who still owes what on a loan, by name - for the incomplete-return warning. */
	private String missingSummary(LendingEntry e)
	{
		List<String> parts = new ArrayList<>();
		int lent = e.outstandingLentQty();
		if (lent > 0)
		{
			parts.add(e.getBorrower() + " still has " + e.getItemName() + (lent > 1 ? " x" + lent : ""));
		}
		List<String> back = new ArrayList<>();
		for (int[] p : parseIdQtyPairs(e.outstandingCollateralIds()))
		{
			if (p[1] > 0)
			{
				back.add(itemName(p[0]) + (p[1] > 1 ? " x" + p[1] : ""));
			}
		}
		long gp = e.outstandingCollateralGp();
		if (gp > 0)
		{
			back.add(QuantityFormatter.quantityToStackSize(gp) + " GP");
		}
		if (!back.isEmpty())
		{
			parts.add(e.getLender() + " still has the collateral: " + String.join(", ", back));
		}
		return parts.isEmpty() ? "nothing" : String.join("; ", parts);
	}

	/** Exact ids of items in my final offer that I have listed for lending. */
	private Set<Integer> listedItemIdsInFinalOffer()
	{
		Set<Integer> result = new HashSet<>();
		if (finalMyOffer == null)
		{
			return result;
		}
		for (Item item : finalMyOffer)
		{
			if (item != null && item.getId() > 0 && isListedForLending(item.getId()))
			{
				result.add(item.getId());
			}
		}
		return result;
	}

	/** Create loan records for the given item ids present in my final offer. */
	private List<LendingEntry> recordLoans(Set<Integer> loanItemIds, ReturnTally tally)
	{
		List<LendingEntry> created = new ArrayList<>();
		String me = localPlayerName();
		if (me == null || loanItemIds.isEmpty() || finalMyOffer == null)
		{
			return created;
		}

		LendingGroup group = groupService.getActiveGroup();
		if (group == null)
		{
			addGameMessage(warnPrefix() + "Trade completed but no lending group is active — the loan was NOT recorded. Create or select a group first.");
			return created;
		}

		// Aggregate loaned offer items by exact id (an offer can hold several stacks)
		Map<Integer, Integer> lentQuantities = new HashMap<>();
		for (Item item : finalMyOffer)
		{
			if (item != null && item.getId() > 0 && loanItemIds.contains(item.getId()))
			{
				lentQuantities.merge(item.getId(), item.getQuantity(), Integer::sum);
			}
		}
		// Quantities I handed back as COLLATERAL RETURNS are not new lends — the
		// tally consumed them; subtract per variation-base so a mixed trade
		// (returning their deposit while lending something new) records only the
		// genuinely new part.
		if (!tally.consumedMyQtyByBase.isEmpty())
		{
			Map<Integer, Integer> remainingConsumed = new HashMap<>(tally.consumedMyQtyByBase);
			for (Map.Entry<Integer, Integer> lent : new ArrayList<>(lentQuantities.entrySet()))
			{
				int baseId = ItemVariationMapping.map(lent.getKey());
				int consumed = remainingConsumed.getOrDefault(baseId, 0);
				if (consumed <= 0)
				{
					continue;
				}
				int take = Math.min(consumed, lent.getValue());
				remainingConsumed.put(baseId, consumed - take);
				int left = lent.getValue() - take;
				if (left > 0)
				{
					lentQuantities.put(lent.getKey(), left);
				}
				else
				{
					lentQuantities.remove(lent.getKey());
				}
			}
		}
		if (lentQuantities.isEmpty())
		{
			return created;
		}

		// The partner's side of a loan trade is collateral. Coins and platinum
		// tokens count as GP. Quantities the tally consumed as LENT-ITEM RETURNS
		// are exactly that — returns — so only the leftover is collateral.
		Map<Integer, Integer> remainingTheirConsumed = new HashMap<>(tally.consumedTheirQtyByBase);
		long collateralGp = 0;
		List<String> collateralItems = new ArrayList<>();
		List<String> collateralIdPairs = new ArrayList<>();
		if (finalTheirOffer != null)
		{
			for (Item item : finalTheirOffer)
			{
				if (item == null || item.getId() <= 0)
				{
					continue;
				}
				if (item.getId() == ItemID.COINS_995)
				{
					collateralGp += item.getQuantity();
				}
				else if (item.getId() == ItemID.PLATINUM_TOKEN)
				{
					collateralGp += item.getQuantity() * 1000L;
				}
				else
				{
					int baseId = ItemVariationMapping.map(item.getId());
					int consumed = remainingTheirConsumed.getOrDefault(baseId, 0);
					int qty = item.getQuantity();
					int take = Math.min(consumed, qty);
					if (take > 0)
					{
						remainingTheirConsumed.put(baseId, consumed - take);
						qty -= take;
					}
					if (qty > 0)
					{
						collateralItems.add(itemName(item.getId())
							+ (qty > 1 ? " x" + qty : ""));
						collateralIdPairs.add(item.getId() + ":" + qty);
					}
				}
			}
		}

		long dueTime = dueTimeFor(effectiveLoanDays());
		boolean first = true;
		for (Map.Entry<Integer, Integer> lent : lentQuantities.entrySet())
		{
			int itemId = lent.getKey();
			int quantity = lent.getValue();

			LendingEntry entry = new LendingEntry();
			entry.setId(UUID.randomUUID().toString());
			entry.setItem(itemName(itemId));
			entry.setItemId(itemId);
			entry.setQuantity(quantity);
			entry.setValue((long) itemManager.getItemPrice(itemId) * quantity);
			// Running tally starts with everything outstanding
			entry.setLentOutstanding(quantity);
			entry.setCollateralOutstandingIds("");
			entry.setCollateralGpOutstanding(0L);
			// Lender chose one-time: tracked like any loan, never (re)listed on return
			entry.setOneTime(autoLoanAll && loanOneTime);
			// Collateral covers the whole trade — attach it to the FIRST loan record
			// only, so several loans from one trade don't multiply the recorded total
			if (first)
			{
				if (collateralGp > 0)
				{
					entry.setCollateralValue((int) Math.min(collateralGp, Integer.MAX_VALUE));
					entry.setCollateralType("GP");
					entry.setCollateralGpOutstanding(collateralGp);
				}
				if (!collateralItems.isEmpty())
				{
					entry.setCollateralItems(String.join(", ", collateralItems));
					entry.setCollateralItemIds(String.join(",", collateralIdPairs));
					entry.setCollateralOutstandingIds(String.join(",", collateralIdPairs));
				}
			}
			dataService.addLoan(group.getId(), me, partner, entry, dueTime);
			adjustListingForLoan(group.getId(), me, itemId, quantity);
			created.add(entry);

			addGameMessage("Loan recorded: " + entry.getItem()
				+ (quantity > 1 ? " x" + quantity : "") + " to " + partner
				+ " (" + daysLabel(effectiveLoanDays())
				+ (entry.isOneTimeLoan() ? ", one-time" : "")
				+ (first && collateralGp > 0 ? ", collateral " + QuantityFormatter.quantityToStackSize(collateralGp) + " GP" : "")
				+ ").");
			first = false;
		}
		return created;
	}

	/**
	 * A loan came home — put the item (back) on the group marketplace. Restocks a
	 * decremented listing, and items that were lent WITHOUT ever being listed join
	 * the marketplace pool here, so everything the player has ever lent out ends
	 * up visible to the group. addAvailable merges quantity into an existing
	 * listing of the same item, so this never creates duplicates.
	 */
	private void relistReturnedItem(LendingEntry returned)
	{
		// One-time loans are recorded and tracked like any other, but the lender
		// chose NOT to make the item a standing marketplace offer — coming home
		// ends the story.
		if (returned.isOneTimeLoan())
		{
			addGameMessage(returned.getItemName() + " returned — not re-listed (one-time loan).");
			return;
		}

		String me = localPlayerName();
		LendingGroup group = groupService.getActiveGroup();
		if (me == null || group == null || returned.getItemId() <= 0)
		{
			return;
		}

		LendingEntry listing = new LendingEntry();
		listing.setId(UUID.randomUUID().toString());
		listing.setItem(returned.getItem());
		listing.setItemId(returned.getItemId());
		listing.setQuantity(Math.max(1, returned.getQuantity()));
		listing.setValue(returned.getValue());
		listing.setBorrower("");
		listing.setLendTime(System.currentTimeMillis());
		listing.setDueTime(Long.MAX_VALUE);
		dataService.addAvailable(group.getId(), me, listing);
		addGameMessage(returned.getItemName() + " re-listed on the group marketplace.");
	}

	/**
	 * A listed item just went out on loan — reduce or remove the marketplace
	 * listing so it doesn't still show as available while it's lent out.
	 */
	private void adjustListingForLoan(String groupId, String me, int itemId, int quantity)
	{
		int baseId = ItemVariationMapping.map(itemId);
		for (LendingEntry offering : dataService.getOfferingsByOwner(groupId, me))
		{
			if (ItemVariationMapping.map(offering.getItemId()) == baseId)
			{
				String ownerKey = offering.getLender() != null ? offering.getLender() : me;
				if (offering.getQuantity() > quantity)
				{
					LendingEntry updated = new LendingEntry(offering);
					updated.setQuantity(offering.getQuantity() - quantity);
					dataService.updateAvailable(groupId, ownerKey, offering.getItem(), offering.getItemId(), updated);
				}
				else
				{
					dataService.removeAvailable(groupId, ownerKey, offering.getItem(), offering.getItemId());
				}
				return;
			}
		}
	}

	/**
	 * The trade completed while the "is this a loan?" popup was still open — stash
	 * everything needed so a late "yes" can still record the loans.
	 * Already-recorded ids (explicitly marked ones) are excluded.
	 */
	private PendingLoanDecision stashPendingDecision(Set<Integer> alreadyRecorded, ReturnTally tally)
	{
		String me = localPlayerName();
		LendingGroup group = groupService.getActiveGroup();
		if (me == null || partner == null || group == null || finalMyOffer == null)
		{
			return null;
		}

		PendingLoanDecision stash = new PendingLoanDecision(sessionId, partner, me, group.getId());
		stash.days = effectiveLoanDays();
		// Quantities consumed as returns (either side) never become stashed loans
		Set<Integer> owedBases = baseIdsIOweTo(partner);
		Map<Integer, Integer> quantities = new HashMap<>();
		for (Item item : finalMyOffer)
		{
			if (item != null && item.getId() > 0 && !alreadyRecorded.contains(item.getId())
				&& isListedForLending(item.getId())
				&& !owedBases.contains(ItemVariationMapping.map(item.getId())))
			{
				quantities.merge(item.getId(), item.getQuantity(), Integer::sum);
			}
		}
		if (!tally.consumedMyQtyByBase.isEmpty())
		{
			Map<Integer, Integer> remainingConsumed = new HashMap<>(tally.consumedMyQtyByBase);
			for (Map.Entry<Integer, Integer> q : new ArrayList<>(quantities.entrySet()))
			{
				int baseId = ItemVariationMapping.map(q.getKey());
				int consumed = remainingConsumed.getOrDefault(baseId, 0);
				if (consumed <= 0)
				{
					continue;
				}
				int take = Math.min(consumed, q.getValue());
				remainingConsumed.put(baseId, consumed - take);
				int left = q.getValue() - take;
				if (left > 0)
				{
					quantities.put(q.getKey(), left);
				}
				else
				{
					quantities.remove(q.getKey());
				}
			}
		}
		if (quantities.isEmpty())
		{
			return null;
		}
		for (Map.Entry<Integer, Integer> q : quantities.entrySet())
		{
			stash.loans.add(new StashedLoan(q.getKey(), q.getValue(), itemName(q.getKey()),
				(long) itemManager.getItemPrice(q.getKey()) * q.getValue()));
		}

		// Collateral snapshot (same rules as recordLoans: returned lent items are
		// returns, only the leftover of the partner's offer is collateral)
		Map<Integer, Integer> remainingTheirConsumed = new HashMap<>(tally.consumedTheirQtyByBase);
		long collateralGp = 0;
		List<String> collateralItems = new ArrayList<>();
		List<String> collateralIdPairs = new ArrayList<>();
		if (finalTheirOffer != null)
		{
			for (Item item : finalTheirOffer)
			{
				if (item == null || item.getId() <= 0)
				{
					continue;
				}
				if (item.getId() == ItemID.COINS_995)
				{
					collateralGp += item.getQuantity();
				}
				else if (item.getId() == ItemID.PLATINUM_TOKEN)
				{
					collateralGp += item.getQuantity() * 1000L;
				}
				else
				{
					int baseId = ItemVariationMapping.map(item.getId());
					int consumed = remainingTheirConsumed.getOrDefault(baseId, 0);
					int qty = item.getQuantity();
					int take = Math.min(consumed, qty);
					if (take > 0)
					{
						remainingTheirConsumed.put(baseId, consumed - take);
						qty -= take;
					}
					if (qty > 0)
					{
						collateralItems.add(itemName(item.getId())
							+ (qty > 1 ? " x" + qty : ""));
						collateralIdPairs.add(item.getId() + ":" + qty);
					}
				}
			}
		}
		stash.collateralGp = collateralGp;
		stash.collateralItems = collateralItems.isEmpty() ? null : String.join(", ", collateralItems);
		stash.collateralItemIds = collateralIdPairs.isEmpty() ? null : String.join(",", collateralIdPairs);

		// Bound the stash map: evict the oldest if a user somehow leaves several
		// popups unanswered
		if (pendingDecisions.size() >= MAX_PENDING_DECISIONS)
		{
			Integer oldest = pendingDecisions.keySet().stream().min(Integer::compare).orElse(null);
			if (oldest != null)
			{
				pendingDecisions.remove(oldest);
			}
		}
		pendingDecisions.put(stash.session, stash);
		return stash;
	}

	/** The popup was answered "yes" after the trade ended — record from the stash. */
	private void recordStashedLoans(PendingLoanDecision stash)
	{
		String outsideWhy = outsideLoanScope(stash.groupId, stash.partnerName);
		if (outsideWhy != null)
		{
			addGameMessage(warnPrefix() + outsideWhy + " - NOT recorded as a loan.");
			return;
		}
		long dueTime = dueTimeFor(stash.days == 0 ? Math.max(1, config.defaultLoanDuration()) : stash.days);
		boolean first = true;
		List<LendingEntry> recorded = new ArrayList<>();
		for (StashedLoan loan : stash.loans)
		{
			LendingEntry entry = new LendingEntry();
			entry.setId(UUID.randomUUID().toString());
			entry.setItem(loan.name);
			entry.setItemId(loan.itemId);
			entry.setQuantity(loan.quantity);
			entry.setValue(loan.value);
			// Running tally starts with everything outstanding
			entry.setLentOutstanding(loan.quantity);
			entry.setCollateralOutstandingIds("");
			entry.setCollateralGpOutstanding(0L);
			if (first)
			{
				if (stash.collateralGp > 0)
				{
					entry.setCollateralValue((int) Math.min(stash.collateralGp, Integer.MAX_VALUE));
					entry.setCollateralType("GP");
					entry.setCollateralGpOutstanding(stash.collateralGp);
				}
				if (stash.collateralItems != null)
				{
					entry.setCollateralItems(stash.collateralItems);
					entry.setCollateralItemIds(stash.collateralItemIds);
					entry.setCollateralOutstandingIds(stash.collateralItemIds);
				}
			}
			dataService.addLoan(stash.groupId, stash.lenderName, stash.partnerName, entry, dueTime);
			recorded.add(entry);
			adjustListingForLoan(stash.groupId, stash.lenderName, loan.itemId, loan.quantity);

			addGameMessage("Loan recorded: " + loan.name
				+ (loan.quantity > 1 ? " x" + loan.quantity : "") + " to " + stash.partnerName
				+ " (" + daysLabel(stash.days == 0 ? Math.max(1, config.defaultLoanDuration()) : stash.days)
				+ (first && stash.collateralGp > 0 ? ", collateral " + QuantityFormatter.quantityToStackSize(stash.collateralGp) + " GP" : "")
				+ ").");
			first = false;
		}
		// The trade's picture is long gone by the time a late "yes" arrives.
		discordWebhook.postBatch(DiscordWebhook.Event.LOAN, recorded, localPlayerName(), null, null);

		if (!stash.loans.isEmpty() && onLoanRecorded != null)
		{
			onLoanRecorded.run();
		}
	}

	/**
	 * A display-only entry describing MY collateral deposit (Collat mode), so the
	 * borrower's proof screenshot overlay names what was handed over. Never saved.
	 */
	private LendingEntry provisionalDepositEntry()
	{
		String me = localPlayerName();
		if (me == null || partner == null || finalMyOffer == null)
		{
			return null;
		}
		long gp = 0;
		List<String> names = new ArrayList<>();
		for (Item item : finalMyOffer)
		{
			if (item == null || item.getId() <= 0)
			{
				continue;
			}
			if (item.getId() == ItemID.COINS_995)
			{
				gp += item.getQuantity();
			}
			else if (item.getId() == ItemID.PLATINUM_TOKEN)
			{
				gp += item.getQuantity() * 1000L;
			}
			else
			{
				names.add(itemName(item.getId())
					+ (item.getQuantity() > 1 ? " x" + item.getQuantity() : ""));
			}
		}
		if (gp == 0 && names.isEmpty())
		{
			return null;
		}
		LendingEntry entry = new LendingEntry();
		entry.setItem("Collateral deposit");
		entry.setLender(partner);
		entry.setBorrower(me);
		if (gp > 0)
		{
			entry.setCollateralValue((int) Math.min(gp, Integer.MAX_VALUE));
			entry.setCollateralType("GP");
		}
		if (!names.isEmpty())
		{
			entry.setCollateralItems(String.join(", ", names));
		}
		return entry;
	}

	/** A display-only entry describing the stashed loans, for the screenshot overlay. */
	private LendingEntry provisionalEntryFromStash(PendingLoanDecision stash)
	{
		if (stash.loans.isEmpty())
		{
			return null;
		}
		StashedLoan loan = stash.loans.get(0);
		LendingEntry entry = new LendingEntry();
		entry.setItem(loan.name);
		entry.setItemId(loan.itemId);
		entry.setQuantity(loan.quantity);
		entry.setValue(loan.value);
		entry.setLender(stash.lenderName);
		entry.setBorrower(stash.partnerName);
		if (stash.collateralGp > 0)
		{
			entry.setCollateralValue((int) Math.min(stash.collateralGp, Integer.MAX_VALUE));
			entry.setCollateralType("GP");
		}
		return entry;
	}

	// --- Helpers ---

	/** Find an active loan where the local player borrowed an item matching itemId. */
	private LendingEntry findBorrowedEntry(int itemId)
	{
		String me = localPlayerName();
		if (me == null)
		{
			return null;
		}
		int baseId = ItemVariationMapping.map(itemId);
		for (LendingEntry e : dataService.getActiveEntries())
		{
			if (!e.isReturned() && me.equalsIgnoreCase(e.getBorrower())
				&& ItemVariationMapping.map(e.getItemId()) == baseId)
			{
				return e;
			}
		}
		return null;
	}

	/**
	 * Is a loan with this player outside what the group tracks? Returns why, for
	 * the chat message, or null when it's fine. For a clan group only a CONFIRMED
	 * non-member is refused: unknown - this client can't see that clan's list -
	 * still records, it just never reaches the clan's Discord, which needs a yes.
	 */
	private String outsideLoanScope(String groupId, String name)
	{
		if (groupId == null || name == null)
		{
			return null;
		}
		switch (groupService.getLoanScope(groupId))
		{
			case CLAN:
				String clan = groupService.getLinkedClan(groupId);
				clanRoster.refresh();
				return clanRoster.check(clan, name) == ClanRoster.Membership.NO
					? name + " isn't in " + clan + ", and this group only tracks loans inside the clan"
					: null;
			case GROUP:
				LendingGroup group = groupService.getGroup(groupId);
				return group != null && !group.hasMember(name)
					? name + " isn't in this group, and it only tracks loans between its members"
					: null;
			default:
				return null;
		}
	}

	private boolean isPartnerInLinkedClan()
	{
		LendingGroup group = groupService.getActiveGroup();
		return group != null && partner != null
			&& clanRoster.check(groupService.getLinkedClan(group.getId()), partner) == ClanRoster.Membership.YES;
	}

	private boolean isPartnerInActiveGroup()
	{
		if (partner == null)
		{
			return false;
		}
		LendingGroup group = groupService.getActiveGroup();
		return group != null && group.hasMember(partner);
	}

	private String readPartnerName(int componentId)
	{
		Widget widget = client.getWidget(componentId);
		if (widget == null || widget.getText() == null)
		{
			return null;
		}
		String text = Text.removeTags(widget.getText()).replace((char) 0xA0, ' ');
		// The game renders both "Trading with:" and "Trading With:" (capital W)
		// depending on the screen — match case-insensitively, like the RuneWatch
		// plugin does for the same widgets
		int idx = text.toLowerCase().indexOf(TRADING_WITH_PREFIX.toLowerCase());
		if (idx < 0)
		{
			return null;
		}
		String name = text.substring(idx + TRADING_WITH_PREFIX.length()).trim();
		return name.isEmpty() ? null : name;
	}

	private Item[] copyContainerItems(int containerId)
	{
		ItemContainer container = client.getItemContainer(containerId);
		return container != null ? container.getItems().clone() : null;
	}

	private int resolveOfferItemId(int slot)
	{
		ItemContainer offer = client.getItemContainer(InventoryID.TRADEOFFER);
		if (offer == null || slot < 0 || slot >= offer.getItems().length)
		{
			return -1;
		}
		return offer.getItems()[slot].getId();
	}

	private int resolveInventoryItemId(int slot)
	{
		ItemContainer inv = client.getItemContainer(InventoryID.INV);
		if (inv == null || slot < 0 || slot >= inv.getItems().length)
		{
			return -1;
		}
		return inv.getItems()[slot].getId();
	}

	/** Sum quantities per variation-base id from a live container. */
	private void collectBaseQuantities(Map<Integer, Integer> into, int containerId)
	{
		ItemContainer container = client.getItemContainer(containerId);
		if (container == null)
		{
			return;
		}
		for (Item item : container.getItems())
		{
			if (item != null && item.getId() > 0)
			{
				into.merge(ItemVariationMapping.map(item.getId()), item.getQuantity(), Integer::sum);
			}
		}
	}


	private String itemName(int itemId)
	{
		try
		{
			return itemManager.getItemComposition(itemId).getName();
		}
		catch (Exception e)
		{
			return "item " + itemId;
		}
	}

	private String localPlayerName()
	{
		return client.getLocalPlayer() != null ? client.getLocalPlayer().getName() : null;
	}

	private String activeGroupName()
	{
		LendingGroup group = groupService.getActiveGroup();
		return group != null ? group.getName() : null;
	}

	private String warnPrefix()
	{
		return "[Lending Tracker] ";
	}

	private void addGameMessage(String message)
	{
		client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", message, "");
	}
}

package com.guess34.lendingtracker.services;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import java.lang.reflect.Type;
import java.time.Instant;
import java.util.*;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.CopyOnWriteArrayList;
import java.util.stream.Collectors;
import java.util.stream.Stream;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.config.ConfigManager;

import com.guess34.lendingtracker.model.ItemSet;
import com.guess34.lendingtracker.model.LendingEntry;
import com.guess34.lendingtracker.model.LendingRequest;

import lombok.extern.slf4j.Slf4j;

/**
 * DataService - Unified data store for all lending tracker data.
 *
 * Consolidates the former Recorder, LendingManager, MarketplaceManager,
 * StorageService, and ItemSetManager into a single service.
 *
 * Handles: marketplace offerings, active loans, history, item sets,
 * and all persistence via ConfigManager.
 */
@Singleton
@Slf4j
public class DataService
{
	// Config keys (backward-compatible with old Recorder/StorageService)
	private static final String CONFIG_GROUP = "lendingtracker";
	private static final String KEY_PREFIX = "lendingtracker.recorder.";
	private static final String ENTRIES_KEY = "lendingtracker.entries";
	private static final String HISTORY_KEY = "lendingtracker.history";
	private static final String ITEMSETS_KEY_PREFIX = "itemsets.";

	// Multi-group data storage (marketplace / lent / borrowed)
	private final Map<String, Map<String, List<LendingEntry>>> groupLent = new ConcurrentHashMap<>();
	private final Map<String, Map<String, List<LendingEntry>>> groupBorrowed = new ConcurrentHashMap<>();
	private final Map<String, Map<String, List<LendingEntry>>> groupAvailable = new ConcurrentHashMap<>();

	// Global entries storage (all entries regardless of group)
	private final Map<String, LendingEntry> allEntries = new ConcurrentHashMap<>();
	private final List<LendingEntry> historyEntries = new CopyOnWriteArrayList<>();

	// Direct lending requests (borrow requests / lend offers): groupId -> requests
	private final Map<String, List<LendingRequest>> groupRequests = new ConcurrentHashMap<>();

	// Delisting tombstones: groupId -> "lender:itemId" -> when it was removed.
	//
	// A removal used to be communicated only by ABSENCE from the snapshot, and
	// absence does not survive a union merge - any peer still holding the row put
	// it straight back, and with every client republishing its whole state on a
	// timer the two sides took turns undoing each other. Saying "this was removed,
	// at this time" is a statement a merge can actually honour.
	//
	// Same shape as LendingGroup.removedMembers, which solved the same problem for
	// kicks: union by newest time, and a re-listing newer than the tombstone wins.
	private final Map<String, Map<String, Long>> removedListings = new ConcurrentHashMap<>();

	// How far apart two players' clocks may be before we stop trusting a
	// comparison between them. Player PCs aren't guaranteed to run NTP, and a
	// tombstone stamped by one machine is compared against a row stamped by
	// another - without slack, a few minutes of drift silently eats a listing
	// somebody created seconds ago.
	private static final long CLOCK_SKEW_ALLOWANCE_MS = 10L * 60000L;

	/** Stable key for one member's listing of one item. */
	private static String listingKey(String lender, int itemId)
	{
		return (lender == null ? "" : lender.toLowerCase().replace('_', ' ').trim()) + ":" + itemId;
	}

	/** Record that a listing was removed, so the removal can propagate. */
	private void tombstoneListing(String groupId, String lender, int itemId)
	{
		if (groupId == null) return;
		removedListings.computeIfAbsent(groupId, k -> new ConcurrentHashMap<>())
			.put(listingKey(lender, itemId), System.currentTimeMillis());
	}

	// Item sets: groupId -> setId -> ItemSet
	private final Map<String, Map<String, ItemSet>> groupItemSets = new ConcurrentHashMap<>();

	// Injected dependencies
	@Inject private ConfigManager configManager;
	@Inject private Gson gson;
	@Inject private GroupService groupService;

	private boolean initialized = false;

	public DataService()
	{
		// For @Inject usage
	}

	// Initialization

	public void initialize()
	{
		if (initialized)
		{
			return;
		}

		loadEntries();
		initialized = true;
	}

	/**
	 * Flatten a group's nested map (owner -> entries) into a single list.
	 * Returns an empty list if the group has no data.
	 */
	private List<LendingEntry> flattenGroupData(Map<String, Map<String, List<LendingEntry>>> store, String groupId)
	{
		Map<String, List<LendingEntry>> groupData = store.get(groupId);
		if (groupData == null)
		{
			return new ArrayList<>();
		}
		return groupData.values().stream()
			.flatMap(List::stream)
			.collect(Collectors.toList());
	}

	// Marketplace / Available items

	public void addAvailable(String groupId, String owner, LendingEntry entry)
	{
		entry.setGroupId(groupId);
		entry.setLender(owner);
		entry.setUpdatedAt(System.currentTimeMillis());

		List<LendingEntry> ownerList = groupAvailable
			.computeIfAbsent(groupId, k -> new ConcurrentHashMap<>())
			.computeIfAbsent(owner, k -> new CopyOnWriteArrayList<>());

		boolean alreadyExists = ownerList.stream()
			.anyMatch(e -> e.getItemId() == entry.getItemId());

		if (alreadyExists)
		{
			for (LendingEntry existing : ownerList)
			{
				if (existing.getItemId() == entry.getItemId())
				{
					existing.setQuantity(existing.getQuantity() + entry.getQuantity());
					// Restocking is a change, so the stored row has to say so. Without
					// this the row keeps its original time, which both loses the merge
					// against a peer's older copy and leaves it looking old enough for
					// any later delisting tombstone to delete it.
					existing.setUpdatedAt(entry.getUpdatedAt());
					break;
				}
			}
		}
		else
		{
			// A piece coming back from a loan is relisted as a brand new row, so it
			// would come back loose. The lender's own machine remembers which set
			// it was in; putting it back is what makes the set regroup itself.
			if (!entry.isInSet())
			{
				String[] remembered = rememberedSet(groupId, owner, entry.getItemId());
				if (remembered != null)
				{
					entry.setSetId(remembered[0]);
					entry.setSetName(remembered[1]);
				}
			}
			ownerList.add(new LendingEntry(entry));
		}

		persist(groupId, "available");

		if (groupService != null)
		{
			groupService.publishEvent(
				alreadyExists ? GroupService.SyncEventType.ITEM_UPDATED : GroupService.SyncEventType.ITEM_ADDED,
				entry.getId() != null ? entry.getId() : String.valueOf(entry.getItemId()),
				entry
			);
		}
	}

	/**
	 * Restore an available item from sync data - does NOT add to quantity if item already exists.
	 * Used by LocalDataSyncService to prevent quantity duplication on login.
	 */
	public void restoreAvailable(String groupId, String owner, LendingEntry entry)
	{
		entry.setGroupId(groupId);
		entry.setLender(owner);

		List<LendingEntry> ownerList = groupAvailable
			.computeIfAbsent(groupId, k -> new ConcurrentHashMap<>())
			.computeIfAbsent(owner, k -> new CopyOnWriteArrayList<>());

		boolean alreadyExists = ownerList.stream()
			.anyMatch(e ->
				(entry.getId() != null && entry.getId().equals(e.getId())) ||
				(e.getItemId() == entry.getItemId() && Objects.equals(e.getLender(), entry.getLender()))
			);

		if (alreadyExists)
		{
			return;
		}

		ownerList.add(new LendingEntry(entry));
		persist(groupId, "available");
	}

	public void removeAvailable(String groupId, String owner, String itemName, int itemId)
	{
		Map<String, List<LendingEntry>> groupData = groupAvailable.get(groupId);
		if (groupData != null)
		{
			List<LendingEntry> ownerItems = groupData.get(owner);
			if (ownerItems != null)
			{
				ownerItems.removeIf(entry ->
					entry.getItem().equals(itemName) && entry.getItemId() == itemId
				);
				tombstoneListing(groupId, owner, itemId);
				persist(groupId, "available");

				if (groupService != null)
				{
					groupService.publishEvent(
						GroupService.SyncEventType.ITEM_REMOVED,
						itemName + "_" + itemId,
						null
					);
				}
			}
		}
	}

	public void updateAvailable(String groupId, String owner, String itemName, int itemId, LendingEntry updatedEntry)
	{
		Map<String, List<LendingEntry>> groupData = groupAvailable.get(groupId);
		if (groupData != null)
		{
			List<LendingEntry> ownerItems = groupData.get(owner);
			if (ownerItems != null)
			{
				for (int i = 0; i < ownerItems.size(); i++)
				{
					LendingEntry entry = ownerItems.get(i);
					if (entry.getItem().equals(itemName) && entry.getItemId() == itemId)
					{
						updatedEntry.setGroupId(groupId);
						updatedEntry.setLender(owner);
						updatedEntry.setUpdatedAt(System.currentTimeMillis());
						ownerItems.set(i, new LendingEntry(updatedEntry));
						persist(groupId, "available");

						if (groupService != null)
						{
							groupService.publishEvent(
								GroupService.SyncEventType.ITEM_UPDATED,
								updatedEntry.getId() != null ? updatedEntry.getId() : String.valueOf(itemId),
								updatedEntry
							);
						}
						break;
					}
				}
			}
		}
	}

	public List<LendingEntry> getAvailable(String groupId)
	{
		return flattenGroupData(groupAvailable, groupId);
	}

	// --- Item sets ---
	//
	// A set is whichever of one owner's listings share a setId. Only the owner
	// ever changes it, and only from their own machine - which is also where the
	// memory of each piece's set lives, so a piece lent out and relisted on return
	// rejoins its set without anything new crossing the wire.

	private static final String SET_MEMORY_PREFIX = "setMembers.";

	/**
	 * Put these of the owner's listings into a set, or take them out of any set
	 * when setId is null. One save and one sync for the lot rather than one per
	 * piece - a set of eight was eight full state pushes.
	 *
	 * @return how many listings changed
	 */
	public int applySetToListings(String groupId, String owner, Collection<Integer> itemIds,
		String setId, String setName)
	{
		if (groupId == null || owner == null || itemIds == null || itemIds.isEmpty()) return 0;
		Map<String, List<LendingEntry>> groupData = groupAvailable.get(groupId);
		if (groupData == null) return 0;
		String ownerKey = groupData.keySet().stream()
			.filter(k -> k.equalsIgnoreCase(owner)).findFirst().orElse(null);
		if (ownerKey == null) return 0;
		List<LendingEntry> ownerItems = groupData.get(ownerKey);
		long now = System.currentTimeMillis();
		Map<Integer, String> memory = loadSetMemory(groupId, owner);
		int changed = 0;
		for (int i = 0; i < ownerItems.size(); i++)
		{
			LendingEntry e = ownerItems.get(i);
			if (e == null || !itemIds.contains(e.getItemId())) continue;
			LendingEntry updated = new LendingEntry(e);
			updated.setSetId(setId);
			updated.setSetName(setId != null ? setName : null);
			updated.setUpdatedAt(now);
			ownerItems.set(i, updated);
			int base = net.runelite.client.game.ItemVariationMapping.map(e.getItemId());
			if (setId != null) memory.put(base, setId + "|" + (setName != null ? setName : ""));
			else memory.remove(base);
			changed++;
		}
		if (changed == 0) return 0;
		saveSetMemory(groupId, owner, memory);
		persist(groupId, "available");
		if (groupService != null)
		{
			groupService.publishEvent(GroupService.SyncEventType.ITEM_UPDATED, groupId + ":sets", null);
		}
		return changed;
	}

	/** The item ids of the owner's listings currently in this set. */
	public List<Integer> getSetPieces(String groupId, String owner, String setId)
	{
		List<Integer> ids = new ArrayList<>();
		if (setId == null) return ids;
		for (LendingEntry e : getOfferingsByOwner(groupId, owner))
		{
			if (setId.equals(e.getSetId())) ids.add(e.getItemId());
		}
		return ids;
	}

	/** Rename a set everywhere it appears. */
	public void renameSet(String groupId, String owner, String setId, String newName)
	{
		applySetToListings(groupId, owner, getSetPieces(groupId, owner, setId), setId, newName);
	}

	/** Break a set back into loose listings. */
	public void breakSet(String groupId, String owner, String setId)
	{
		applySetToListings(groupId, owner, getSetPieces(groupId, owner, setId), null, null);
		// Pieces out on loan right now aren't listed, so the loop above never saw
		// them - clear their memory too, or they rejoin a dead set on return.
		Map<Integer, String> memory = loadSetMemory(groupId, owner);
		if (memory.values().removeIf(v -> v.startsWith(setId + "|")))
		{
			saveSetMemory(groupId, owner, memory);
		}
	}

	/**
	 * The owner took this piece off the marketplace themselves, so it should not
	 * rejoin its set if they list it again later. (Lending it out is different -
	 * that delists it too, and the whole point is that it comes back.)
	 */
	public void forgetSetMembership(String groupId, String owner, int itemId)
	{
		Map<Integer, String> memory = loadSetMemory(groupId, owner);
		if (memory.remove(net.runelite.client.game.ItemVariationMapping.map(itemId)) != null)
		{
			saveSetMemory(groupId, owner, memory);
		}
	}

	/** {setId, setName} this owner last had the item in, or null. */
	private String[] rememberedSet(String groupId, String owner, int itemId)
	{
		if (groupId == null || owner == null) return null;
		String v = loadSetMemory(groupId, owner).get(net.runelite.client.game.ItemVariationMapping.map(itemId));
		if (v == null) return null;
		int bar = v.indexOf('|');
		if (bar <= 0) return null;
		return new String[] { v.substring(0, bar), v.substring(bar + 1) };
	}

	private Map<Integer, String> loadSetMemory(String groupId, String owner)
	{
		String json = configManager.getConfiguration(CONFIG_GROUP,
			SET_MEMORY_PREFIX + groupId + "." + owner.toLowerCase());
		if (json == null || json.isEmpty()) return new HashMap<>();
		try
		{
			Map<Integer, String> m = gson.fromJson(json, new TypeToken<Map<Integer, String>>(){}.getType());
			return m != null ? new HashMap<>(m) : new HashMap<>();
		}
		catch (Exception e)
		{
			return new HashMap<>();
		}
	}

	private void saveSetMemory(String groupId, String owner, Map<Integer, String> memory)
	{
		String key = SET_MEMORY_PREFIX + groupId + "." + owner.toLowerCase();
		if (memory.isEmpty()) configManager.unsetConfiguration(CONFIG_GROUP, key);
		else configManager.setConfiguration(CONFIG_GROUP, key, gson.toJson(memory));
	}

	// --- Looking For posts ---

	/** Live Looking For posts in this group, newest first. */
	public List<LendingRequest> getLookingForPosts(String groupId)
	{
		return getRequests(groupId).stream()
			.filter(r -> r.isLookingFor() && r.isPending())
			.sorted(Comparator.comparingLong(LendingRequest::getCreatedAt).reversed())
			.collect(Collectors.toList());
	}

	public void addToAvailableList(LendingEntry entry, String groupId)
	{
		addAvailable(groupId, entry.getLender(), entry);
	}

	/** Add a marketplace offering (MarketplaceManager API). */
	public void addOffering(String groupId, String ownerName, LendingEntry entry)
	{
		if (groupId == null || ownerName == null || entry == null)
		{
			throw new IllegalArgumentException("Invalid offering parameters");
		}
		addAvailable(groupId, ownerName, entry);
	}

	/** Remove a marketplace offering (MarketplaceManager API). */
	public void removeOffering(String groupId, String ownerName, String itemName, int itemId)
	{
		if (groupId == null || ownerName == null)
		{
			throw new IllegalArgumentException("Invalid removal parameters");
		}
		removeAvailable(groupId, ownerName, itemName, itemId);
	}

	public List<LendingEntry> getOfferingsByOwner(String groupId, String ownerName)
	{
		List<LendingEntry> all = getAvailable(groupId);
		if (all == null || ownerName == null)
		{
			return Collections.emptyList();
		}
		return all.stream()
			.filter(e -> ownerName.equalsIgnoreCase(e.getLender()))
			.collect(Collectors.toList());
	}

	/** Remove all items for a specific lender (used when a member is kicked). */
	public void removeItemsForLender(String groupId, String lenderName)
	{
		if (groupId == null || lenderName == null)
		{
			return;
		}

		Map<String, List<LendingEntry>> groupData = groupAvailable.get(groupId);
		if (groupData != null)
		{
			// Names are keyed however the publishing client happened to capitalise
			// them, so an exact-case remove left a kicked member's listings behind.
			// Everything else in this file compares names with equalsIgnoreCase.
			List<LendingEntry> removed = null;
			for (String key : new ArrayList<>(groupData.keySet()))
			{
				if (key != null && key.equalsIgnoreCase(lenderName))
				{
					List<LendingEntry> hit = groupData.remove(key);
					if (hit != null)
					{
						if (removed == null)
						{
							removed = new ArrayList<>();
						}
						removed.addAll(hit);
					}
				}
			}
			if (removed != null)
			{
				for (LendingEntry e : removed)
				{
					tombstoneListing(groupId, lenderName, e.getItemId());
				}
			}
			if (removed != null && !removed.isEmpty())
			{
				persist(groupId, "available");
				if (groupService != null)
				{
					groupService.publishEvent(
						GroupService.SyncEventType.ITEM_REMOVED,
						groupId + ":" + lenderName,
						null
					);
				}
			}
		}
	}

	// Lending / Borrowing

	/**
	 * Restore a borrowed entry from sync data - does NOT add if entry already exists.
	 */
	public void restoreBorrowed(String groupId, String borrower, LendingEntry entry)
	{
		entry.setGroupId(groupId);
		entry.setBorrower(borrower);

		List<LendingEntry> borrowerList = groupBorrowed
			.computeIfAbsent(groupId, k -> new ConcurrentHashMap<>())
			.computeIfAbsent(borrower, k -> new CopyOnWriteArrayList<>());

		boolean alreadyExists = borrowerList.stream()
			.anyMatch(e ->
				(entry.getId() != null && entry.getId().equals(e.getId())) ||
				(e.getItemId() == entry.getItemId() && Objects.equals(e.getBorrower(), entry.getBorrower()))
			);

		if (alreadyExists)
		{
			return;
		}

		borrowerList.add(new LendingEntry(entry));
		persist(groupId, "borrowed");
	}

	/**
	 * Restore a lent entry from sync data - does NOT add if entry already exists.
	 */
	public void restoreLent(String groupId, String lender, String borrower, LendingEntry entry, long dueTime)
	{
		entry.setGroupId(groupId);
		entry.setLender(lender);
		entry.setBorrower(borrower);
		entry.setDueTime(dueTime);

		List<LendingEntry> lenderList = groupLent
			.computeIfAbsent(groupId, k -> new ConcurrentHashMap<>())
			.computeIfAbsent(lender, k -> new CopyOnWriteArrayList<>());

		boolean alreadyExists = lenderList.stream()
			.anyMatch(e ->
				(entry.getId() != null && entry.getId().equals(e.getId())) ||
				(e.getItemId() == entry.getItemId() &&
				 Objects.equals(e.getLender(), entry.getLender()) &&
				 Objects.equals(e.getBorrower(), entry.getBorrower()))
			);

		if (alreadyExists)
		{
			return;
		}

		lenderList.add(new LendingEntry(entry));
		persist(groupId, "lent");
	}

	/** Add a new loan (LendingManager API). */
	public void addLoan(String groupId, String lender, String borrower, LendingEntry entry, long dueTime)
	{
		if (groupId == null || lender == null || borrower == null || entry == null)
		{
			throw new IllegalArgumentException("Invalid loan parameters");
		}

		entry.setGroupId(groupId);
		entry.setLender(lender);
		entry.setBorrower(borrower);
		entry.setLendTime(System.currentTimeMillis());
		entry.setDueTime(dueTime);
		entry.setReturnedAt(0);
		entry.setUpdatedAt(System.currentTimeMillis());

		allEntries.put(entry.getId(), entry);

		groupLent.computeIfAbsent(groupId, k -> new ConcurrentHashMap<>())
			.computeIfAbsent(lender, k -> new CopyOnWriteArrayList<>())
			.add(entry);

		groupBorrowed.computeIfAbsent(groupId, k -> new ConcurrentHashMap<>())
			.computeIfAbsent(borrower, k -> new CopyOnWriteArrayList<>())
			.add(entry);

		saveEntries();
		// persist() writes the whole group snapshot regardless of category, so a
		// single call covers both the lent and borrowed changes.
		persist(groupId, "loan");

		if (groupService != null)
		{
			groupService.publishEvent(
				GroupService.SyncEventType.ITEM_ADDED,
				entry.getId(),
				entry
			);
		}
	}

	// Direct lending requests (borrow requests / lend offers)

	/** Add a new request and sync it to the group. */
	public void addRequest(String groupId, LendingRequest request)
	{
		if (groupId == null || request == null || request.getId() == null)
		{
			return;
		}

		request.setGroupId(groupId);
		List<LendingRequest> requests = groupRequests
			.computeIfAbsent(groupId, k -> new CopyOnWriteArrayList<>());
		requests.removeIf(r -> request.getId().equals(r.getId()));
		requests.add(request);

		persist(groupId, "requests");

		if (groupService != null)
		{
			groupService.publishEvent(
				GroupService.SyncEventType.REQUEST_CREATED,
				request.getId(),
				request
			);
		}
	}

	/** Update a request's status (accept/decline/cancel) and sync the change. */
	public void updateRequestStatus(String groupId, String requestId, String status)
	{
		List<LendingRequest> requests = groupRequests.get(groupId);
		if (requests == null || requestId == null)
		{
			return;
		}

		for (LendingRequest r : requests)
		{
			if (requestId.equals(r.getId()))
			{
				r.setStatus(status);
				// Somebody actually decided, so this is no longer an expiry. Left
				// set, the flag outranks the status when notifying and the requester
				// is told nobody answered a request that was in fact answered.
				r.setExpired(false);
				r.setUpdatedAt(System.currentTimeMillis());
				persist(groupId, "requests");

				if (groupService != null)
				{
					groupService.publishEvent(
						GroupService.SyncEventType.REQUEST_UPDATED,
						requestId,
						r
					);
				}
				return;
			}
		}
	}

	/** All requests for a group (any status). */
	public List<LendingRequest> getRequests(String groupId)
	{
		List<LendingRequest> requests = groupRequests.get(groupId);
		if (requests == null)
		{
			return new ArrayList<>();
		}
		synchronized (requests)
		{
			return new ArrayList<>(requests);
		}
	}

	/** Pending requests addressed TO the given player. */
	public List<LendingRequest> getPendingRequestsFor(String groupId, String playerName)
	{
		if (playerName == null)
		{
			return new ArrayList<>();
		}
		return getRequests(groupId).stream()
			.filter(r -> r.isPending() && playerName.equalsIgnoreCase(r.getTo()))
			.collect(Collectors.toList());
	}

	/** Requests created BY the given player. */
	public List<LendingRequest> getRequestsFrom(String groupId, String playerName)
	{
		if (playerName == null)
		{
			return new ArrayList<>();
		}
		return getRequests(groupId).stream()
			.filter(r -> playerName.equalsIgnoreCase(r.getFrom()))
			.collect(Collectors.toList());
	}

	/**
	 * Drop resolved (non-pending) requests last updated before the cutoff across
	 * all groups, so the synced snapshot doesn't grow without bound. Returns the
	 * number removed.
	 */
	public int pruneResolvedRequests(long cutoffTime)
	{
		int removed = 0;
		for (Map.Entry<String, List<LendingRequest>> entry : groupRequests.entrySet())
		{
			List<LendingRequest> list = entry.getValue();
			synchronized (list)
			{
				int before = list.size();
				list.removeIf(r -> !r.isPending() && r.getUpdatedAt() < cutoffTime);
				int delta = before - list.size();
				if (delta > 0)
				{
					removed += delta;
					persist(entry.getKey(), "requests");
				}
			}
		}
		return removed;
	}

	// Getters for lent/borrowed/available lists

	public List<LendingEntry> getLent(String groupId)
	{
		return flattenGroupData(groupLent, groupId);
	}

	public List<LendingEntry> getBorrowed(String groupId)
	{
		return flattenGroupData(groupBorrowed, groupId);
	}

	// Global entries (allEntries map)

	public void addEntry(LendingEntry entry)
	{
		if (entry == null || entry.getId() == null)
		{
			return;
		}

		entry.setUpdatedAt(System.currentTimeMillis());
		allEntries.put(entry.getId(), new LendingEntry(entry));
		saveEntries();
		if (groupService != null && entry.getGroupId() != null)
		{
			groupService.publishEvent(
				GroupService.SyncEventType.ITEM_ADDED,
				entry.getId(),
				entry
			);
		}
	}

	/**
	 * Restore an entry from a LOCAL BACKUP file. Unlike {@link #addEntry} this
	 * PRESERVES the entry's original updatedAt and publishes nothing: a backup is
	 * a point-in-time copy, and stamping it "now" would let stale return tallies
	 * win last-write-wins against the whole group's fresher state (e.g. a partial
	 * return silently rolling back to fully-outstanding everywhere).
	 */
	public void restoreEntry(LendingEntry entry)
	{
		if (entry == null || entry.getId() == null)
		{
			return;
		}
		allEntries.put(entry.getId(), new LendingEntry(entry));
		saveEntries();
	}

	public List<LendingEntry> getActiveEntries()
	{
		return allEntries.values().stream()
			.filter(entry -> !entry.isReturned())
			.collect(Collectors.toList());
	}

	public List<LendingEntry> getHistoryEntries()
	{
		return new ArrayList<>(historyEntries);
	}

	/**
	 * Loans in this group that still owe something in either direction and that
	 * the named player is a party to — as lender or borrower.
	 *
	 * Uses isFullySettled() rather than isReturned() on purpose: a loan can have
	 * the item home while the lender still holds collateral, and walking away
	 * from that is exactly what this is meant to prevent. History is checked too,
	 * as a safety net in case any path archives an entry before it settles.
	 */
	public List<LendingEntry> getUnsettledFor(String groupId, String playerName)
	{
		if (groupId == null || playerName == null)
		{
			return new ArrayList<>();
		}
		Map<String, LendingEntry> byId = new LinkedHashMap<>();
		Stream.concat(allEntries.values().stream(), historyEntries.stream())
			.filter(e -> e != null && groupId.equals(e.getGroupId()))
			.filter(e -> playerName.equalsIgnoreCase(e.getLender())
				|| playerName.equalsIgnoreCase(e.getBorrower()))
			.filter(e -> !e.isFullySettled())
			.forEach(e -> byId.putIfAbsent(e.getId(), e));
		return new ArrayList<>(byId.values());
	}
	/**
	 * Every unsettled loan anywhere in this group, whoever the parties are.
	 *
	 * getUnsettledFor answers "may THIS player walk away". This answers "is the
	 * group finished with", which is a different question: disbanding destroys the
	 * record of who owes what to whom, for everybody at once, so it has to wait
	 * until nothing at all is outstanding - not merely nothing of the owner's.
	 */
	public List<LendingEntry> getAllUnsettled(String groupId)
	{
		if (groupId == null)
		{
			return new ArrayList<>();
		}
		Map<String, LendingEntry> byId = new LinkedHashMap<>();
		Stream.concat(allEntries.values().stream(), historyEntries.stream())
			.filter(e -> e != null && groupId.equals(e.getGroupId()))
			.filter(e -> !e.isFullySettled())
			.forEach(e -> byId.putIfAbsent(e.getId(), e));
		return new ArrayList<>(byId.values());
	}

	/**
	 * Drop every request this player is a party to when they leave or are removed.
	 * Both directions matter: a request addressed TO someone who is gone leaves
	 * the other party waiting on a reply that can never come.
	 */
	/**
	 * Cancel every request this player is a party to when they leave or are removed.
	 *
	 * CANCELS rather than deletes on purpose. Deleting communicates the change only
	 * by absence, and mergeRequests is a union - any peer still holding the request
	 * puts it straight back. A cancelled status is a statement the merge already
	 * understands (it adopts a newer status), so it actually propagates. The rows
	 * then fall away on their own via the normal retention sweep.
	 *
	 * Both directions matter: a request addressed TO someone who is gone leaves the
	 * other party waiting on a reply that can never come.
	 */
	public int removeRequestsInvolving(String groupId, String playerName)
	{
		if (groupId == null || playerName == null) return 0;
		List<LendingRequest> requests = groupRequests.get(groupId);
		if (requests == null) return 0;

		int changed = 0;
		long now = System.currentTimeMillis();
		synchronized (requests)
		{
			for (LendingRequest r : requests)
			{
				if (r == null || !r.isPending()) continue;
				if (playerName.equalsIgnoreCase(r.getFrom()) || playerName.equalsIgnoreCase(r.getTo()))
				{
					r.setStatus(LendingRequest.STATUS_CANCELLED);
					r.setUpdatedAt(now);
					changed++;
				}
			}
		}
		if (changed > 0)
		{
			persist(groupId, "requests");
			saveEntries();
			if (groupService != null)
			{
				groupService.publishEvent(GroupService.SyncEventType.ITEM_UPDATED,
					groupId + ":requests", null);
			}
		}
		return changed;
	}

	/** How long a request may sit unanswered before it is auto-expired. */
	public static final long PENDING_REQUEST_EXPIRY_MS = 14L * 86400000L;

	/** When a request was raised. Falls back to updatedAt for rows predating createdAt. */
	private static long requestAge(LendingRequest r)
	{
		return r.getCreatedAt() > 0 ? r.getCreatedAt() : r.getUpdatedAt();
	}

	/**
	 * How settled a request is, for merging. Somebody answering it beats the
	 * clock running out on it, which beats nobody having touched it yet.
	 *
	 * Cancelled shares a rank whether a person did it or the timer did, because
	 * the two are indistinguishable to a client that predates the expiry flag -
	 * it relays a timed-out request as a plain cancellation. Ranking on the flag
	 * would let whichever copy arrived last decide, which is the coin-flip this
	 * exists to remove.
	 */
	private static int outcomeRank(LendingRequest r)
	{
		if (r.isPending()) return 0;
		if (LendingRequest.STATUS_CANCELLED.equals(r.getStatus())) return 1;
		return 2;
	}

	/**
	 * Auto-expire requests nobody ever answered. pruneResolvedRequests only touches
	 * non-pending rows, so an unanswered request lived forever and was re-added by
	 * every peer that still had it - the single largest source of payload growth.
	 * Marking it (not deleting it) means the expiry propagates; retention clears it later.
	 *
	 * Cancelled AND flagged expired. The flag is what lets the requester be told:
	 * a cancellation is somebody's decision and they already know, but an expiry is
	 * the plugin quietly giving up on their behalf, and going silent there is how a
	 * dispute vanishes with nobody ever learning it died.
	 *
	 * @return the requests that were expired, so the caller can notify.
	 */
	public List<LendingRequest> expirePendingRequests(long olderThanMs)
	{
		List<LendingRequest> expired = new ArrayList<>();
		long now = System.currentTimeMillis();
		for (Map.Entry<String, List<LendingRequest>> g : groupRequests.entrySet())
		{
			int changed = 0;
			synchronized (g.getValue())
			{
				for (LendingRequest r : g.getValue())
				{
					if (r == null || !r.isPending()) continue;
					long born = requestAge(r);
					if (born > 0 && born < olderThanMs)
					{
						r.setStatus(LendingRequest.STATUS_CANCELLED);
						r.setExpired(true);
						r.setUpdatedAt(now);
						expired.add(r);
						changed++;
					}
				}
			}
			if (changed > 0)
			{
				persist(g.getKey(), "requests");
			}
		}
		if (!expired.isEmpty()) saveEntries();
		return expired;
	}

	public int removeOldHistoryEntries(long olderThanMs)
	{
		int sizeBefore = historyEntries.size();
		historyEntries.removeIf(entry ->
			entry.getReturnedAt() > 0 && entry.getReturnedAt() < olderThanMs
		);
		int removed = sizeBefore - historyEntries.size();
		if (removed > 0)
		{
			saveEntries();
		}
		return removed;
	}

	/**
	 * Overdue loans this player is a party to - lender or borrower.
	 *
	 * allEntries holds every group this machine has ever loaded, and every loan in
	 * each of them, not just ours. Unscoped, a 70-member group meant an hourly alert
	 * for every late loan anyone had, and a group you had left or been removed from
	 * kept alerting forever. Scoping to the player fixes both at the source, so
	 * leaving a group never has to delete loan records to stop the noise - and the
	 * loans you are still owed, or still owe, keep reminding you wherever they are.
	 */
	public List<LendingEntry> getOverdueEntries(String playerName)
	{
		if (playerName == null || playerName.isEmpty())
		{
			return new ArrayList<>();
		}
		long currentTime = Instant.now().toEpochMilli();
		return allEntries.values().stream()
			.filter(entry -> !entry.isReturned() && entry.getDueDate() > 0 && entry.getDueDate() < currentTime)
			.filter(entry -> playerName.equalsIgnoreCase(entry.getLender())
				|| playerName.equalsIgnoreCase(entry.getBorrower()))
			.collect(Collectors.toList());
	}

	/**
	 * Persist and sync a PARTIAL return: the entry's outstanding tallies changed
	 * but the loan isn't fully settled yet, so it stays active. Bumps updatedAt
	 * (last-write-wins) and pushes the change live so every member's panel shows
	 * the new "still to return" state immediately.
	 */
	public void updateEntryProgress(LendingEntry entry)
	{
		if (entry == null || entry.getId() == null)
		{
			return;
		}
		entry.setUpdatedAt(System.currentTimeMillis());
		allEntries.put(entry.getId(), entry);
		saveEntries();
		if (entry.getGroupId() != null)
		{
			persist(entry.getGroupId(), "loan");
		}
		if (groupService != null && entry.getGroupId() != null)
		{
			groupService.publishEvent(
				GroupService.SyncEventType.ITEM_UPDATED,
				entry.getId(),
				entry
			);
		}
	}

	public void completeEntry(String entryId, boolean returned)
	{
		LendingEntry entry = allEntries.get(entryId);
		if (entry != null)
		{
			if (returned)
			{
				entry.setReturnedAt(Instant.now().toEpochMilli());
			}
			entry.setUpdatedAt(System.currentTimeMillis());
			entry.markSettled();
		historyEntries.add(new LendingEntry(entry));
			if (returned)
			{
				allEntries.remove(entryId);
				// Drop it from the group lists too, the way forgiveLoan and the staff
				// removal path already do. Left behind, the row kept being published
				// as an active loan, and after a restart it no longer shared an object
				// with the history copy — so its returnedAt stayed 0 and no retention
				// sweep could ever reap it.
				removeEntryFromCategory(groupLent, entryId);
				removeEntryFromCategory(groupBorrowed, entryId);
				// The group lists live in the per-group snapshot key, which only
				// persist() writes — saveEntries() covers just entries/history. Skip
				// it and the next loadGroupData resurrects the row from stale config.
				if (entry.getGroupId() != null)
				{
					persist(entry.getGroupId(), "returned");
				}
			}
			saveEntries();
			if (groupService != null && entry.getGroupId() != null)
			{
				groupService.publishEvent(
					GroupService.SyncEventType.ITEM_RETURNED,
					entryId,
					entry
				);
			}
		}
	}

	/**
	 * Remove an active loan and archive it to history as "forgiven by the lender".
	 * The lender is the creditor, so dropping their own claim harms no one — this
	 * is only offered for loans with NO collateral (a collateralised loan is a real
	 * exchange that could be disputed, so it needs the two-party / staff paths).
	 *
	 * Propagates like a return (the lender is authoritative for their own loans, so
	 * peers archive it and it won't be resurrected). Returns false if not found.
	 */
	public boolean forgiveLoan(String entryId, String actingLender)
	{
		LendingEntry entry = allEntries.get(entryId);
		if (entry == null)
		{
			return false;
		}
		// Only the lender may forgive, and only when no collateral is held
		if (actingLender == null || !actingLender.equalsIgnoreCase(entry.getLender()) || hasCollateral(entry))
		{
			return false;
		}

		long now = System.currentTimeMillis();
		entry.setReturnedAt(now); // close it out for history/overdue purposes
		entry.setUpdatedAt(now);
		String stamp = "[Forgiven by lender " + actingLender + "]";
		entry.setNotes(entry.getNotes() == null || entry.getNotes().isEmpty()
			? stamp : entry.getNotes() + " " + stamp);

		entry.markSettled();
		historyEntries.add(new LendingEntry(entry));
		allEntries.remove(entryId);
		removeEntryFromCategory(groupLent, entryId);
		removeEntryFromCategory(groupBorrowed, entryId);
		// The group lists only reach config via persist() — saveEntries() covers
		// just entries/history. Without it the next loadGroupData resurrects the
		// removed row from the stale per-group snapshot.
		if (entry.getGroupId() != null)
		{
			persist(entry.getGroupId(), "returned");
		}
		saveEntries();

		if (groupService != null && entry.getGroupId() != null)
		{
			groupService.publishEvent(GroupService.SyncEventType.ITEM_RETURNED, entryId, entry);
		}
		return true;
	}

	/**
	 * True if the lender STILL HOLDS collateral against this loan. Uses the
	 * running tally: once every deposit went back to the borrower, forgiving the
	 * loan strands nothing — the lender is only dropping their own claim.
	 */
	public static boolean hasCollateral(LendingEntry entry)
	{
		return entry.outstandingCollateralGp() > 0
			|| !entry.outstandingCollateralIds().isEmpty();
	}

	/**
	 * Remove an active loan because its removal request was APPROVED (by the
	 * counterparty, or by uninvolved staff). Archives to history with an audit
	 * stamp naming the approval, so a removal is never silent. Propagates like a
	 * return. The caller enforces WHO may trigger this; returns false if the loan
	 * is already gone (idempotent).
	 */
	public boolean removeLoanApproved(String entryId, String auditStamp)
	{
		LendingEntry entry = allEntries.get(entryId);
		if (entry == null)
		{
			return false;
		}

		long now = System.currentTimeMillis();
		entry.setReturnedAt(now);
		entry.setUpdatedAt(now);
		entry.setNotes(entry.getNotes() == null || entry.getNotes().isEmpty()
			? auditStamp : entry.getNotes() + " " + auditStamp);

		entry.markSettled();
		historyEntries.add(new LendingEntry(entry));
		allEntries.remove(entryId);
		removeEntryFromCategory(groupLent, entryId);
		removeEntryFromCategory(groupBorrowed, entryId);
		// The group lists only reach config via persist() — saveEntries() covers
		// just entries/history. Without it the next loadGroupData resurrects the
		// removed row from the stale per-group snapshot.
		if (entry.getGroupId() != null)
		{
			persist(entry.getGroupId(), "returned");
		}
		saveEntries();

		if (groupService != null && entry.getGroupId() != null)
		{
			groupService.publishEvent(GroupService.SyncEventType.ITEM_RETURNED, entryId, entry);
		}
		return true;
	}

	/** Look up an active loan by id, or null. */
	public LendingEntry getActiveEntry(String entryId)
	{
		return entryId != null ? allEntries.get(entryId) : null;
	}

	/** Is there already an unresolved removal request for this loan? */
	public boolean hasPendingRemovalFor(String groupId, String entryId)
	{
		return getRequests(groupId).stream()
			.anyMatch(r -> r.isRemoval() && r.isPending() && entryId != null && entryId.equals(r.getEntryId()));
	}

	/** Was a MUTUAL removal request for this loan already declined (escalation grounds)? */
	public boolean hasDeclinedMutualRemovalFor(String groupId, String entryId)
	{
		return getRequests(groupId).stream()
			.anyMatch(r -> LendingRequest.TYPE_REMOVAL_MUTUAL.equals(r.getType())
				&& LendingRequest.STATUS_DECLINED.equals(r.getStatus())
				&& entryId != null && entryId.equals(r.getEntryId()));
	}

	/**
	 * Pending staff-review removals this viewer may adjudicate: viewer must be an
	 * owner or co-owner of the group, must not be the requester, and must not be a
	 * party (lender/borrower) to the loan — nobody clears their own loan.
	 */
	/** Is there any owner/co-owner who could adjudicate this request? */
	private boolean hasEligibleSeniorReviewer(String groupId,
		com.guess34.lendingtracker.model.LendingGroup group, LendingRequest r, LendingEntry entry)
	{
		if (group == null || group.getMembers() == null || groupService == null) return false;
		for (com.guess34.lendingtracker.model.GroupMember m : group.getMembers())
		{
			String n = m.getName();
			if (n == null) continue;
			if (!groupService.isOwner(groupId, n) && !groupService.isCoOwner(groupId, n)) continue;
			if (r != null && n.equalsIgnoreCase(r.getFrom())) continue;
			if (entry != null
				&& (n.equalsIgnoreCase(entry.getLender()) || n.equalsIgnoreCase(entry.getBorrower()))) continue;
			return true;
		}
		return false;
	}

	/**
	 * Can a staff-removal for this loan actually be reviewed by anyone? The UI asks
	 * before offering the option, so a member is not left waiting on adjudication
	 * that cannot happen.
	 */
	public boolean hasAnyStaffReviewerFor(String groupId,
		com.guess34.lendingtracker.model.LendingGroup group, String requester, String entryId)
	{
		if (group == null || group.getMembers() == null || groupService == null) return false;
		LendingEntry entry = getActiveEntry(entryId);
		LendingRequest probe = new LendingRequest();
		probe.setFrom(requester);
		if (hasEligibleSeniorReviewer(groupId, group, probe, entry)) return true;
		for (com.guess34.lendingtracker.model.GroupMember m : group.getMembers())
		{
			String n = m.getName();
			if (n == null || !groupService.isAdmin(groupId, n)) continue;
			if (requester != null && n.equalsIgnoreCase(requester)) continue;
			if (entry != null
				&& (n.equalsIgnoreCase(entry.getLender()) || n.equalsIgnoreCase(entry.getBorrower()))) continue;
			return true;
		}
		return false;
	}

	public List<LendingRequest> getPendingStaffRemovalsFor(String groupId, String viewer,
		com.guess34.lendingtracker.model.LendingGroup group)
	{
		List<LendingRequest> result = new ArrayList<>();
		if (viewer == null || group == null || groupService == null)
		{
			return result;
		}
		boolean senior = groupService.isOwner(groupId, viewer) || groupService.isCoOwner(groupId, viewer);
		boolean admin = groupService.isAdmin(groupId, viewer);
		if (!senior && !admin)
		{
			return result;
		}
		for (LendingRequest r : getRequests(groupId))
		{
			if (!r.isStaffRemoval() || !r.isPending() || viewer.equalsIgnoreCase(r.getFrom()))
			{
				continue;
			}
			LendingEntry entry = getActiveEntry(r.getEntryId());
			if (entry != null
				&& (viewer.equalsIgnoreCase(entry.getLender()) || viewer.equalsIgnoreCase(entry.getBorrower())))
			{
				continue; // party to the loan - conflict of interest
			}
			// Admins only see it when no owner or co-owner is eligible. In a group with
			// one owner and no co-owners, that owner is often the requester or a party
			// to the loan - and then NOBODY could adjudicate, so the request sat unseen
			// until it expired. Widening one rank keeps the conflict-of-interest rule
			// intact while giving the dispute somewhere to go.
			if (!senior && !hasEligibleSeniorReviewer(groupId, group, r, entry))
			{
				result.add(r);
				continue;
			}
			if (!senior) continue;
			result.add(r);
		}
		return result;
	}

	// Data retention / cleanup

	public int deleteOldReturnedEntries(long requestedCutoff)
	{
		// The "this loan came back" tombstone is derived from history on every
		// publish, so pruning history below the tombstone window silently shortens
		// it — and it is the PUBLISHER's retention setting that decides, so one
		// member on a short setting would break catch-up for everyone else. Never
		// delete history a snapshot might still need to name.
		final long cutoffTime = Math.min(requestedCutoff, System.currentTimeMillis() - RETURNED_TOMBSTONE_MS);

		int deletedCount = 0;

		for (Map.Entry<String, Map<String, List<LendingEntry>>> groupEntry : groupLent.entrySet())
		{
			for (Map.Entry<String, List<LendingEntry>> accountEntry : groupEntry.getValue().entrySet())
			{
				List<LendingEntry> entries = accountEntry.getValue();
				int sizeBefore = entries.size();
				entries.removeIf(e -> e.getReturnedAt() > 0 && e.getReturnedAt() < cutoffTime);
				deletedCount += sizeBefore - entries.size();
			}
		}

		for (Map.Entry<String, Map<String, List<LendingEntry>>> groupEntry : groupBorrowed.entrySet())
		{
			for (Map.Entry<String, List<LendingEntry>> accountEntry : groupEntry.getValue().entrySet())
			{
				List<LendingEntry> entries = accountEntry.getValue();
				int sizeBefore = entries.size();
				entries.removeIf(e -> e.getReturnedAt() > 0 && e.getReturnedAt() < cutoffTime);
				deletedCount += sizeBefore - entries.size();
			}
		}

		int histSizeBefore = historyEntries.size();
		historyEntries.removeIf(entry ->
			entry.isReturned() && entry.getReturnedAt() < cutoffTime
		);
		deletedCount += histSizeBefore - historyEntries.size();

		if (deletedCount > 0)
		{
			for (String groupId : groupLent.keySet())
			{
				persist(groupId, "lent");
			}
			for (String groupId : groupBorrowed.keySet())
			{
				persist(groupId, "borrowed");
			}
			saveEntries();
		}

		return deletedCount;
	}

	public void clearGroupData(String groupId)
	{
		if (groupId == null || groupId.isEmpty())
		{
			return;
		}

		groupLent.remove(groupId);
		groupBorrowed.remove(groupId);
		groupAvailable.remove(groupId);
		// Also purge the flat stores, or the deleted group's loans stay in allEntries:
		// borrowed-item guards keep firing and overdue alerts keep arriving for a group
		// that no longer exists anywhere in the UI.
		allEntries.values().removeIf(e -> e != null && groupId.equals(e.getGroupId()));
		historyEntries.removeIf(e -> e != null && groupId.equals(e.getGroupId()));
		groupRequests.remove(groupId);
		removedListings.remove(groupId);
		// Forget that we read this group's file, so rejoining reads it fresh
		// instead of writing our now-empty maps over whatever is there.
		hydratedGroups.remove(groupId);
		saveEntries();
		configManager.unsetConfiguration(CONFIG_GROUP, KEY_PREFIX + groupId);
		if (groupService != null)
		{
			groupService.publishEvent(
				GroupService.SyncEventType.ITEM_REMOVED,
				groupId,
				null
			);
		}
	}

	// Item Sets (minimal -- load and clear only)

	private void loadItemSetsForGroup(String groupId)
	{
		if (groupId == null || groupId.isEmpty())
		{
			return;
		}

		String json = configManager.getConfiguration(CONFIG_GROUP, ITEMSETS_KEY_PREFIX + groupId);
		if (json != null && !json.isEmpty())
		{
			try
			{
				Type type = new TypeToken<List<ItemSet>>(){}.getType();
				List<ItemSet> sets = gson.fromJson(json, type);
				if (sets != null && !sets.isEmpty())
				{
					Map<String, ItemSet> setMap = new ConcurrentHashMap<>();
					for (ItemSet set : sets)
					{
						setMap.put(set.getId(), set);
					}
					groupItemSets.put(groupId, setMap);
				}
			}
			catch (Exception e)
			{
				log.error("Failed to load item sets for group {}: {}", groupId, e.getMessage());
			}
		}
	}

	public void clearItemSetData(String groupId)
	{
		if (groupId == null || groupId.isEmpty())
		{
			return;
		}

		groupItemSets.remove(groupId);
		configManager.unsetConfiguration(CONFIG_GROUP, ITEMSETS_KEY_PREFIX + groupId);

		if (groupService != null)
		{
			groupService.publishEvent(
				GroupService.SyncEventType.ITEM_SET_DELETED,
				groupId,
				null
			);
		}
	}

	// Persistence -- group data (lent/borrowed/available per group)

	// Groups whose stored snapshot has been read into memory this session.
	//
	// persist() serialises the in-memory maps over the stored file, so writing
	// before that file has been read replaces real data with empty maps. That is
	// not hypothetical: the local-backup restore at login calls restoreAvailable
	// (which persists) BEFORE startSync gets around to loadGroupData, so the very
	// first write of every session used to blank out the group's requests and
	// delisting tombstones. Returned-loan tombstones happened to survive only
	// because they are rebuilt from historyEntries, which does load early - which
	// is why this stayed hidden.
	private final Set<String> hydratedGroups = ConcurrentHashMap.newKeySet();

	private void persist(String groupId, String kind)
	{
		if (groupId == null || groupId.isEmpty()) return;
		if (!hydratedGroups.contains(groupId))
		{
			// Read what's on disk before writing over it. loadGroupData marks the
			// group hydrated itself, so this runs at most once per group.
			loadGroupData(groupId);
		}
		configManager.setConfiguration(CONFIG_GROUP, KEY_PREFIX + groupId, buildGroupSnapshotJson(groupId));
	}

	/**
	 * Build the full snapshot for a group: marketplace categories, direct requests,
	 * and active loan entries for the group. One format shared by local config
	 * persistence and relay state sync, so both paths carry the same data.
	 */
	// How long a returned-loan tombstone stays in the snapshot so members who were
	// offline at return time still learn the loan was returned when they catch up.
	private static final long RETURNED_TOMBSTONE_MS = 30L * 86400000L;

	// Snapshot format version. 1 = the original keys; 2 adds removedListings and
	// cancelled-request tombstones. Bump when the SHAPE changes, not the contents.
	private static final int SNAPSHOT_VERSION = 2;

	private String buildGroupSnapshotJson(String groupId)
	{
		Map<String, Object> snapshot = new LinkedHashMap<>();
		snapshot.put("lent", groupLent.getOrDefault(groupId, new HashMap<>()));
		snapshot.put("borrowed", groupBorrowed.getOrDefault(groupId, new HashMap<>()));
		snapshot.put("available", groupAvailable.getOrDefault(groupId, new HashMap<>()));
		snapshot.put("requests", getRequests(groupId));
		// Active loans live in the global allEntries map, which never crossed
		// machines before — include this group's entries so loans sync too.
		snapshot.put("entries", allEntries.values().stream()
			.filter(e -> groupId.equals(e.getGroupId()))
			.collect(Collectors.toList()));
		// Tombstones of recently-returned loans. A return removes the entry from
		// allEntries, so without this a member offline at return time would never
		// see it leave their Active Loans on catch-up.
		long cutoff = System.currentTimeMillis() - RETURNED_TOMBSTONE_MS;
		List<String> returnedIds = new ArrayList<>();
		for (LendingEntry h : historyEntries)
		{
			if (groupId.equals(h.getGroupId()) && h.getReturnedAt() > cutoff && h.getId() != null)
			{
				returnedIds.add(h.getId());
			}
		}
		snapshot.put("returnedIds", returnedIds);

		// Delisting tombstones, same 30-day window. Pruned as we build so the map
		// cannot grow forever, and so a re-listing eventually stops being suppressed.
		// Pruned at BOTH ends: a nonsense future date can't be aged out by waiting,
		// so it would otherwise suppress that listing for good.
		Map<String, Long> live = new LinkedHashMap<>();
		Map<String, Long> stones = removedListings.get(groupId);
		if (stones != null)
		{
			long ceiling = System.currentTimeMillis() + CLOCK_SKEW_ALLOWANCE_MS;
			stones.entrySet().removeIf(e -> e.getValue() == null
				|| e.getValue() <= cutoff || e.getValue() > ceiling);
			live.putAll(stones);
		}
		snapshot.put("removedListings", live);

		// Snapshot format version. Old clients ignore it; from here on a reader can
		// tell what a payload is expected to contain instead of guessing.
		snapshot.put("v", SNAPSHOT_VERSION);
		return gson.toJson(snapshot);
	}

	/**
	 * Get the full data snapshot for a group as a JSON string.
	 * Used for relay state sync so offline members can catch up.
	 */
	public String getGroupDataSnapshot(String groupId)
	{
		if (groupId == null) return null;
		return buildGroupSnapshotJson(groupId);
	}

	/**
	 * Apply a group snapshot received over the relay.
	 *
	 * Two very different cases, distinguished by {@code publisher}:
	 *
	 * <b>Catch-up (publisher == null)</b> — the authoritative stored snapshot the
	 * joining client fetched over REST. Adopt it wholesale so deletions made while
	 * this client was offline take effect (no resurrection).
	 *
	 * <b>Live (publisher != null)</b> — a single member's push. That member is
	 * authoritative ONLY for their own rows, so we replace just their owner-key in
	 * each category and leave everyone else untouched. This avoids both the
	 * resurrection bug (a stale peer can't re-add another owner's deleted rows) and
	 * data loss (concurrent edits by different members never clobber each other).
	 * Loans and requests, which aren't cleanly owned by one member, reconcile by a
	 * per-record last-write-wins on {@code updatedAt}.
	 *
	 * All writes replace list/map references rather than mutating live lists, so a
	 * reader iterating on another thread never sees a torn collection.
	 */
	public void loadGroupDataFromSnapshot(String groupId, String snapshotJson)
	{
		loadGroupDataFromSnapshot(groupId, snapshotJson, null, null);
	}

	/**
	 * @param publisher non-null for a live push (authoritative for their own rows
	 *                  only); null for an authoritative catch-up snapshot.
	 * @param selfOwner this client's player name, whose own rows are preserved on
	 *                  catch-up so offline additions aren't clobbered.
	 */
	public void loadGroupDataFromSnapshot(String groupId, String snapshotJson, String publisher, String selfOwner)
	{
		if (groupId == null || snapshotJson == null || snapshotJson.isEmpty()) return;
		try
		{
			@SuppressWarnings("unchecked")
			Map<String, Object> snapshot = gson.fromJson(snapshotJson, Map.class);

			if (publisher == null)
			{
				// Authoritative catch-up: adopt the stored marketplace wholesale so
				// deletions made while offline take effect, but keep the local
				// player's own rows (they're authoritative for their own listings).
				// Loans and requests merge by last-write-wins instead of a wholesale
				// replace, so a snapshot from a member with an incomplete view can't
				// drop live records.
				loadGroupEntries(getCategory(snapshot, "available"), groupId, groupAvailable, selfOwner);
				loadGroupEntries(getCategory(snapshot, "lent"), groupId, groupLent, selfOwner);
				loadGroupEntries(getCategory(snapshot, "borrowed"), groupId, groupBorrowed, selfOwner);
				mergeRequests(groupId, snapshot.get("requests"), true);
				mergeActiveEntries(groupId, snapshot.get("entries"));
			}
			else
			{
				// Live update: publisher is authoritative only for their own rows.
				applyPublisherRows(getCategory(snapshot, "available"), groupId, groupAvailable, publisher);
				applyPublisherRows(getCategory(snapshot, "lent"), groupId, groupLent, publisher);
				// "borrowed" is deliberately NOT applied here, and an attempt to add it
				// was reverted. Two reasons. It is keyed by BORROWER, so the publisher
				// owns no bucket and any rule has to scope by the lender field - and
				// scoping that way, absence of a row cannot mean "returned": a lend
				// offer is recorded on the BORROWER's client, so the lender legitimately
				// never holds it and would delete it off everyone else. Deletion here
				// needs a positive tombstone, not an inference from absence.
				// It also buys nothing today: nothing user-facing reads groupBorrowed.
				// Active Loans, the trade guards and the return flow all read
				// getActiveEntries(), which mergeActiveEntries already syncs live.
				mergeRequests(groupId, snapshot.get("requests"), true);
				mergeActiveEntries(groupId, snapshot.get("entries"));
			}

			// Apply returned-loan tombstones (both paths) so returns propagate to
			// members who were offline when the loan came back.
			applyReturnedTombstones(snapshot.get("returnedIds"));
			applyRemovedListings(groupId, snapshot.get("removedListings"));

			// Persist the reconciled state locally so it survives a restart.
			persist(groupId, "sync");
			log.debug("Applied group snapshot for group {} (publisher: {})", groupId,
				publisher != null ? publisher : "catch-up");
		}
		catch (Exception e)
		{
			log.error("Failed to load group data from snapshot: {}", e.getMessage(), e);
		}
	}

	@SuppressWarnings("unchecked")
	private Map<String, List<Map<String, Object>>> getCategory(Map<String, Object> snapshot, String key)
	{
		Object raw = snapshot.get(key);
		return raw instanceof Map ? (Map<String, List<Map<String, Object>>>) raw : null;
	}

	/**
	 * Live merge for one category: replace ONLY the publisher's own owner-key with
	 * their rows from the snapshot; leave every other owner untouched. The
	 * publisher's key is replaced (not merged) so their own deletions propagate.
	 */
	private void applyPublisherRows(Map<String, List<Map<String, Object>>> rawData, String groupId,
		Map<String, Map<String, List<LendingEntry>>> target, String publisher)
	{
		if (rawData == null || publisher == null) return;

		Map<String, List<LendingEntry>> ownerMap = target
			.computeIfAbsent(groupId, k -> new ConcurrentHashMap<>());

		// Find the publisher's rows in the snapshot (owner keys are player names)
		String matchedKey = null;
		List<Map<String, Object>> rows = null;
		for (Map.Entry<String, List<Map<String, Object>>> e : rawData.entrySet())
		{
			if (e.getKey().equalsIgnoreCase(publisher))
			{
				matchedKey = e.getKey();
				rows = e.getValue();
				break;
			}
		}

		// Drop any stale entries filed under the publisher's key(s) first, so a
		// removal (they now have no rows) propagates.
		for (String owner : new ArrayList<>(ownerMap.keySet()))
		{
			if (owner.equalsIgnoreCase(publisher))
			{
				ownerMap.remove(owner);
			}
		}

		if (rows == null || rows.isEmpty())
		{
			return;
		}

		List<LendingEntry> fresh = new CopyOnWriteArrayList<>();
		for (Map<String, Object> row : rows)
		{
			LendingEntry entry = gson.fromJson(gson.toJson(row), LendingEntry.class);
			if (entry != null)
			{
				fresh.add(entry);
			}
		}
		ownerMap.put(matchedKey, fresh);
	}

	/** Merge direct requests from a remote snapshot (union by id, newest update wins). */
	private void mergeRequests(String groupId, Object rawRequests, boolean fromPeer)
	{
		if (!(rawRequests instanceof List))
		{
			return;
		}

		List<LendingRequest> localRequests = groupRequests
			.computeIfAbsent(groupId, k -> new CopyOnWriteArrayList<>());
		long staleBefore = System.currentTimeMillis() - PENDING_REQUEST_EXPIRY_MS;

		for (Object raw : (List<?>) rawRequests)
		{
			LendingRequest remote = gson.fromJson(gson.toJson(raw), LendingRequest.class);
			if (remote == null || remote.getId() == null)
			{
				continue;
			}

			synchronized (localRequests)
			{
				LendingRequest local = localRequests.stream()
					.filter(r -> remote.getId().equals(r.getId()))
					.findFirst().orElse(null);
				if (local == null)
				{
					// A pending request older than the expiry age is one everybody
					// else already retired and pruned. Re-adding it hands the
					// recipient a live, actionable request from months ago, which
					// they answer into a loan that may involve someone long gone -
					// and re-stamping it on expiry buys it another full retention
					// window, so the same peer resurrects it again on every login.
					//
					// PEERS ONLY. "local == null" means "not in memory", and at
					// startup nothing has been loaded yet - so on the config reload
					// every one of our OWN saved requests looks unknown. Dropping
					// them there deletes the user's own unanswered disputes instead
					// of expiring them, which loses the record and the notification
					// with it. Our own file is reloaded as-is; expiry retires it.
					long born = requestAge(remote);
					if (fromPeer && remote.isPending() && born > 0 && born < staleBefore)
					{
						continue;
					}
					localRequests.add(remote);
					// Nothing to reconcile - the row we just took carries its own
					// status and flags. Everything below compares against a local
					// copy that does not exist here.
					continue;
				}

				// Outcome first, timestamp second. Expiry runs on a timer against
				// whatever that client last knew, so a member who has not synced
				// recently will happily expire a request somebody already answered -
				// and it stamps a fresh time doing it, so plain last-write-wins would
				// hand that stale non-answer to the whole group and quietly undo an
				// approved loan removal. A decision outranks an expiry outranks
				// still-pending; only within one rank does the newer copy win.
				int remoteRank = outcomeRank(remote);
				int localRank = outcomeRank(local);
				if (remoteRank > localRank
					|| (remoteRank == localRank && remote.getUpdatedAt() > local.getUpdatedAt()))
				{
					local.setStatus(remote.getStatus());
					local.setUpdatedAt(remote.getUpdatedAt());
					// Moving to a real decision retires the expiry; a move to
					// cancelled leaves the flag to the one-way union below.
					if (!LendingRequest.STATUS_CANCELLED.equals(remote.getStatus()))
					{
						local.setExpired(false);
					}
				}

				// The expiry flag unions separately from the status, one way only.
				// It has to: a client that predates the field drops it when it
				// relays the row, and since it keeps the same updatedAt, the rank
				// and time above are both ties and never fire - so an expiry
				// laundered through one older peer would be lost for good. Only
				// adopted onto a cancellation, so a leftover flag can't overwrite
				// somebody's actual decision.
				if (remote.isExpired() && !local.isExpired()
					&& LendingRequest.STATUS_CANCELLED.equals(local.getStatus()))
				{
					local.setExpired(true);
				}
			}
		}
	}

	/** Live merge of loan entries: last-write-wins by updatedAt, archive returns. */
	private void mergeActiveEntries(String groupId, Object rawEntries)
	{
		if (!(rawEntries instanceof List))
		{
			return;
		}

		boolean changed = false;
		for (Object raw : (List<?>) rawEntries)
		{
			LendingEntry remote = gson.fromJson(gson.toJson(raw), LendingEntry.class);
			if (remote == null || remote.getId() == null)
			{
				continue;
			}
			// A group's snapshot may only carry that group's loans. Publishers already
			// filter on the way out, so anything else here is a stale or malformed
			// peer — accepting it would file another group's loan under this one and
			// expose it to members who have no business seeing it.
			if (remote.getGroupId() != null && !groupId.equals(remote.getGroupId()))
			{
				continue;
			}
			if (applyRemoteEntry(remote))
			{
				changed = true;
			}
		}

		if (changed)
		{
			saveEntries();
		}
	}

	/**
	 * Apply one remote loan entry to allEntries. Returns true if anything changed.
	 * A returned entry is archived (not kept active); an active entry is upserted
	 * when it is newer than the local copy, and never resurrected if this client
	 * has already archived it.
	 */
	// Told about a loan this client had never seen before, arriving from sync.
	// The Discord webhook uses it: the lender must post loans they did not record
	// themselves (an accepted lend offer is recorded by the borrower).
	private java.util.function.Consumer<LendingEntry> onNewLoanFromSync;

	public void setOnNewLoanFromSync(java.util.function.Consumer<LendingEntry> callback)
	{
		this.onNewLoanFromSync = callback;
	}

	private boolean applyRemoteEntry(LendingEntry remote)
	{
		boolean alreadyInHistory;
		synchronized (historyEntries)
		{
			alreadyInHistory = historyEntries.stream()
				.anyMatch(h -> remote.getId().equals(h.getId()));
		}

		if (remote.isReturned())
		{
			boolean changed = false;
			if (!alreadyInHistory)
			{
				// Settle it here too, or an un-updated peer republishing a partially
				// returned loan reintroduces the never-settles condition on a client
				// that already migrated.
				remote.markSettled();
				historyEntries.add(remote);
				changed = true;
			}
			if (allEntries.remove(remote.getId()) != null)
			{
				changed = true;
			}
			return changed;
		}

		if (alreadyInHistory)
		{
			return false; // returned locally already — don't resurrect
		}

		LendingEntry local = allEntries.get(remote.getId());
		// One-way latch: a client that predates the flag drops it when relaying
		// the row, and losing it would leave a borrower-kept loan with no client
		// tracking its returns.
		if (local != null && local.isKeptByBorrower() && !remote.isKeptByBorrower())
		{
			remote.setKeptByBorrower(true);
		}
		if (local == null || remote.getUpdatedAt() > local.getUpdatedAt())
		{
			allEntries.put(remote.getId(), remote);
			if (local == null && onNewLoanFromSync != null)
			{
				try
				{
					onNewLoanFromSync.accept(remote);
				}
				catch (Exception e)
				{
					log.debug("New-loan listener failed: {}", e.getMessage());
				}
			}
			return true;
		}
		return false;
	}

	/**
	 * Mark a loan returned because a sync event from another client said so.
	 * Same effect as {@link #completeEntry} but does NOT publish a sync event,
	 * so two clients can't bounce the same return back and forth.
	 */
	public void applyReturnedFromSync(String entryId)
	{
		// Grab the group before archiving removes the entry — the group snapshot
		// needs the same persist the local return paths do, or the next
		// loadGroupData resurrects the lent/borrowed rows from stale config and
		// we republish the returned loan as active.
		LendingEntry entry = allEntries.get(entryId);
		if (archiveReturnedById(entryId))
		{
			if (entry != null && entry.getGroupId() != null)
			{
				persist(entry.getGroupId(), "returned");
			}
			saveEntries();
		}
	}

	/**
	 * Adopt a peer's delisting tombstones and drop any listing they retire.
	 *
	 * Union by newest time, so a tombstone survives being merged with a peer that
	 * never saw the removal. A row is only dropped when the removal is NEWER than
	 * the row itself - re-listing an item you previously pulled therefore wins,
	 * because the fresh row carries a later updatedAt than the tombstone.
	 *
	 * Two things this has to get right, both learned the hard way:
	 *
	 * ADOPTION IS OPTIONAL, ENFORCEMENT IS NOT. A snapshot from a client that
	 * predates this format carries no tombstones at all. That is a reason to skip
	 * the adoption loop, NOT a reason to skip the sweep - the tombstones we already
	 * hold still have to be honoured, or a stale peer's copy of a row we deleted
	 * walks straight back in and the whole mechanism does nothing.
	 *
	 * THE TWO TIMES COME FROM DIFFERENT MACHINES. The tombstone is stamped by
	 * whoever removed the listing; updatedAt by whoever created it. Nothing keeps
	 * two players' clocks in step, so the comparison gets a skew allowance - a few
	 * minutes of drift must not be enough to delete a listing somebody created
	 * seconds ago.
	 *
	 * The allowance is the ONLY protection, deliberately. Exempting the local
	 * player's own rows outright looks safer and is worse: play on two machines,
	 * delist an item on the desktop, and the laptop would keep the row, keep
	 * republishing it, and put it back in front of the whole group the moment the
	 * tombstone aged out. A removal has to be enforceable against the person who
	 * made it, or it isn't a removal.
	 */
	private void applyRemovedListings(String groupId, Object raw)
	{
		if (groupId == null) return;
		Map<String, Long> mine = removedListings.computeIfAbsent(groupId, k -> new ConcurrentHashMap<>());
		boolean changed = adoptRemovedListings(mine, raw);

		Map<String, List<LendingEntry>> groupData = groupAvailable.get(groupId);
		if (groupData != null && !mine.isEmpty())
		{
			for (Map.Entry<String, List<LendingEntry>> owner : groupData.entrySet())
			{
				changed |= owner.getValue().removeIf(row ->
				{
					String lender = row.getLender() != null ? row.getLender() : owner.getKey();
					Long at = mine.get(listingKey(lender, row.getItemId()));
					return at != null && at > row.getUpdatedAt() + CLOCK_SKEW_ALLOWANCE_MS;
				});
			}
		}
		if (changed) persist(groupId, "available");
	}

	/**
	 * Union an incoming tombstone map into ours, newest wins. Returns true if
	 * anything changed.
	 *
	 * Times are clamped to our own clock on the way in. A member whose PC has the
	 * wrong year would otherwise hand us a tombstone dated far in the future, which
	 * no re-listing could ever outrank and no prune could ever reach - that item
	 * would be permanently unlistable for everyone, with no way to clear it.
	 */
	private boolean adoptRemovedListings(Map<String, Long> mine, Object raw)
	{
		if (!(raw instanceof Map)) return false;
		boolean changed = false;
		long ceiling = System.currentTimeMillis() + CLOCK_SKEW_ALLOWANCE_MS;
		for (Map.Entry<?, ?> e : ((Map<?, ?>) raw).entrySet())
		{
			if (e.getKey() == null || !(e.getValue() instanceof Number)) continue;
			String key = e.getKey().toString();
			long at = Math.min(((Number) e.getValue()).longValue(), ceiling);
			Long known = mine.get(key);
			if (known == null || at > known)
			{
				mine.put(key, at);
				changed = true;
			}
		}
		return changed;
	}

	/**
	 * Apply a batch of returned-loan tombstones from a snapshot: archive each id
	 * that's still active locally so returns reach members who were offline.
	 */
	private void applyReturnedTombstones(Object rawIds)
	{
		if (!(rawIds instanceof List))
		{
			return;
		}
		boolean changed = false;
		for (Object raw : (List<?>) rawIds)
		{
			if (raw != null && archiveReturnedById(raw.toString()))
			{
				changed = true;
			}
		}
		if (changed)
		{
			saveEntries();
		}
	}

	/**
	 * Archive a loan by id: move it from the active map to history and drop it
	 * from the lent/borrowed maps. Idempotent — a no-op if already archived or
	 * unknown. Returns true if anything changed. Caller persists.
	 */
	private boolean archiveReturnedById(String entryId)
	{
		if (entryId == null)
		{
			return false;
		}

		LendingEntry entry = allEntries.remove(entryId);
		removeEntryFromCategory(groupLent, entryId);
		removeEntryFromCategory(groupBorrowed, entryId);

		if (entry == null)
		{
			return false; // wasn't active here; nothing to archive
		}

		boolean inHistory = historyEntries.stream().anyMatch(h -> entryId.equals(h.getId()));
		if (!inHistory)
		{
			if (!entry.isReturned())
			{
				entry.setReturnedAt(Instant.now().toEpochMilli());
			}
			entry.markSettled();
		historyEntries.add(new LendingEntry(entry));
		}
		return true;
	}

	/** Remove an entry by id from every owner list in a category map. */
	private void removeEntryFromCategory(Map<String, Map<String, List<LendingEntry>>> category, String entryId)
	{
		for (Map<String, List<LendingEntry>> ownerMap : category.values())
		{
			for (List<LendingEntry> list : ownerMap.values())
			{
				list.removeIf(e -> entryId.equals(e.getId()));
			}
		}
	}

	/**
	 * Load group-specific data from storage.
	 * Called when switching groups to restore previously saved items.
	 * Also loads item sets for the group.
	 */
	public void loadGroupData(String groupId)
	{
		if (groupId == null || groupId.isEmpty())
		{
			return;
		}
		// Marked before reading, not after: anything below that persists would
		// otherwise come back through persist's hydrate check and recurse.
		hydratedGroups.add(groupId);

		String json = configManager.getConfiguration(CONFIG_GROUP, KEY_PREFIX + groupId);
		if (json != null && !json.isEmpty())
		{
			try
			{
				@SuppressWarnings("unchecked")
				Map<String, Object> snapshot = gson.fromJson(json, Map.class);

				loadGroupEntries(getCategory(snapshot, "available"), groupId, groupAvailable);
				loadGroupEntries(getCategory(snapshot, "lent"), groupId, groupLent);
				loadGroupEntries(getCategory(snapshot, "borrowed"), groupId, groupBorrowed);
				mergeRequests(groupId, snapshot.get("requests"), false);
				mergeActiveEntries(groupId, snapshot.get("entries"));
				// Tombstones have to come back with everything else. Held only in
				// memory they died on every logout, which made the 30-day window
				// really "until you next close the client" - and a client that has
				// forgotten a removal goes right back to publishing the row.
				//
				// Rehydrate only, never sweep. This file is our own state, already
				// swept before it was written, so there is nothing here to
				// reconcile - and sweeping it would run without knowing who we are,
				// which is exactly the case the "never drop your own rows" rule
				// exists to prevent.
				adoptRemovedListings(
					removedListings.computeIfAbsent(groupId, k -> new ConcurrentHashMap<>()),
					snapshot.get("removedListings"));
			}
			catch (Exception e)
			{
				log.error("Failed to load group data for {}: {}", groupId, e.getMessage(), e);
			}
		}

		loadItemSetsForGroup(groupId);
	}

	/**
	 * Helper to deserialize a category (available/lent/borrowed) from a raw map snapshot.
	 */
	private void loadGroupEntries(Map<String, List<Map<String, Object>>> rawData, String groupId,
		Map<String, Map<String, List<LendingEntry>>> target)
	{
		loadGroupEntries(rawData, groupId, target, null);
	}

	/**
	 * Wholesale-load one category from a snapshot, atomically swapping in a fresh
	 * owner-map so readers on other threads never see a torn collection.
	 *
	 * When {@code selfOwner} is set (authoritative catch-up), that owner's local
	 * rows are preserved rather than overwritten — the local player is always
	 * authoritative for their own listings, so a stale relay snapshot can't drop
	 * items they added while disconnected.
	 */
	private void loadGroupEntries(Map<String, List<Map<String, Object>>> rawData, String groupId,
		Map<String, Map<String, List<LendingEntry>>> target, String selfOwner)
	{
		// A null category means the snapshot didn't carry this section at all (old
		// or foreign format); preserve local data rather than wiping it. An EMPTY
		// map is different — it means "no rows", so deletions still propagate.
		if (rawData == null)
		{
			return;
		}

		Map<String, List<LendingEntry>> existing = target.get(groupId);

		Map<String, List<LendingEntry>> entryMap = new ConcurrentHashMap<>();
		{
			for (Map.Entry<String, List<Map<String, Object>>> ownerEntry : rawData.entrySet())
			{
				if (selfOwner != null && ownerEntry.getKey().equalsIgnoreCase(selfOwner))
				{
					continue; // preserve local self rows below
				}
				List<LendingEntry> entries = new CopyOnWriteArrayList<>();
				for (Map<String, Object> entryData : ownerEntry.getValue())
				{
					LendingEntry entry = gson.fromJson(gson.toJson(entryData), LendingEntry.class);
					if (entry != null)
					{
						entries.add(entry);
					}
				}
				if (!entries.isEmpty())
				{
					entryMap.put(ownerEntry.getKey(), entries);
				}
			}
		}

		// Carry over the local player's own rows untouched
		if (selfOwner != null && existing != null)
		{
			for (Map.Entry<String, List<LendingEntry>> e : existing.entrySet())
			{
				if (e.getKey().equalsIgnoreCase(selfOwner))
				{
					entryMap.put(e.getKey(), e.getValue());
				}
			}
		}

		target.put(groupId, entryMap);
	}

	// Persistence -- global entries (allEntries + history)

	private void loadEntries()
	{
		try
		{
			String entriesJson = configManager.getConfiguration(CONFIG_GROUP, ENTRIES_KEY);
			if (entriesJson != null)
			{
				Type type = new TypeToken<Map<String, LendingEntry>>(){}.getType();
				Map<String, LendingEntry> loaded = gson.fromJson(entriesJson, type);
				if (loaded != null)
				{
					allEntries.putAll(loaded);
				}
			}

			String historyJson = configManager.getConfiguration(CONFIG_GROUP, HISTORY_KEY);
			if (historyJson != null)
			{
				Type type = new TypeToken<List<LendingEntry>>(){}.getType();
				List<LendingEntry> loaded = gson.fromJson(historyJson, type);
				if (loaded != null)
				{
					historyEntries.addAll(loaded);
					// One-time migration. Builds before markSettled archived partially
					// returned loans with their tallies intact, so isFullySettled() stayed
					// false forever - and getUnsettledFor would refuse to let those members
					// leave, listing a loan they had already closed, for at least the 30-day
					// retention window. Anything archived is settled by definition.
					boolean migrated = false;
					for (LendingEntry h : historyEntries)
					{
						// Being in historyEntries IS the archive predicate - do not also
						// require isReturned(). A row archived without returnedAt would
						// otherwise stay unsettled forever and block leaving permanently,
						// which is the exact failure this migration exists to clear.
						if (h != null && !h.isFullySettled())
						{
							if (!h.isReturned()) h.setReturnedAt(System.currentTimeMillis());
							h.markSettled();
							migrated = true;
						}
					}
					if (migrated)
					{
						log.debug("Settled legacy history entries that could never clear");
						saveEntries();
					}
				}
			}
		}
		catch (Exception e)
		{
			log.error("Failed to load entries", e);
		}
	}

	private void saveEntries()
	{
		try
		{
			configManager.setConfiguration(CONFIG_GROUP, ENTRIES_KEY, gson.toJson(allEntries));
			configManager.setConfiguration(CONFIG_GROUP, HISTORY_KEY, gson.toJson(historyEntries));
		}
		catch (Exception e)
		{
			log.error("Failed to save entries", e);
		}
	}
}

package com.guess34.lendingtracker.services;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import com.guess34.lendingtracker.LendingTrackerConfig;
import com.guess34.lendingtracker.model.LendingEntry;
import com.guess34.lendingtracker.model.LendingGroup;
import java.awt.image.BufferedImage;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.time.Instant;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.concurrent.atomic.AtomicInteger;
import java.awt.Graphics2D;
import javax.imageio.ImageIO;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.game.ItemManager;
import net.runelite.client.util.AsyncBufferedImage;
import net.runelite.client.util.QuantityFormatter;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.HttpUrl;
import okhttp3.MediaType;
import okhttp3.MultipartBody;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;

/**
 * Posts loan events to the Discord channel of the group the loan was made in.
 *
 * The webhook belongs to the GROUP: staff set it once in the group settings and
 * it syncs to every member (sealed - see WebhookSeal). So a player in two groups
 * never posts one group's loans into the other's Discord. Each player still has
 * to turn posting on for themselves; RuneLite requires that for anything sent to
 * a third party.
 *
 * One way only - nothing is ever read back. Each post is one small embed: a
 * sentence saying what happened, the items, and the trade picture as a
 * click-to-enlarge thumbnail. Everything from one trade is one post.
 *
 * EXACTLY ONE CLIENT POSTS EACH EVENT, which matters with a whole clan trading:
 *  - Only the loan's KEEPER posts. That is the lender's client (they tap Loan,
 *    the borrower taps Collat and records nothing) - except when the lender
 *    isn't in the group and can't record it, typically a clan-mate on mobile.
 *    Then the borrower's client keeps the loan, flagged keptByBorrower, and it
 *    alone posts. The flag is set once when the loan is recorded, so the two
 *    sides never both think they are the keeper.
 *  - The lender's client posts a loan when it first SEES it, not only when it
 *    records it. An accepted lend offer is recorded by the borrower, and arrives
 *    at the lender by sync - it used to go unposted.
 *  - Every post is remembered (loan id + event), so a restart, a re-sync or the
 *    same loan arriving twice never posts it again.
 * The one case left is the same account logged in on two computers at once,
 * each with its own memory of what it posted.
 */
@Slf4j
@Singleton
public class DiscordWebhook
{
	public enum Event
	{
		LOAN("New loan", 0x3BA55D, "\uD83D\uDCE6"),
		RETURNED("Returned", 0x5865F2, "\u2705"),
		OVERDUE("Overdue", 0xFEE75C, "\u23F0"),
		FORGIVEN("Forgiven", 0x99AAB5, "\uD83E\uDD1D"),
		PARTIAL("Incomplete return", 0xF0A020, "\u26A0"),
		REMOVED("Removed", 0x99AAB5, "\uD83D\uDDD1");

		private final String label;
		private final int color;
		private final String icon;

		Event(String label, int color, String icon)
		{
			this.label = label;
			this.color = color;
			this.icon = icon;
		}
	}

	private static final MediaType JSON = MediaType.parse("application/json; charset=utf-8");
	private static final MediaType PNG = MediaType.parse("image/png");
	private static final int MAX_LINES = 20;
	// Collateral item names, filled on the client thread before a post is built.
	private final java.util.Map<Integer, String> itemNames = new java.util.concurrent.ConcurrentHashMap<>();
	// One row of icons, however many items; waits at most this long for them.
	private static final int MAX_ICONS = 10;
	private static final long ICON_WAIT_SECONDS = 3;
	// Up to 30s for the game to load the clan list after login before posting anyway.
	private static final int ROSTER_WAIT_TRIES = 3;
	private static final long ROSTER_WAIT_SECONDS = 10;
	private static final String CONFIG_GROUP = "lendingtracker";
	private static final String POSTED_KEY = "webhookPosted";
	private static final int POSTED_CAP = 400;
	// A loan that turns up by sync is only news if it is recent - otherwise
	// turning the webhook on, or a fresh install, would post every loan the
	// group has ever had.
	private static final long SEEN_LOAN_WINDOW_MS = 24L * 3600000L;

	private final OkHttpClient httpClient;
	private final Gson gson;
	private final LendingTrackerConfig config;
	private final GroupService groupService;
	private final ConfigManager configManager;
	private final ScheduledExecutorService executor;
	private final ClanRoster clanRoster;
	private final ClientThread clientThread;
	private final ItemManager itemManager;

	@Inject
	public DiscordWebhook(OkHttpClient httpClient, Gson gson, LendingTrackerConfig config, GroupService groupService,
		ConfigManager configManager, ScheduledExecutorService executor, ClanRoster clanRoster, ClientThread clientThread,
		ItemManager itemManager)
	{
		this.itemManager = itemManager;
		this.clientThread = clientThread;
		this.executor = executor;
		this.clanRoster = clanRoster;
		this.httpClient = httpClient;
		this.gson = gson;
		this.config = config;
		this.groupService = groupService;
		this.configManager = configManager;
	}

	/**
	 * Only a real Discord webhook address is accepted. Anything else is ignored,
	 * so a mistyped or malicious link can't turn this into a way of sending loan
	 * data to some other server.
	 */
	public static boolean isDiscordWebhook(String url)
	{
		if (url == null) return false;
		HttpUrl parsed = HttpUrl.parse(url.trim());
		if (parsed == null || !parsed.isHttps()) return false;
		String host = parsed.host();
		boolean discord = host.equals("discord.com") || host.equals("discordapp.com")
			|| host.equals("ptb.discord.com") || host.equals("canary.discord.com");
		return discord && parsed.encodedPath().startsWith("/api/webhooks/");
	}

	/** Post this event if the webhook is on, the event type is wanted, and we are the client that should. */
	public void post(Event event, LendingEntry loan, String reporter)
	{
		post(event, loan, reporter, null);
	}

	/** A loan that reached this client by sync rather than being recorded here. */
	public void postLoanSeen(LendingEntry loan, String reporter)
	{
		if (loan == null || loan.isReturned() || loan.getLendTime() < System.currentTimeMillis() - SEEN_LOAN_WINDOW_MS)
		{
			return;
		}
		post(Event.LOAN, loan, reporter, null);
	}

	/**
	 * @param occurrence tells apart events that can legitimately repeat for one
	 *                   loan - the overdue day - or null for one-off events
	 */
	public void post(Event event, LendingEntry loan, String reporter, String occurrence)
	{
		postBatch(event, Collections.singletonList(loan), reporter, occurrence, null);
	}

	/**
	 * A short "connected" message, so staff can check the link works. Only with
	 * posting turned on in this player's own settings, like everything else.
	 *
	 * @return null when sent, else why not
	 */
	public String postTest(String groupId, String player)
	{
		if (!config.webhookEnabled())
		{
			return "Turn on 'Post loans to Discord' in the plugin's settings first - RuneLite requires it before the plugin sends anything to Discord.";
		}
		String url = groupService.getGroupWebhook(groupId);
		if (url == null)
		{
			return "This group has no Discord webhook set.";
		}
		LendingGroup group = groupService.getGroup(groupId);
		JsonObject embed = new JsonObject();
		embed.addProperty("title", "Lending Tracker connected");
		embed.addProperty("description", "Loans in " + safe(group != null ? group.getName() : "this group")
			+ " will be posted here. Test sent by " + safe(player) + ".");
		embed.addProperty("color", 0x3BA55D);
		JsonArray embeds = new JsonArray();
		embeds.add(embed);
		JsonObject body = new JsonObject();
		body.addProperty("username", "Lending Tracker");
		body.add("embeds", embeds);
		JsonObject mentions = new JsonObject();
		mentions.add("parse", new JsonArray());
		body.add("allowed_mentions", mentions);
		send(url, RequestBody.create(JSON, gson.toJson(body)));
		return null;
	}

	/** Post the trade-window picture with loan events? */
	public boolean wantsScreenshot()
	{
		return config.webhookEnabled() && config.webhookScreenshot();
	}

	/**
	 * One post for everything that happened in one go - every item lent in a
	 * single trade is its own loan record, but it was one hand-over and reads as
	 * one message. All loans passed must share lender and borrower.
	 *
	 * @param proof the trade window, already cropped to just that window, or null
	 */
	public void postBatch(Event event, List<LendingEntry> loans, String reporter, String occurrence,
		BufferedImage proof)
	{
		if (loans == null || loans.isEmpty() || loans.get(0) == null || reporter == null
			|| !config.webhookEnabled() || !wanted(event))
		{
			return;
		}
		// The channel of the group this trade happened in - nowhere else.
		String url = groupService.getGroupWebhook(loans.get(0).getGroupId());
		if (url == null)
		{
			return;
		}
		List<LendingEntry> fresh = new ArrayList<>();
		for (LendingEntry loan : loans)
		{
			if (loan == null || loan.getId() == null || !shouldReport(loan, reporter))
			{
				continue;
			}
			if (claim(loan.getId() + ":" + event.name() + (occurrence != null ? ":" + occurrence : "")))
			{
				fresh.add(loan);   // not already posted from this computer
			}
		}
		if (fresh.isEmpty())
		{
			return;
		}
		deliver(fresh, event, proof, url.trim(), 0);
	}

	/**
	 * Apply the group's loan scope (clan / group / anyone) before posting, with
	 * clan membership read fresh from the game's clan list. If the game hasn't
	 * loaded the clan yet (just logged in), wait a little and try again rather
	 * than decide on a list that isn't there.
	 */
	private void deliver(List<LendingEntry> fresh, Event event, BufferedImage proof, String target, int attempt)
	{
		LendingEntry first = fresh.get(0);
		String groupId = first.getGroupId();
		GroupService.LoanScope scope = groupService.getLoanScope(groupId);
		String clan = groupService.getLinkedClan(groupId);
		// A loan whose "New loan" went out always gets its ending posted too, even
		// if someone has since left the clan or group - otherwise the channel, and
		// any bot reading it, would show it open forever.
		boolean announced = event != Event.LOAN && wasAnnounced(fresh);

		if (!announced && scope == GroupService.LoanScope.GROUP)
		{
			LendingGroup group = groupService.getGroup(groupId);
			if (group == null || !group.hasMember(first.getLender()) || !group.hasMember(first.getBorrower()))
			{
				log.debug("Not posting {}: {} -> {} not both in the group", event, first.getLender(), first.getBorrower());
				return;
			}
		}
		if (clan == null)
		{
			withIcons(fresh, strip -> buildAndSend(fresh, event, proof, target, strip));
			return;
		}
		clientThread.invokeLater(() ->
		{
			clanRoster.refresh();
			if (!clanRoster.isLoaded() && attempt < ROSTER_WAIT_TRIES)
			{
				executor.schedule(() -> deliver(fresh, event, proof, target, attempt + 1),
					ROSTER_WAIT_SECONDS, TimeUnit.SECONDS);
				return;
			}
			// Clan scope: both players must be confirmed members by the game's own
			// list, or nothing is posted. Unconfirmed counts as no.
			if (!announced && scope == GroupService.LoanScope.CLAN
				&& (clanRoster.check(clan, first.getLender()) != ClanRoster.Membership.YES
				|| clanRoster.check(clan, first.getBorrower()) != ClanRoster.Membership.YES))
			{
				log.debug("Not posting {}: {} -> {} not both confirmed in {}", event,
					first.getLender(), first.getBorrower(), clan);
				return;
			}
			withIcons(fresh, strip -> buildAndSend(fresh, event, proof, target, strip));
		});
	}

	private static final String ANNOUNCED = ":ANNOUNCED";

	private synchronized boolean wasAnnounced(List<LendingEntry> loans)
	{
		String csv = configManager.getConfiguration(CONFIG_GROUP, POSTED_KEY);
		if (csv == null || csv.isEmpty()) return false;
		java.util.Set<String> posted = new java.util.HashSet<>(java.util.Arrays.asList(csv.split(",")));
		for (LendingEntry loan : loans)
		{
			if (loan.getId() != null && posted.contains(loan.getId() + ANNOUNCED)) return true;
		}
		return false;
	}

	/**
	 * Draw the items' icons into one small strip, the way they sit in an
	 * inventory, then hand it on. Icons come from the game so they are fetched on
	 * the client thread; one that never loads can't hold the post up for long.
	 */
	private void withIcons(List<LendingEntry> loans, java.util.function.Consumer<BufferedImage> then)
	{
		clientThread.invokeLater(() ->
		{
			// Names for any collateral still out - only the client thread can look them up
			for (LendingEntry loan : loans)
			{
				for (int[] p : idQty(loan.outstandingCollateralIds()))
				{
					itemNames.computeIfAbsent(p[0], id -> itemManager.getItemComposition(id).getName());
				}
			}
			List<AsyncBufferedImage> icons = new ArrayList<>();
			for (LendingEntry loan : loans)
			{
				if (icons.size() >= MAX_ICONS)
				{
					break;
				}
				if (loan.getItemId() > 0)
				{
					icons.add(itemManager.getImage(loan.getItemId(), Math.max(1, loan.getQuantity()), loan.getQuantity() > 1));
				}
			}
			AtomicBoolean done = new AtomicBoolean();
			AtomicInteger waiting = new AtomicInteger(icons.size());
			Runnable finish = () ->
			{
				if (done.compareAndSet(false, true))
				{
					executor.submit(() -> then.accept(strip(icons)));
				}
			};
			if (icons.isEmpty())
			{
				finish.run();
				return;
			}
			for (AsyncBufferedImage icon : icons)
			{
				icon.onLoaded(() ->
				{
					if (waiting.decrementAndGet() == 0)
					{
						finish.run();
					}
				});
			}
			executor.schedule(finish, ICON_WAIT_SECONDS, TimeUnit.SECONDS);
		});
	}

	private static BufferedImage strip(List<AsyncBufferedImage> icons)
	{
		if (icons.isEmpty())
		{
			return null;
		}
		int w = 36;
		int h = 32;
		int gap = 2;
		BufferedImage out = new BufferedImage(icons.size() * w + (icons.size() - 1) * gap, h, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = out.createGraphics();
		for (int i = 0; i < icons.size(); i++)
		{
			g.drawImage(icons.get(i), i * (w + gap), 0, null);
		}
		g.dispose();
		return out;
	}

	/** Build the post and send it. Runs on the executor - encoding the pictures is real work. */
	private void buildAndSend(List<LendingEntry> fresh, Event event, BufferedImage proof, String target,
		BufferedImage iconStrip)
	{
		LendingEntry first = fresh.get(0);
		if (event == Event.LOAN)
		{
			for (LendingEntry loan : fresh)
			{
				if (loan.getId() != null) claim(loan.getId() + ANNOUNCED);
			}
		}

		// Laid out like the Dink loot posts people already know: group name as a
		// small header, a sentence ending in a colon, one line per item (linked to
		// the wiki), then the numbers in boxes. The trade picture sits in the
		// corner and opens full size when clicked.
		StringBuilder items = new StringBuilder();
		List<String> collateral = new ArrayList<>();
		long total = 0;
		int shown = 0;
		for (LendingEntry loan : fresh)
		{
			total += loan.getValue();
			String c = collateralText(loan);
			if (c != null) collateral.add(c);
			if (shown++ >= MAX_LINES)
			{
				continue;
			}
			items.append('\n').append(Math.max(1, loan.getQuantity())).append(" x ").append(itemLink(loan))
				.append(" (").append(QuantityFormatter.quantityToStackSize(loan.getValue())).append(")");
		}
		if (fresh.size() > MAX_LINES)
		{
			items.append("\n...and ").append(fresh.size() - MAX_LINES).append(" more");
		}
		LendingGroup group = first.getGroupId() != null ? groupService.getGroup(first.getGroupId()) : null;

		JsonObject embed = new JsonObject();
		if (group != null && group.getName() != null)
		{
			JsonObject author = new JsonObject();
			author.addProperty("name", safe(group.getName()));
			embed.add("author", author);
		}
		embed.addProperty("title", event.icon + " " + event.label);
		embed.addProperty("description", lead(event, first) + "\n"
			+ (event == Event.PARTIAL ? missingList(fresh)
				: event == Event.RETURNED ? returnedList(fresh, collateral)
			: event == Event.OVERDUE ? overdueList(fresh)
				: items.toString()));
		embed.addProperty("color", event.color);
		embed.addProperty("timestamp", Instant.now().toString());

		JsonArray fields = new JsonArray();
		if (event != Event.PARTIAL)
		{
			fields.add(field("Value", "`" + QuantityFormatter.quantityToStackSize(total) + " gp`", true));
		}
		String collateralNow = String.join(" + ", collateral).replace("`", "'");
		boolean stillOut = event == Event.LOAN || event == Event.OVERDUE || event == Event.PARTIAL;
		if ((event == Event.LOAN || event == Event.OVERDUE) && !collateral.isEmpty())
		{
			fields.add(field("Collateral", "`" + collateralNow + "`", true));
		}
		if (event == Event.LOAN && first.getDueTime() <= 0)
		{
			fields.add(field("Due", "`No limit`", true));
		}
		if (stillOut && first.getDueTime() > 0 && first.getDueTime() < Long.MAX_VALUE / 2)
		{
			// "in 7 days" / "2 days ago", in each reader's own time zone. Can't sit
			// inside a code box - Discord wouldn't render it there.
			fields.add(field("Due", "<t:" + (first.getDueTime() / 1000) + ":R>", true));
		}
		embed.add("fields", fields);

		JsonObject footer = new JsonObject();
		footer.addProperty("text", "Lending Tracker");
		embed.add("footer", footer);

		// No username or avatar set here on purpose: the post uses the name and
		// picture the group gave the webhook in Discord, which is where it's
		// customised.
		JsonObject body = new JsonObject();
		// Tag the lender and borrower, if they turned "Ping me" on. Pings only work
		// in the message text, not inside the embed. allowed_mentions lists exactly
		// those two IDs, so nothing else in a post - an item or group name - can
		// ever ping anyone.
		JsonArray pingIds = new JsonArray();
		StringBuilder content = new StringBuilder();
		for (String who : new String[] { first.getLender(), first.getBorrower() })
		{
			String id = groupService.getMemberDiscordId(first.getGroupId(), who);
			if (id != null && !pingIds.contains(new com.google.gson.JsonPrimitive(id)))
			{
				pingIds.add(id);
				content.append(content.length() > 0 ? " " : "").append("<@").append(id).append(">");
			}
		}
		if (content.length() > 0)
		{
			body.addProperty("content", content.toString());
		}
		JsonObject mentions = new JsonObject();
		mentions.add("parse", new JsonArray());
		mentions.add("users", pingIds);
		body.add("allowed_mentions", mentions);

		// Two optional pictures: the trade window as the corner thumbnail (click to
		// enlarge) and the item icon strip, shown at its own small size underneath.
		byte[] tradePng = encode(proof);
		byte[] iconsPng = encode(iconStrip);
		JsonArray attachments = new JsonArray();
		List<String> fileNames = new ArrayList<>();
		List<byte[]> files = new ArrayList<>();
		if (tradePng != null)
		{
			JsonObject thumb = new JsonObject();
			thumb.addProperty("url", "attachment://trade.png");
			embed.add("thumbnail", thumb);
			fileNames.add("trade.png");
			files.add(tradePng);
		}
		if (iconsPng != null)
		{
			JsonObject image = new JsonObject();
			image.addProperty("url", "attachment://items.png");
			embed.add("image", image);
			fileNames.add("items.png");
			files.add(iconsPng);
		}
		for (int i = 0; i < files.size(); i++)
		{
			JsonObject att = new JsonObject();
			att.addProperty("id", i);
			att.addProperty("filename", fileNames.get(i));
			attachments.add(att);
		}
		JsonArray embeds = new JsonArray();
		embeds.add(embed);
		body.add("embeds", embeds);

		RequestBody requestBody;
		if (files.isEmpty())
		{
			requestBody = RequestBody.create(JSON, gson.toJson(body));
		}
		else
		{
			body.add("attachments", attachments);
			MultipartBody.Builder multipart = new MultipartBody.Builder()
				.setType(MultipartBody.FORM)
				.addFormDataPart("payload_json", gson.toJson(body));
			for (int i = 0; i < files.size(); i++)
			{
				multipart.addFormDataPart("files[" + i + "]", fileNames.get(i), RequestBody.create(PNG, files.get(i)));
			}
			requestBody = multipart.build();
		}
		send(target, requestBody);
	}

	private void send(String url, RequestBody body)
	{
		Request request = new Request.Builder().url(url).post(body).build();
		httpClient.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				log.debug("Discord webhook post failed: {}", e.getMessage());
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				try (Response r = response)
				{
					if (!r.isSuccessful())
					{
						log.debug("Discord webhook answered HTTP {}", r.code());
					}
				}
			}
		});
	}

	private static byte[] encode(BufferedImage image)
	{
		if (image == null)
		{
			return null;
		}
		try (ByteArrayOutputStream out = new ByteArrayOutputStream())
		{
			ImageIO.write(image, "png", out);
			byte[] bytes = out.toByteArray();
			// Well under Discord's upload limit for a cropped trade window; if
			// something odd produced a huge image, post the text alone.
			return bytes.length > 0 && bytes.length < 7_000_000 ? bytes : null;
		}
		catch (IOException e)
		{
			log.debug("Could not encode the trade picture: {}", e.getMessage());
			return null;
		}
	}

	/**
	 * Record that this post is being made; false if it already was. Claimed
	 * before sending, so two paths reporting the same loan at once (recorded
	 * here, then echoed back by sync) can't both get through.
	 */
	private synchronized boolean claim(String key)
	{
		java.util.LinkedHashSet<String> posted = new java.util.LinkedHashSet<>();
		String csv = configManager.getConfiguration(CONFIG_GROUP, POSTED_KEY);
		if (csv != null && !csv.isEmpty())
		{
			posted.addAll(java.util.Arrays.asList(csv.split(",")));
		}
		if (!posted.add(key))
		{
			return false;
		}
		java.util.Iterator<String> oldest = posted.iterator();
		while (posted.size() > POSTED_CAP && oldest.hasNext())
		{
			oldest.next();
			oldest.remove();
		}
		configManager.setConfiguration(CONFIG_GROUP, POSTED_KEY, String.join(",", posted));
		return true;
	}

	private boolean wanted(Event event)
	{
		switch (event)
		{
			case LOAN:
				return config.webhookLoans();
			case OVERDUE:
				return config.webhookOverdue();
			default:
				return config.webhookReturns();
		}
	}

	// The keeper posts: the lender, or the borrower for a loan the borrower keeps
	// because the lender can't run the plugin. Never both.
	private static boolean shouldReport(LendingEntry loan, String reporter)
	{
		return loan.isKeptByBorrower()
			? reporter.equalsIgnoreCase(loan.getBorrower())
			: reporter.equalsIgnoreCase(loan.getLender());
	}

	private static String collateralText(LendingEntry loan)
	{
		StringBuilder sb = new StringBuilder();
		if (loan.getCollateralValue() != null && loan.getCollateralValue() > 0 && "GP".equals(loan.getCollateralType()))
		{
			sb.append(QuantityFormatter.quantityToStackSize(loan.getCollateralValue())).append(" gp");
		}
		if (loan.getCollateralItems() != null && !loan.getCollateralItems().isEmpty())
		{
			if (sb.length() > 0) sb.append(" + ");
			sb.append(safe(loan.getCollateralItems()));
		}
		return sb.length() > 0 ? sb.toString() : null;
	}

	/** The sentence above the item list. Names bolded, markdown in them escaped. */
	private static String lead(Event event, LendingEntry first)
	{
		String lender = "**" + md(first.getLender()) + "**";
		String borrower = "**" + md(first.getBorrower()) + "**";
		switch (event)
		{
			case LOAN:
				return lender + " lent " + borrower + ":";
			case RETURNED:
				return borrower + " returned everything to " + lender + ":";
			case OVERDUE:
				long late = Math.max(1, (System.currentTimeMillis() - first.getDueTime()) / 86400000L);
				return borrower + " is **" + late + (late == 1 ? " day" : " days") + "** overdue returning to " + lender + ":";
			case PARTIAL:
				return borrower + " returned part of the loan to " + lender + " - it stays open until everything is back.";
			case FORGIVEN:
				return lender + " forgave " + borrower + ":";
			default:
				return "Loan between " + lender + " and " + borrower + " removed:";
		}
	}

	/**
	 * What a part-return still leaves out, and who has it - loaned items with the
	 * borrower, collateral with the lender.
	 */
	private String missingList(List<LendingEntry> loans)
	{
		// A "diff" code box shows lines starting with "-" in red on Discord for PC;
		// the cross on each line carries it where the red doesn't show (some phone
		// apps). Code boxes can't hold links or bold, so names are plain here.
		LendingEntry first = loans.get(0);
		List<String> lines = new ArrayList<>();
		for (LendingEntry l : loans)
		{
			int q = l.outstandingLentQty();
			if (q > 0)
			{
				lines.add(q + " x " + plain(l.getItemName()) + "  (with " + plain(l.getBorrower()) + ")");
			}
		}
		for (LendingEntry l : loans)
		{
			for (int[] p : idQty(l.outstandingCollateralIds()))
			{
				lines.add(p[1] + " x " + plain(itemNames.getOrDefault(p[0], "Item " + p[0]))
					+ " collateral  (with " + plain(first.getLender()) + ")");
			}
			long gp = l.outstandingCollateralGp();
			if (gp > 0)
			{
				lines.add(QuantityFormatter.quantityToStackSize(gp) + " gp collateral  (with " + plain(first.getLender()) + ")");
			}
		}
		// What has come back so far, so the box shows progress, not just the gap.
		List<String> back = new ArrayList<>();
		for (LendingEntry l : loans)
		{
			int returned = Math.max(1, l.getQuantity()) - l.outstandingLentQty();
			if (returned > 0)
			{
				back.add(returned + " x " + plain(l.getItemName()) + "  (returned)");
			}
		}
		for (LendingEntry l : loans)
		{
			java.util.Map<Integer, Integer> stillOut = new java.util.HashMap<>();
			for (int[] p : idQty(l.outstandingCollateralIds()))
			{
				stillOut.merge(p[0], p[1], Integer::sum);
			}
			for (int[] p : idQty(l.getCollateralItemIds()))
			{
				int got = p[1] - stillOut.getOrDefault(p[0], 0);
				if (got > 0)
				{
					back.add(got + " x " + plain(itemNames.getOrDefault(p[0], "Item " + p[0])) + " collateral  (given back)");
				}
			}
			long gpGiven = l.getCollateralValue() != null && "GP".equals(l.getCollateralType()) ? l.getCollateralValue() : 0;
			long gpBack = gpGiven - l.outstandingCollateralGp();
			if (gpBack > 0)
			{
				back.add(QuantityFormatter.quantityToStackSize(gpBack) + " gp collateral  (given back)");
			}
		}
		StringBuilder sb = new StringBuilder("\n**Return progress:**\n```diff");
		for (String line : back)
		{
			// Still "-" lines: the whole box stays red while the loan is open; the
			// green tick is what marks these as already back.
			sb.append("\n- \u2705 ").append(line);
		}
		for (String line : lines)
		{
			sb.append("\n- \u274C ").append(line);
		}
		return sb.append("\n```").toString();
	}

	/**
	 * The green twin of missingList: "+" lines in a diff box show green on PC, and
	 * the tick carries it elsewhere. A return only completes once the collateral
	 * is back too, so that gets its own line.
	 */
	private static String returnedList(List<LendingEntry> loans, List<String> collateral)
	{
		StringBuilder sb = new StringBuilder("```diff");
		int shown = 0;
		for (LendingEntry l : loans)
		{
			if (shown++ >= MAX_LINES)
			{
				sb.append("\n+ ...and ").append(loans.size() - MAX_LINES).append(" more");
				break;
			}
			sb.append("\n+ \u2705 ").append(Math.max(1, l.getQuantity())).append(" x ").append(plain(l.getItemName()));
		}
		if (!collateral.isEmpty())
		{
			sb.append("\n+ \u2705 Collateral back with ").append(plain(loans.get(0).getBorrower()))
				.append(": ").append(plain(String.join(" + ", collateral)));
		}
		return sb.append("\n```").toString();
	}

	/** Overdue: what's still out, in yellow, with who has it. */
	private static String overdueList(List<LendingEntry> loans)
	{
		// An "ansi" code box takes real colour codes; 33 is yellow on Discord for PC.
		// ("fix" boxes used to be yellow but Discord now draws them blue.)
		StringBuilder sb = new StringBuilder("```ansi");
		for (LendingEntry l : loans)
		{
			int q = l.outstandingLentQty();
			if (q > 0)
			{
				sb.append("\n\u001B[33m\u23F0 ").append(q).append(" x ").append(plain(l.getItemName()))
					.append("  (with ").append(plain(l.getBorrower())).append(")\u001B[0m");
			}
		}
		return sb.append("\n```").toString();
	}

	/** Text safe inside a code box: nothing that could close it early. */
	private static String plain(String s)
	{
		return s == null ? "-" : s.replace("`", "'");
	}

	/** "itemId:qty,itemId:qty" -> pairs with a quantity still owed. */
	private static List<int[]> idQty(String csv)
	{
		List<int[]> out = new ArrayList<>();
		if (csv == null || csv.isEmpty())
		{
			return out;
		}
		for (String part : csv.split(","))
		{
			String[] kv = part.split(":");
			try
			{
				int id = Integer.parseInt(kv[0].trim());
				int qty = kv.length > 1 ? Integer.parseInt(kv[1].trim()) : 1;
				if (id > 0 && qty > 0)
				{
					out.add(new int[] { id, qty });
				}
			}
			catch (NumberFormatException ignored)
			{
				// a damaged pair just isn't listed
			}
		}
		return out;
	}

	/** Item name linked to its OSRS Wiki page (looked up by id, so names never need matching). */
	private static String itemLink(LendingEntry loan)
	{
		String name = md(loan.getItemName()).replace("[", "(").replace("]", ")");
		return loan.getItemId() > 0
			? "[" + name + "](https://oldschool.runescape.wiki/w/Special:Lookup?type=item&id=" + loan.getItemId() + ")"
			: name;
	}

	private static String md(String s)
	{
		if (s == null) return "-";
		return s.replaceAll("([*_~`|>])", "\\\\$1");
	}

	private static JsonObject field(String name, String value, boolean inline)
	{
		JsonObject f = new JsonObject();
		f.addProperty("name", name);
		f.addProperty("value", value == null || value.isEmpty() ? "-" : value);
		f.addProperty("inline", inline);
		return f;
	}

	/**
	 * Trimmed to Discord's field limit and otherwise left exactly as it is, so a
	 * bot reads the real name. Pings are already off via allowed_mentions.
	 */
	private static String safe(String s)
	{
		if (s == null) return "-";
		return s.length() > 1000 ? s.substring(0, 1000) : s;
	}
}

package com.guess34.lendingtracker.services;

import java.awt.*;
import java.awt.image.BufferedImage;
import java.io.File;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.text.SimpleDateFormat;
import java.time.Instant;
import java.util.Date;
import java.util.concurrent.ScheduledExecutorService;
import javax.inject.Inject;
import javax.inject.Singleton;
import javax.imageio.ImageIO;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.DrawManager;
import com.guess34.lendingtracker.LendingTrackerConfig;
import com.guess34.lendingtracker.model.LendingEntry;

/**
 * ProofScreenshot - Captures and saves proof screenshots for lending transactions
 * Supports capturing during trade screens and after completion
 */
@Slf4j
@Singleton
public class ProofScreenshot
{
	@Inject
	private LendingTrackerConfig config;

	@Inject
	private DrawManager drawManager;

	@Inject
	private Client client;

	@Inject
	private ScheduledExecutorService executor;

	private static final SimpleDateFormat DATE_FORMAT = new SimpleDateFormat("yyyy-MM-dd_HH-mm-ss");
	private static final SimpleDateFormat DISPLAY_DATE_FORMAT = new SimpleDateFormat("yyyy-MM-dd HH:mm:ss");

	// Base directory for all screenshots (inside .runelite per Plugin Hub rules)
	private static final Path BASE_DIR = Paths.get(System.getProperty("user.home"), ".runelite", "lending-tracker", "proof");

	/**
	 * Get the screenshot directory for a specific user and group
	 */
	private Path getScreenshotDirectory(String username, String groupName)
	{
		// Clean up names for file system safety
		String safeUsername = sanitizeFilename(username != null ? username : "unknown");
		String safeGroupName = sanitizeFilename(groupName != null ? groupName : "default");

		return BASE_DIR.resolve(safeUsername).resolve(safeGroupName);
	}

	/**
	 * Where this user's proof screenshots are kept, created if it isn't there yet.
	 *
	 * The panel shows this as text instead of opening it. Launching the folder
	 * means handing a local path to whatever the OS decides should handle it,
	 * which the Plugin Hub doesn't allow.
	 */
	public String getScreenshotFolderPath(String username, String groupName)
	{
		// The BASE folder, not this group's subfolder. Screenshots are filed under
		// the group that was active when the trade happened, so pointing at the
		// group active right now sends anyone who has since switched groups to an
		// empty directory - which is what people were reporting as "no screenshots".
		// Everything is under here whichever group or name it was filed with.
		//
		// Deliberately does NOT create the folder either. It only needed to exist so
		// it could be opened; saving a screenshot makes it when there is something
		// to put in it.
		return BASE_DIR.toString();
	}

	/** Screenshot phases captured across a loan trade's lifecycle. */
	public static final String PHASE_FIRST_SCREEN = "first_screen";
	public static final String PHASE_CONFIRM_SCREEN = "confirm_screen";
	public static final String PHASE_COMPLETED = "completed";

	// Frames captured while the trade screens were visible (keyed by phase),
	// waiting for the trade to complete. Written to disk only when the trade is
	// accepted, so a declined trade never leaves files behind. Re-caching a phase
	// overwrites it, so the saved first-screen shot reflects the FINAL offers.
	// The generation counter is bumped by commit/discard so an in-flight capture
	// from an already-ended trade can't store its frame late and get committed as
	// "proof" of a DIFFERENT trade; all access goes through cacheLock so the
	// generation check and the store/take are atomic.
	private final Object cacheLock = new Object();
	private final java.util.Map<String, BufferedImage> cachedFrames = new java.util.HashMap<>();
	// The same frames cut down to just the trade window. These, never the full
	// frame, are what may leave the machine (the Discord post): a full frame
	// carries the chatbox - private messages included - and the inventory.
	private final java.util.Map<String, BufferedImage> cachedCrops = new java.util.HashMap<>();
	private int cacheGeneration;

	/**
	 * Capture the next rendered frame and hold it in memory under the given
	 * phase. Call while the relevant trade screen is open — the "Accepted trade."
	 * message only arrives after the windows close, so capturing at that point
	 * would miss the evidence.
	 */
	public void cacheTradeFrame(String phase)
	{
		cacheTradeFrame(phase, -1);
	}

	/**
	 * As above, also keeping a copy cropped to the given widget (the trade
	 * window). Its bounds are read inside the frame listener, which runs on the
	 * client thread while that very frame is drawn - so the crop matches it.
	 */
	public void cacheTradeFrame(String phase, int cropWidgetId)
	{
		final int generation;
		synchronized (cacheLock)
		{
			generation = cacheGeneration;
		}
		drawManager.requestNextFrameListener(image ->
		{
			Rectangle bounds = null;
			Dimension real = null;
			if (cropWidgetId != -1)
			{
				Widget w = client.getWidget(cropWidgetId);
				if (w != null && !w.isHidden())
				{
					bounds = w.getBounds();
					// Widget bounds are in game pixels; the frame may be stretched.
					real = client.isStretchedEnabled()
						? client.getRealDimensions()
						: new Dimension(client.getCanvasWidth(), client.getCanvasHeight());
				}
			}
			final Rectangle cropBounds = bounds;
			final Dimension gameSize = real;
			executor.submit(() ->
			{
				BufferedImage frame = toBufferedImage(image);
				BufferedImage crop = crop(frame, cropBounds, gameSize);
				synchronized (cacheLock)
				{
					if (cacheGeneration == generation)
					{
						cachedFrames.put(phase, frame);
						if (crop != null)
						{
							cachedCrops.put(phase, crop);
						}
					}
				}
			});
		});
	}

	/**
	 * The trade-window picture for this trade - confirm screen if we have it,
	 * else the first screen - or null. Does not clear anything; call before
	 * commitCachedTrade/discardCachedFrame, which do.
	 */
	public BufferedImage takeProofCrop()
	{
		synchronized (cacheLock)
		{
			BufferedImage confirm = cachedCrops.get(PHASE_CONFIRM_SCREEN);
			return confirm != null ? confirm : cachedCrops.get(PHASE_FIRST_SCREEN);
		}
	}

	private static BufferedImage crop(BufferedImage frame, Rectangle bounds, Dimension real)
	{
		if (frame == null || bounds == null || real == null || real.width <= 0 || real.height <= 0
			|| bounds.width <= 0 || bounds.height <= 0)
		{
			return null;
		}
		double sx = frame.getWidth() / (double) real.width;
		double sy = frame.getHeight() / (double) real.height;
		int x = Math.max(0, (int) Math.floor(bounds.x * sx));
		int y = Math.max(0, (int) Math.floor(bounds.y * sy));
		int w = Math.min((int) Math.ceil(bounds.width * sx), frame.getWidth() - x);
		int h = Math.min((int) Math.ceil(bounds.height * sy), frame.getHeight() - y);
		if (w <= 0 || h <= 0)
		{
			return null;
		}
		BufferedImage out = new BufferedImage(w, h, BufferedImage.TYPE_INT_RGB);
		Graphics2D g = out.createGraphics();
		g.drawImage(frame.getSubimage(x, y, w, h), 0, 0, null);
		g.dispose();
		return out;
	}

	/**
	 * Save every cached trade frame (first screen, confirm screen) as proof
	 * screenshots for a completed trade, plus a fresh post-completion frame that
	 * catches the "Accepted trade." and loan-recorded chat lines — up to three
	 * shots documenting the whole hand-over.
	 */
	public void commitCachedTrade(String username, String groupName, String tradePartner,
		String eventType, LendingEntry entry)
	{
		java.util.Map<String, BufferedImage> frames;
		synchronized (cacheLock)
		{
			cacheGeneration++;
			frames = new java.util.HashMap<>(cachedFrames);
			cachedFrames.clear();
			cachedCrops.clear();
		}
		for (java.util.Map.Entry<String, BufferedImage> cached : frames.entrySet())
		{
			final String phase = cached.getKey();
			final BufferedImage toSave = cached.getValue();
			executor.submit(() ->
				saveScreenshot(toSave, username, groupName, tradePartner, eventType, phase, entry));
		}
		// Fresh frame after completion — the chat now shows the acceptance and the
		// recorded items in text
		captureTradeScreenshot(username, groupName, tradePartner, eventType, PHASE_COMPLETED, entry);
	}

	/** Drop all cached frames (trade declined or cancelled). */
	public void discardCachedFrame()
	{
		synchronized (cacheLock)
		{
			cacheGeneration++;
			cachedFrames.clear();
			cachedCrops.clear();
		}
	}

	// Capture the game canvas with DrawManager, then overlay + save off-thread
	private void captureTradeScreenshot(String username, String groupName, String tradePartner,
										 String eventType, String phase, LendingEntry entry)
	{
		drawManager.requestNextFrameListener(image ->
			executor.submit(() ->
				saveScreenshot(image, username, groupName, tradePartner, eventType, phase, entry)));
	}

	// Overlay + write the PNG, off the client thread
	private void saveScreenshot(Image image, String username, String groupName, String tradePartner,
								 String eventType, String phase, LendingEntry entry)
	{
		try
		{
			BufferedImage screenshot = toBufferedImage(image);
			if (screenshot == null)
			{
				log.warn("Failed to capture game frame");
				return;
			}

			// Add overlay if enabled
			if (config != null && config.screenshotIncludeOverlay())
			{
				screenshot = addOverlayText(screenshot, eventType, phase, tradePartner, entry);
			}

			// Build filename: eventType_phase_partner_timestamp.png
			String timestamp = DATE_FORMAT.format(Date.from(Instant.now()));
			String safePartner = sanitizeFilename(tradePartner != null ? tradePartner : "unknown");
			String filename = String.format("%s_%s_%s_%s.png",
				eventType.toLowerCase(),
				phase,
				safePartner,
				timestamp);

			// Save to user/group specific directory
			Path outDir = getScreenshotDirectory(username, groupName);
			Files.createDirectories(outDir);

			File outFile = outDir.resolve(filename).toFile();
			ImageIO.write(screenshot, "png", outFile);
		}
		catch (Exception e)
		{
			log.error("Failed to save proof screenshot: {}", e.getMessage());
		}
	}

	private BufferedImage toBufferedImage(Image image)
	{
		if (image == null)
		{
			return null;
		}
		BufferedImage buffered = new BufferedImage(
			image.getWidth(null), image.getHeight(null), BufferedImage.TYPE_INT_ARGB);
		Graphics graphics = buffered.getGraphics();
		graphics.drawImage(image, 0, 0, null);
		graphics.dispose();
		return buffered;
	}

	/**
	 * Add overlay text with trade details
	 */
	private BufferedImage addOverlayText(BufferedImage img, String eventType, String phase,
										  String tradePartner, LendingEntry entry)
	{
		Graphics2D g = img.createGraphics();
		try
		{
			g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);

			int boxWidth = Math.min(img.getWidth() - 20, 450);
			int boxHeight = 180;
			int boxX = 10;
			int boxY = 10;

			// Semi-transparent background
			g.setColor(new Color(0, 0, 0, 200));
			g.fillRoundRect(boxX, boxY, boxWidth, boxHeight, 12, 12);

			// Border
			g.setColor(new Color(255, 152, 0)); // Orange border
			g.setStroke(new BasicStroke(2));
			g.drawRoundRect(boxX, boxY, boxWidth, boxHeight, 12, 12);

			int y = boxY + 24;
			int x = boxX + 12;

			// Title
			g.setColor(new Color(255, 152, 0));
			g.setFont(new Font("Dialog", Font.BOLD, 16));
			g.drawString("LendingTracker Proof", x, y);
			y += 24;

			// Event info
			g.setColor(Color.WHITE);
			g.setFont(new Font("Dialog", Font.PLAIN, 13));

			String timestamp = DISPLAY_DATE_FORMAT.format(new Date());
			g.drawString("Time: " + timestamp, x, y);
			y += 18;

			if (eventType != null)
			{
				String phaseLabel = phase != null ? " (" + formatPhase(phase) + ")" : "";
				g.drawString("Event: " + eventType + phaseLabel, x, y);
				y += 18;
			}

			if (tradePartner != null)
			{
				g.drawString("Trade Partner: " + tradePartner, x, y);
				y += 18;
			}

			if (entry != null)
			{
				g.drawString("Lender: " + safe(entry.getLender()), x, y);
				y += 18;
				g.drawString("Borrower: " + safe(entry.getBorrower()), x, y);
				y += 18;
				g.drawString("Item: " + safe(entry.getItem()) + " x" + entry.getQuantity(), x, y);
				y += 18;

				// Collateral info
				String col = formatCollateral(entry);
				g.drawString("Collateral: " + col, x, y);
			}

			return img;
		}
		finally
		{
			g.dispose();
		}
	}

	/**
	 * Format the phase for display
	 */
	private String formatPhase(String phase)
	{
		if (phase == null) return "";
		switch (phase.toLowerCase())
		{
			case "first_screen": return "First Trade Screen";
			case "second_accept": return "Second Accept Screen";
			case "confirm_screen": return "Confirm Screen";
			case "completed": return "Trade Completed";
			default: return phase;
		}
	}

	/**
	 * Format collateral info for display
	 */
	private String formatCollateral(LendingEntry entry)
	{
		if (entry.getCollateralValue() != null && entry.getCollateralValue() > 0)
		{
			return formatGp(entry.getCollateralValue()) + " GP";
		}
		else if (entry.getCollateralItems() != null && !entry.getCollateralItems().isEmpty())
		{
			return "Items: " + entry.getCollateralItems();
		}
		else if (entry.isAgreedNoCollateral())
		{
			return "None (agreed)";
		}
		return "None";
	}

	/**
	 * Format GP value with commas
	 */
	private String formatGp(long value)
	{
		return String.format("%,d", value);
	}

	/**
	 * Null-safe string
	 */
	private static String safe(String s)
	{
		return s == null ? "" : s;
	}

	/**
	 * Sanitize filename for file system safety
	 */
	private String sanitizeFilename(String name)
	{
		if (name == null) return "unknown";
		// Replace invalid characters with underscore
		return name.replaceAll("[^a-zA-Z0-9_\\-]", "_");
	}

}

package com.guess34.lendingtracker.services;

import java.util.ArrayList;
import java.util.Collection;
import java.util.Collections;
import java.util.EnumSet;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.EquipmentInventorySlot;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.game.ItemEquipmentStats;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemStats;

/**
 * Sorts gear into the groups people actually shop by - melee, range, mage, tank
 * and so on - straight from the item's own equipment bonuses.
 *
 * Worked out on each client from RuneLite's item data and never sent anywhere,
 * so nobody has to tag anything and older clients see nothing new on the wire.
 * The lookup has to run on the client thread, so results are cached and the
 * panel asks for anything it has not seen yet, then redraws once it is known.
 */
@Slf4j
@Singleton
public class ItemCategories
{
	public enum Category
	{
		MELEE("Melee"),
		RANGE("Range"),
		MAGIC("Mage"),
		TANK("Tank"),
		DPS("DPS"),
		STAB("Stab"),
		SLASH("Slash"),
		CRUSH("Crush");

		private final String label;

		Category(String label)
		{
			this.label = label;
		}

		public String getLabel()
		{
			return label;
		}
	}

	private final ItemManager itemManager;
	private final ClientThread clientThread;
	private final Map<Integer, Set<Category>> cache = new ConcurrentHashMap<>();
	private final Set<Integer> queued = ConcurrentHashMap.newKeySet();

	@Inject
	public ItemCategories(ItemManager itemManager, ClientThread clientThread)
	{
		this.itemManager = itemManager;
		this.clientThread = clientThread;
	}

	/** This item's categories, or null if it has not been worked out yet. */
	public Set<Category> get(int itemId)
	{
		return cache.get(itemId);
	}

	/**
	 * Work out any of these not known yet, then run onReady if anything new was
	 * learned. Cheap to call on every redraw - known and already-queued ids are
	 * skipped.
	 */
	public void prime(Collection<Integer> itemIds, Runnable onReady)
	{
		List<Integer> missing = new ArrayList<>();
		for (Integer id : itemIds)
		{
			if (id != null && id > 0 && !cache.containsKey(id) && queued.add(id))
			{
				missing.add(id);
			}
		}
		if (missing.isEmpty())
		{
			return;
		}
		clientThread.invokeLater(() ->
		{
			Map<Integer, Set<Category>> batch = new HashMap<>();
			boolean anyStats = false;
			for (int id : missing)
			{
				ItemStats stats = null;
				try
				{
					stats = itemManager.getItemStats(id);
				}
				catch (Exception e)
				{
					log.debug("No item stats for {}: {}", id, e.getMessage());
				}
				anyStats |= stats != null;
				batch.put(id, classify(stats));
			}
			queued.removeAll(missing);
			// A batch with no stats at all means RuneLite has not finished
			// downloading them yet. Caching that would file every item under
			// nothing for the rest of the session, so leave it to be asked again.
			if (anyStats)
			{
				cache.putAll(batch);
				if (onReady != null)
				{
					onReady.run();
				}
			}
		});
	}

	static Set<Category> classify(ItemStats stats)
	{
		if (stats == null || !stats.isEquipable() || stats.getEquipment() == null)
		{
			return Collections.emptySet();
		}
		ItemEquipmentStats e = stats.getEquipment();
		Set<Category> out = EnumSet.noneOf(Category.class);
		boolean weapon = e.getSlot() == EquipmentInventorySlot.WEAPON.getSlotIdx();

		// Each style scores its accuracy plus its damage. Magic damage is a
		// percentage, so it is weighted up to sit on the same scale.
		float melee = Math.max(e.getAstab(), Math.max(e.getAslash(), e.getAcrush())) + e.getStr();
		float range = e.getArange() + e.getRstr();
		float magic = e.getAmagic() + e.getMdmg() * 3f;
		float best = Math.max(melee, Math.max(range, magic));
		if (best > 0)
		{
			// Anything close to the best style counts too, so hybrid gear
			// shows up under every style it is actually good for.
			if (melee > 0 && melee >= best * 0.6f) out.add(Category.MELEE);
			if (range > 0 && range >= best * 0.6f) out.add(Category.RANGE);
			if (magic > 0 && magic >= best * 0.6f) out.add(Category.MAGIC);
		}

		// Tank: heavy defence and next to nothing on offence (Justiciar, Torva,
		// Elysian, DFS), or a weapon that is mostly a wall (Dinh's bulwark).
		int defence = e.getDstab() + e.getDslash() + e.getDcrush() + e.getDrange();
		if ((defence >= 150 && best <= 8) || (weapon && defence >= 300))
		{
			out.add(Category.TANK);
		}

		// DPS: gear that adds damage. For weapons that is any damage bonus, or
		// enough accuracy to be a real ranged or magic weapon.
		boolean dps = weapon
			? e.getStr() > 0 || e.getRstr() > 0 || e.getMdmg() > 0 || e.getArange() >= 60 || e.getAmagic() >= 25
			: e.getStr() >= 5 || e.getRstr() >= 2 || e.getMdmg() >= 2;
		if (dps)
		{
			out.add(Category.DPS);
		}

		// Attack style. Weapons take their strongest; other gear only when one
		// style clearly leads (Inquisitor's is crush, a torture is all three).
		if (out.contains(Category.MELEE))
		{
			int stab = e.getAstab();
			int slash = e.getAslash();
			int crush = e.getAcrush();
			int top = Math.max(stab, Math.max(slash, crush));
			int second = stab + slash + crush - top - Math.min(stab, Math.min(slash, crush));
			if (top > 0 && (weapon || top >= second * 1.25f))
			{
				out.add(top == stab ? Category.STAB : top == slash ? Category.SLASH : Category.CRUSH);
			}
		}
		return out;
	}
}

package com.guess34.lendingtracker.services;

import com.google.gson.Gson;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.config.ConfigManager;
import com.guess34.lendingtracker.model.LendingEntry;
import com.guess34.lendingtracker.model.LendingGroup;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.io.*;
import java.nio.file.*;
import java.time.Instant;
import java.util.*;
import java.util.stream.Collectors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;

@Slf4j
@Singleton
public class LocalDataSyncService {

    private static final String BACKUP_DIR = System.getProperty("user.home") + File.separator + ".runelite" + File.separator + "lending-tracker" + File.separator + "backups";
    private static final String SYNC_DATA_FILE = "lending-data-sync.json";
    private static final String BACKUP_FILE_PREFIX = "lending-backup-";
    private static final int MAX_BACKUP_FILES = 10;

    @Inject
    private ConfigManager configManager;

    @Inject
    private GroupService groupService;

    @Inject
    private DataService dataService;

    @Inject
    private ScheduledExecutorService executor;

    @Inject
    private Gson gson;

    private Path backupDirectory;
    private Path syncDataFile;
    private ScheduledFuture<?> backupTask;

    public void initialize() {
        try {
            // Create backup directory
            backupDirectory = Paths.get(BACKUP_DIR);
            if (!Files.exists(backupDirectory)) {
                Files.createDirectories(backupDirectory);

            }

            syncDataFile = backupDirectory.resolve(SYNC_DATA_FILE);

            schedulePeriodicBackup();


        } catch (IOException e) {
            log.error("Failed to initialize LocalDataSyncService", e);
        }
    }

    /**
     * ADDED: Called when user logs in - now safe to load sync data
     */
    public void onAccountLogin() {

        loadSyncData();
    }

    /**
     * Create a complete backup of all lending data
     */
    public void createBackup() {
        try {
            BackupData backupData = new BackupData();
            backupData.timestamp = Instant.now().toEpochMilli();
            backupData.groups = new ArrayList<>(groupService.getAllGroups());
            backupData.activeEntries = dataService.getActiveEntries();
            backupData.historyEntries = dataService.getHistoryEntries();
            backupData.availableEntries = new HashMap<>();
            backupData.borrowedEntries = new HashMap<>();
            backupData.lentEntries = new HashMap<>();

            // Collect per-group data
            for (LendingGroup group : backupData.groups) {
                String groupId = group.getId();
                backupData.availableEntries.put(groupId, dataService.getAvailable(groupId));
                backupData.borrowedEntries.put(groupId, dataService.getBorrowed(groupId));
                backupData.lentEntries.put(groupId, dataService.getLent(groupId));
            }

            String backupJson = gson.toJson(backupData);

            // Write to timestamped backup file
            String backupFileName = BACKUP_FILE_PREFIX + Instant.now().toEpochMilli() + ".json";
            Path backupFile = backupDirectory.resolve(backupFileName);
            Files.write(backupFile, backupJson.getBytes());

            // Also update the sync data file for cross-session persistence
            Files.write(syncDataFile, backupJson.getBytes());

            // Clean up old backup files
            cleanupOldBackups();


        } catch (IOException e) {
            log.error("Failed to create backup", e);
        }
    }

    /**
     * Load and sync data from previous sessions
     */
    private void loadSyncData() {
        // syncDataFile stays null if initialize() failed — Files.exists(null)
        // would NPE outside the try below and abort the caller's login flow.
        if (syncDataFile == null || !Files.exists(syncDataFile)) {

            return;
        }

        try {
            String syncJson = new String(Files.readAllBytes(syncDataFile));
            BackupData syncData = gson.fromJson(syncJson, BackupData.class);

            if (syncData != null) {
                // Sync group data - merge with existing groups
                syncGroups(syncData.groups);

                // Sync lending entries - merge new entries and update existing ones
                syncLendingEntries(syncData);


            }

        } catch (Exception e) {
            // Catch everything, not just IO: a malformed backup must degrade to
            // "no restore" — an escaping exception here would abort the rest of
            // the caller's login flow (sync never starts until relog).
            log.error("Failed to load sync data", e);
        }
    }

    /**
     * Sync groups - merge new groups and update existing ones
     */
    private void syncGroups(List<LendingGroup> syncedGroups) {
        if (syncedGroups == null) return;

        for (LendingGroup syncedGroup : syncedGroups) {
            if (syncedGroup == null || syncedGroup.getId() == null) continue;
            LendingGroup existingGroup = groupService.getGroup(syncedGroup.getId());

            if (existingGroup == null) {
                // Restore the group AS-IS, keeping its original id/secret/roster.
                // (Recreating via createGroup minted a new id — forking the group
                // from its sync room and orphaning its per-group data — and could
                // NPE on a name collision, aborting the rest of the login flow.)
                groupService.restoreGroupFromBackup(syncedGroup);
            } else {
                // Existing group - check for new members
                syncGroupMembers(existingGroup, syncedGroup);
            }
        }
    }

    /**
     * Sync group members - add new members without removing existing ones
     */
    private void syncGroupMembers(LendingGroup existing, LendingGroup synced) {
        if (synced.getMembers() == null) return;

        Set<String> existingMemberNames = new HashSet<>();
        if (existing.getMembers() != null) {
            existing.getMembers().forEach(member -> existingMemberNames.add(member.getName().toLowerCase()));
        }

        for (var syncedMember : synced.getMembers()) {
            if (syncedMember.getName() == null) continue;
            if (!existingMemberNames.contains(syncedMember.getName().toLowerCase())) {
                // Restore via the backup-aware path: it keeps the member's original
                // joinedAt and respects kick tombstones, so a stale backup can't
                // resurrect someone who was kicked while this user was offline.
                // (addMember here minted a FRESH joinedAt and cleared the tombstone,
                // which un-kicked them for the entire group.)
                groupService.restoreMemberFromBackup(existing.getId(), syncedMember);
            }
        }

        // saveGroup is not needed as restoreMemberFromBackup already saves
    }

    /**
     * Sync lending entries - merge new entries
     */
    private void syncLendingEntries(BackupData syncData) {
        // Get current entry IDs to avoid duplicates
        Set<String> existingEntryIds = new HashSet<>();
        dataService.getActiveEntries().forEach(entry -> existingEntryIds.add(entry.getId()));
        dataService.getHistoryEntries().forEach(entry -> existingEntryIds.add(entry.getId()));

        // FIXED: Also include available, borrowed, and lent entry IDs to prevent duplication
        // This was causing quantity to increase on every login because available entries
        // were not in existingEntryIds and got re-added via addToAvailableList
        for (LendingGroup group : groupService.getAllGroups()) {
            String groupId = group.getId();
            dataService.getAvailable(groupId).forEach(entry -> {
                if (entry.getId() != null) existingEntryIds.add(entry.getId());
            });
            dataService.getBorrowed(groupId).forEach(entry -> {
                if (entry.getId() != null) existingEntryIds.add(entry.getId());
            });
            dataService.getLent(groupId).forEach(entry -> {
                if (entry.getId() != null) existingEntryIds.add(entry.getId());
            });
        }

        // Sync active entries. restoreEntry (NOT addEntry) keeps the backup's
        // original updatedAt and publishes nothing — stamping a backup copy "now"
        // would let its stale return tallies win last-write-wins group-wide.
        if (syncData.activeEntries != null) {
            for (LendingEntry entry : syncData.activeEntries) {
                if (!existingEntryIds.contains(entry.getId())) {
                    dataService.restoreEntry(entry);

                }
            }
        }

        // Sync history entries - add them directly to history list
        if (syncData.historyEntries != null) {
            for (LendingEntry entry : syncData.historyEntries) {
                if (!existingEntryIds.contains(entry.getId())) {
                    // Use completeEntry to add to history
                    dataService.addEntry(entry);
                    dataService.completeEntry(entry.getId(), true);

                }
            }
        }

        // Sync per-group entries
        syncPerGroupEntries(syncData, existingEntryIds);
    }

    /**
     * Sync per-group available, borrowed, and lent entries
     * FIXED: Uses restoreAvailable instead of addToAvailableList to prevent quantity duplication
     */
    private void syncPerGroupEntries(BackupData syncData, Set<String> existingEntryIds) {
        // Sync available entries - use restore method that doesn't add quantities
        if (syncData.availableEntries != null) {
            for (Map.Entry<String, List<LendingEntry>> groupEntry : syncData.availableEntries.entrySet()) {
                String groupId = groupEntry.getKey();
                for (LendingEntry entry : groupEntry.getValue()) {
                    if (!existingEntryIds.contains(entry.getId())) {
                        // FIXED: Use restoreAvailable instead of addToAvailableList
                        // This prevents quantity from being added on every login
                        dataService.restoreAvailable(groupId, entry.getLender(), entry);
                    }
                }
            }
        }

        // Sync borrowed entries - use restore method that doesn't duplicate
        if (syncData.borrowedEntries != null) {
            for (Map.Entry<String, List<LendingEntry>> groupEntry : syncData.borrowedEntries.entrySet()) {
                String groupId = groupEntry.getKey();
                for (LendingEntry entry : groupEntry.getValue()) {
                    if (!existingEntryIds.contains(entry.getId())) {
                        // FIXED: Use restoreBorrowed instead of markAsBorrowed
                        dataService.restoreBorrowed(groupId, entry.getBorrower(), entry);
                    }
                }
            }
        }

        // Sync lent entries - use restore method that doesn't duplicate
        if (syncData.lentEntries != null) {
            for (Map.Entry<String, List<LendingEntry>> groupEntry : syncData.lentEntries.entrySet()) {
                String groupId = groupEntry.getKey();
                for (LendingEntry entry : groupEntry.getValue()) {
                    if (!existingEntryIds.contains(entry.getId())) {
                        // FIXED: Use restoreLent instead of markAsLent
                        dataService.restoreLent(groupId, entry.getLender(), entry.getBorrower(), entry, entry.getDueTime());
                    }
                }
            }
        }
    }

    /**
     * Schedule periodic automatic backups
     */
    private void schedulePeriodicBackup() {
        // Guarded because this is a @Singleton: initialize() runs again on every
        // re-enable, and without this each cycle left another backup task running
        // on the client's shared executor for the rest of the session.
        if (backupTask != null) {
            return;
        }
        backupTask = executor.scheduleAtFixedRate(() -> {
            try {
                createBackup();
            } catch (Exception e) {
                log.error("Failed to create scheduled backup", e);
            }
        }, 5, 5, TimeUnit.MINUTES); // Backup every 5 minutes
    }

    /**
     * Clean up old backup files, keeping only the most recent MAX_BACKUP_FILES
     */
    private void cleanupOldBackups() {
        try {
            List<Path> backupFiles = Files.list(backupDirectory)
                .filter(path -> path.getFileName().toString().startsWith(BACKUP_FILE_PREFIX))
                .sorted((a, b) -> {
                    try {
                        return Files.getLastModifiedTime(b).compareTo(Files.getLastModifiedTime(a));
                    } catch (IOException e) {
                        return 0;
                    }
                })
                .collect(Collectors.toList());

            // Delete old backup files
            if (backupFiles.size() > MAX_BACKUP_FILES) {
                for (int i = MAX_BACKUP_FILES; i < backupFiles.size(); i++) {
                    Files.deleteIfExists(backupFiles.get(i));

                }
            }

        } catch (IOException e) {
            log.error("Failed to cleanup old backups", e);
        }
    }

    /**
     * Data structure for backup/sync operations
     */
    private static class BackupData {
        long timestamp;
        List<LendingGroup> groups;
        List<LendingEntry> activeEntries;
        List<LendingEntry> historyEntries;
        Map<String, List<LendingEntry>> availableEntries;
        Map<String, List<LendingEntry>> borrowedEntries;
        Map<String, List<LendingEntry>> lentEntries;
    }

    public void shutdown() {
        // Ours to cancel - the executor belongs to the client and must not be
        // shut down here. Left running, this kept writing backups every five
        // minutes after the plugin was disabled.
        if (backupTask != null) {
            backupTask.cancel(false);
            backupTask = null;
        }
        // Final backup, handed off rather than waited on: shutDown must not block,
        // and this writes the whole dataset to disk.
        try {
            executor.execute(this::createBackup);
        } catch (Exception e) {
            log.warn("Could not queue the final backup: {}", e.getMessage());
        }
    }
}

package com.guess34.lendingtracker.ui;

import lombok.extern.slf4j.Slf4j;
import net.runelite.client.game.ItemManager;
import com.guess34.lendingtracker.model.LendingEntry;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

import javax.swing.*;
import javax.swing.border.EmptyBorder;
import java.awt.*;
import java.awt.image.BufferedImage;
import java.time.Instant;
import java.time.ZoneId;
import java.time.format.DateTimeFormatter;

/**
 * HistoryCard - Single transaction card for history list.
 */
@Slf4j
public class HistoryCard extends JPanel
{
	private static final Color CARD_BACKGROUND = ColorScheme.DARKER_GRAY_COLOR;
	private static final Color RETURNED_COLOR = new Color(0, 200, 0);
	private static final Color OVERDUE_COLOR = new Color(255, 140, 0);
	private static final Color DEFAULTED_COLOR = new Color(200, 0, 0);
	private static final DateTimeFormatter DATE_FORMAT = DateTimeFormatter.ofPattern("MMM dd");

	public HistoryCard(LendingEntry entry, ItemManager itemManager)
	{
		setLayout(new BorderLayout(10, 0));
		setBackground(CARD_BACKGROUND);
		setBorder(new EmptyBorder(8, 10, 8, 10));
		setMaximumSize(new Dimension(Integer.MAX_VALUE, 60));
		setPreferredSize(new Dimension(0, 60));

		// Left: Item Icon
		JLabel iconLabel = new JLabel();
		iconLabel.setPreferredSize(new Dimension(36, 36));

		// Load icon asynchronously
		SwingUtilities.invokeLater(() ->
		{
			BufferedImage itemImage = itemManager.getImage(entry.getItemId(), entry.getQuantity(), entry.getQuantity() > 1);
			if (itemImage != null)
			{
				// Scale to 36x36
				Image scaled = itemImage.getScaledInstance(36, 36, Image.SCALE_SMOOTH);
				iconLabel.setIcon(new ImageIcon(scaled));
			}
		});

		add(iconLabel, BorderLayout.WEST);

		// Center: Item Info
		JPanel centerPanel = new JPanel();
		centerPanel.setLayout(new BoxLayout(centerPanel, BoxLayout.Y_AXIS));
		centerPanel.setBackground(CARD_BACKGROUND);

		JLabel itemNameLabel = new JLabel(entry.getItem());
		itemNameLabel.setFont(FontManager.getRunescapeBoldFont());
		itemNameLabel.setForeground(Color.WHITE);
		itemNameLabel.setAlignmentX(Component.LEFT_ALIGNMENT);

		String participantInfo = String.format("Lent to: %s", entry.getBorrower());
		JLabel participantLabel = new JLabel(participantInfo);
		participantLabel.setFont(FontManager.getRunescapeSmallFont());
		participantLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		participantLabel.setAlignmentX(Component.LEFT_ALIGNMENT);

		centerPanel.add(itemNameLabel);
		centerPanel.add(Box.createVerticalStrut(2));
		centerPanel.add(participantLabel);

		add(centerPanel, BorderLayout.CENTER);

		// Right: Date and Status
		JPanel rightPanel = new JPanel();
		rightPanel.setLayout(new BoxLayout(rightPanel, BoxLayout.Y_AXIS));
		rightPanel.setBackground(CARD_BACKGROUND);

		// Date label
		String dateStr = DATE_FORMAT.format(Instant.ofEpochMilli(entry.getLendDate()).atZone(ZoneId.systemDefault()));
		JLabel dateLabel = new JLabel(dateStr);
		dateLabel.setFont(FontManager.getRunescapeSmallFont());
		dateLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		dateLabel.setAlignmentX(Component.RIGHT_ALIGNMENT);

		// Status badge
		JLabel statusBadge = createStatusBadge(entry);
		statusBadge.setAlignmentX(Component.RIGHT_ALIGNMENT);

		rightPanel.add(dateLabel);
		rightPanel.add(Box.createVerticalStrut(4));
		rightPanel.add(statusBadge);

		add(rightPanel, BorderLayout.EAST);

		// Hover anywhere on the card shows the full deal: borrower, dates,
		// collateral, notes (tooltips don't inherit, so set on every component)
		LoanTooltip.apply(entry, this, iconLabel, centerPanel, itemNameLabel,
			participantLabel, rightPanel, dateLabel, statusBadge);
	}

	/**
	 * Create status badge with appropriate color
	 */
	private JLabel createStatusBadge(LendingEntry entry)
	{
		String statusText;
		Color statusColor;

		if (entry.getReturnedAt() > 0)
		{
			statusText = "Returned";
			statusColor = RETURNED_COLOR;
		}
		else if (entry.isOverdue())
		{
			// Very overdue (> 30 days) = defaulted
			long daysSinceDue = (System.currentTimeMillis() - entry.getDueDate()) / (24 * 60 * 60 * 1000);
			if (daysSinceDue > 30)
			{
				statusText = "Defaulted";
				statusColor = DEFAULTED_COLOR;
			}
			else
			{
				statusText = "Overdue";
				statusColor = OVERDUE_COLOR;
			}
		}
		else
		{
			statusText = "Active";
			statusColor = ColorScheme.BRAND_ORANGE;
		}

		JLabel badge = new JLabel(statusText);
		badge.setFont(FontManager.getRunescapeSmallFont());
		badge.setForeground(Color.WHITE);
		badge.setBackground(statusColor);
		badge.setOpaque(true);
		badge.setBorder(new EmptyBorder(2, 8, 2, 8));
		badge.setHorizontalAlignment(SwingConstants.CENTER);

		return badge;
	}
}

