			JLabel itemLabel = new JLabel(itemName + " x" + request.quantity);
			itemLabel.setFont(FontManager.getRunescapeSmallFont());
			itemLabel.setForeground(Color.WHITE);

			// Requester name
			String requesterText = "By: " + request.requesterName;
			JLabel requesterLabel = new JLabel(requesterText);
			requesterLabel.setFont(FontManager.getRunescapeSmallFont());
			requesterLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);

			detailsPanel.add(itemLabel);
			detailsPanel.add(requesterLabel);

			// Matched against the marketplace, so nobody has to go looking.
			if (request.wantsMine || !request.listedBy.isEmpty())
			{
				String who = request.wantsMine ? "You have this listed"
					: "Listed by " + request.listedBy.get(0)
						+ (request.listedBy.size() > 1 ? " +" + (request.listedBy.size() - 1) : "");
				JLabel match = new JLabel(who);
				match.setFont(FontManager.getRunescapeSmallFont());
				match.setForeground(request.wantsMine ? ColorScheme.BRAND_ORANGE : new Color(0x8C, 0xE0, 0x8C));
				match.setToolTipText("<html>Listed right now by:<br>" + String.join("<br>", request.listedBy) + "</html>");
				detailsPanel.add(match);
				setMaximumSize(new Dimension(Integer.MAX_VALUE, 78));
				setPreferredSize(new Dimension(200, 72));
			}

			add(detailsPanel, BorderLayout.CENTER);

			// Right side: Duration and posted time
			rightPanel = new JPanel();
			rightPanel.setLayout(new BoxLayout(rightPanel, BoxLayout.Y_AXIS));
			rightPanel.setBackground(bgColor);
			rightPanel.setPreferredSize(new Dimension(55, 45));

			JLabel durationLabel = new JLabel(request.durationDays + " days");
			durationLabel.setFont(FontManager.getRunescapeSmallFont());
			durationLabel.setForeground(ColorScheme.GRAND_EXCHANGE_PRICE);

			JLabel timeLabel = new JLabel(request.getPostedTimeFormatted());
			timeLabel.setFont(FontManager.getRunescapeSmallFont());
			timeLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);

			rightPanel.add(durationLabel);
			rightPanel.add(timeLabel);

			add(rightPanel, BorderLayout.EAST);

			setComponentPopupMenu(createLookingForPopupMenu());
			addHoverEffect(this, new Color(55, 60, 70), bgColor, detailsPanel, rightPanel);
		}

		private JPopupMenu createLookingForPopupMenu()
		{
			JPopupMenu menu = new JPopupMenu();
			String currentPlayer = getCurrentPlayerName();
			boolean isOwner = request.requesterName != null && request.requesterName.equalsIgnoreCase(currentPlayer);

			// View items option for multi-item requests (details shown via tooltip)
			if (request.isMultiItem())
			{
				JMenuItem viewItemsItem = new JMenuItem(request.getItemCount() + " items - " +
					QuantityFormatter.quantityToStackSize(request.getTotalValue()) + " GP");
				viewItemsItem.setEnabled(false);
				menu.add(viewItemsItem);
				menu.addSeparator();
			}

			if (isOwner)
			{
				JMenuItem editItem = new JMenuItem("Edit Request");
				editItem.addActionListener(e -> showEditLookingForDialog(request));
				menu.add(editItem);

				// Owner can remove their own request
				JMenuItem removeItem = new JMenuItem("Remove Request");
				removeItem.addActionListener(e -> {
					int confirm = JOptionPane.showConfirmDialog(
						DashboardPanel.this,
						"Remove your request for " + request.itemName + "?",
						"Confirm Remove",
						JOptionPane.YES_NO_OPTION
					);
					if (confirm == JOptionPane.YES_OPTION)
					{
						String groupId = groupService.getCurrentGroupIdUnchecked();
						if (groupId != null)
						{
							removeLookingForRequest(groupId, request.id);
							refresh();
						}
					}
				});
				menu.add(removeItem);
			}
			else
			{
				JMenuItem offerItem = new JMenuItem("I Have This Item");
				offerItem.addActionListener(e -> {
					showOfferToLendDialog(currentPlayer, request);
				});
				menu.add(offerItem);
			}

			// Show notes if any
			if (request.notes != null && !request.notes.isEmpty())
			{
				menu.addSeparator();
				JMenuItem notesItem = new JMenuItem("Notes: " + request.notes);
				notesItem.setEnabled(false);
				menu.add(notesItem);
			}

			return menu;
		}

		private void showEditLookingForDialog(LookingForRequest request)
		{
			JPanel editPanel = new JPanel(new GridBagLayout());
			GridBagConstraints gbc = createDefaultGbc();
			gbc.anchor = GridBagConstraints.WEST;

			gbc.gridx = 0; gbc.gridy = 0;
			editPanel.add(new JLabel("Item Name:"), gbc);
			gbc.gridx = 1;
			JTextField itemNameField = new JTextField(request.itemName, 20);
			editPanel.add(itemNameField, gbc);

			gbc.gridx = 0; gbc.gridy = 1;
			editPanel.add(new JLabel("Quantity:"), gbc);
			gbc.gridx = 1;
			JTextField quantityField = new JTextField(String.valueOf(request.quantity), 10);
			editPanel.add(quantityField, gbc);

			gbc.gridx = 0; gbc.gridy = 2;
			editPanel.add(new JLabel("Duration (days):"), gbc);
			gbc.gridx = 1;
			JTextField durationField = new JTextField(String.valueOf(request.durationDays), 10);
			editPanel.add(durationField, gbc);

			gbc.gridx = 0; gbc.gridy = 3;
			editPanel.add(new JLabel("Notes:"), gbc);
			gbc.gridx = 1;
			JTextField notesField = new JTextField(request.notes != null ? request.notes : "", 20);
			editPanel.add(notesField, gbc);

			int result = JOptionPane.showConfirmDialog(
				DashboardPanel.this,
				editPanel,
				"Edit Request",
				JOptionPane.OK_CANCEL_OPTION,
				JOptionPane.PLAIN_MESSAGE
			);

			if (result == JOptionPane.OK_OPTION)
			{
				try
				{
					String newItemName = itemNameField.getText().trim();
					int newQty = Integer.parseInt(quantityField.getText().trim());
					int newDuration = Integer.parseInt(durationField.getText().trim());
					String newNotes = notesField.getText().trim();

					if (newItemName.isEmpty())
					{
						JOptionPane.showMessageDialog(DashboardPanel.this,
							"Item name cannot be empty.", "Error", JOptionPane.ERROR_MESSAGE);
						return;
					}

					// Update the request data and re-save
					String groupId = groupService.getCurrentGroupIdUnchecked();
					if (groupId != null)
					{
						// Keep the item list, or the post can no longer be matched
						// against the marketplace by item.
						StringBuilder itemsStr = new StringBuilder();
						for (LookingForItem it : request.items)
						{
							if (itemsStr.length() > 0) itemsStr.append(",");
							itemsStr.append(it.itemId).append(":").append(it.itemName.replace(":", "").replace(",", ""))
								.append(":").append(it.quantity).append(":").append(it.value);
						}
						String requestData = String.format("%s|%s|%d|%d|%s|%s",
							request.requesterName, newItemName, newQty, newDuration,
							newNotes.replace("|", "/"), itemsStr);
						saveLookingForRequest(groupId, request.id, requestData);
						refresh();
					}
				}
				catch (NumberFormatException ex)
				{
					JOptionPane.showMessageDialog(DashboardPanel.this,
						"Please enter valid numbers.", "Error", JOptionPane.ERROR_MESSAGE);
				}
			}
		}

		private void showOfferToLendDialog(String lender, LookingForRequest request)
		{
			String groupId = groupService.getCurrentGroupIdUnchecked();
			String groupName = groupId != null ? groupService.getGroupNameById(groupId) : null;

			JPanel panel = new JPanel(new GridBagLayout());
			GridBagConstraints gbc = createDefaultGbc();
			gbc.gridy = 0; gbc.gridwidth = 2;
			panel.add(new JLabel("<html><b>Offer: " + request.itemName + "</b> to " + request.requesterName +
				(groupName != null ? " <font color='#FFA500'>(" + groupName + ")</font>" : "") +
				"<br><font color='gray'>Requested: x" + request.quantity + " for " + request.durationDays + " days</font></html>"), gbc);

			gbc.gridy = 1; gbc.gridwidth = 1;
			panel.add(new JLabel("Quantity:"), gbc);
			gbc.gridx = 1;
			JTextField qtyField = new JTextField(String.valueOf(request.quantity), 5);
			panel.add(qtyField, gbc);

			gbc.gridx = 0; gbc.gridy = 2;
			panel.add(new JLabel("Duration:"), gbc);
			gbc.gridx = 1;
			JTextField durationField = new JTextField(String.valueOf(request.durationDays), 5);
			panel.add(durationField, gbc);

			gbc.gridx = 0; gbc.gridy = 3; gbc.gridwidth = 2;
			JRadioButton daysRadio = new JRadioButton("Days", true);
			JRadioButton hoursRadio = new JRadioButton("Hours");
			ButtonGroup durationGroup = new ButtonGroup();
			durationGroup.add(daysRadio);
			durationGroup.add(hoursRadio);
			JPanel radioPanel = new JPanel(new FlowLayout(FlowLayout.LEFT, 5, 0));
			radioPanel.add(daysRadio);
			radioPanel.add(hoursRadio);
			panel.add(radioPanel, gbc);

			gbc.gridy = 4;
			JCheckBox applyTerms = new JCheckBox("<html>Apply standard lending terms<br>" +
				"<font size='2' color='#b0b0b0'>\u2022 No Wilderness \u2022 No trading \u2022 Return on time</font></html>");
			applyTerms.setSelected(true);
			panel.add(applyTerms, gbc);

			gbc.gridy = 5; gbc.gridwidth = 1;
			panel.add(new JLabel("Message:"), gbc);
			gbc.gridx = 1;
			JTextField msgField = new JTextField(15);
			panel.add(msgField, gbc);

			int result = JOptionPane.showConfirmDialog(DashboardPanel.this, panel,
				"Offer Item", JOptionPane.OK_CANCEL_OPTION, JOptionPane.PLAIN_MESSAGE);

			if (result == JOptionPane.OK_OPTION)
			{
				try
				{
					int offerQty = Integer.parseInt(qtyField.getText().trim());
					int duration = Integer.parseInt(durationField.getText().trim());
					if (offerQty <= 0 || duration <= 0) throw new NumberFormatException();
					if (hoursRadio.isSelected()) duration = -duration; // Negative = hours
					String durationDisplay = duration < 0 ? Math.abs(duration) + " hours" : duration + " days";
					int durationDays = duration < 0 ? Math.max(1, Math.abs(duration) / 24) : duration;
					boolean sent = plugin.sendLendOffer(lender, request.requesterName, request.itemName, offerQty, durationDays, msgField.getText().trim(), durationDisplay);
					if (sent)
					{
						String deliveryNote = plugin.isRelaySyncConnected()
							? "They'll see it in their Lending Tracker panel."
							: "Cloud Sync is offline — it will be delivered when they next sync.";
						JOptionPane.showMessageDialog(DashboardPanel.this,
							"Offer sent to " + request.requesterName + "!\nItem: " + request.itemName + " x" + offerQty + "\nDuration: " + durationDisplay + "\n" + deliveryNote,
							"Offer Sent", JOptionPane.INFORMATION_MESSAGE);
					}
					else
					{
						JOptionPane.showMessageDialog(DashboardPanel.this,
							"Could not send the offer — no active group.",
							"Offer Not Sent", JOptionPane.ERROR_MESSAGE);
					}
				}
				catch (NumberFormatException e)
				{
					JOptionPane.showMessageDialog(DashboardPanel.this,
						"Please enter valid numbers.", "Error", JOptionPane.ERROR_MESSAGE);
				}
			}
		}
	}
}

package com.guess34.lendingtracker.ui;

import lombok.extern.slf4j.Slf4j;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;
import com.guess34.lendingtracker.LendingTrackerPlugin;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.PluginPanel;
import net.runelite.client.ui.components.materialtabs.MaterialTab;
import net.runelite.client.ui.components.materialtabs.MaterialTabGroup;

import javax.swing.*;
import javax.swing.border.EmptyBorder;
import java.awt.*;
import java.awt.image.BufferedImage;

/**
 * LendingPanel - Main UI shell with Material Design tabs.
 */
@Slf4j
public class LendingPanel extends PluginPanel
{
	private final LendingTrackerPlugin plugin;
	private final EventBus eventBus;

	// Group control panel (persistent header)
	private final GroupControlPanel groupControlPanel;

	// Connection status bar
	private JLabel connectionDot;
	private JLabel connectionLabel;

	// Display panel — reports small preferred height so child scroll panes can scroll
	private final JPanel display = new JPanel()
	{
		@Override
		public Dimension getPreferredSize()
		{
			return new Dimension(super.getPreferredSize().width, 0);
		}
	};
	private final MaterialTabGroup tabGroup;

	// Tab panels
	private DashboardPanel marketplacePanel;
	private RosterPanel rosterPanel;
	private HistoryPanel historyPanel;
	private SettingsPanel settingsPanel;

	public LendingPanel(LendingTrackerPlugin plugin, EventBus eventBus)
	{
		super(false);
		this.plugin = plugin;
		this.eventBus = eventBus;

		setLayout(new BorderLayout());
		setBackground(ColorScheme.DARK_GRAY_COLOR);

		// Create group control panel at the top
		groupControlPanel = new GroupControlPanel(plugin, eventBus);

		tabGroup = new MaterialTabGroup(display);
		tabGroup.setBorder(new EmptyBorder(5, 0, 0, 0));
		tabGroup.setBackground(ColorScheme.DARK_GRAY_COLOR);

		// Create tab panels
		marketplacePanel = new DashboardPanel(plugin);
		rosterPanel = new RosterPanel(plugin);
		historyPanel = new HistoryPanel(plugin);
		settingsPanel = new SettingsPanel(plugin);

		// Initialize tabs
		initializeTabs();

		// Connection status bar
		JPanel connectionBar = new JPanel(new FlowLayout(FlowLayout.LEFT, 4, 1));
		connectionBar.setBackground(ColorScheme.DARK_GRAY_COLOR);
		connectionDot = new JLabel("\u25CF");
		connectionDot.setForeground(ColorScheme.MEDIUM_GRAY_COLOR);
		connectionDot.setFont(connectionDot.getFont().deriveFont(8f));
		connectionLabel = new JLabel("Not connected");
		connectionLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		connectionLabel.setFont(connectionLabel.getFont().deriveFont(Font.PLAIN, 10f));
		connectionBar.add(connectionDot);
		connectionBar.add(connectionLabel);

		// Layout: Group control at top, connection bar, tabs, content in center
		JPanel topPanel = new JPanel();
		topPanel.setLayout(new BoxLayout(topPanel, BoxLayout.Y_AXIS));
		topPanel.setBackground(ColorScheme.DARK_GRAY_COLOR);
		topPanel.add(groupControlPanel);
		topPanel.add(connectionBar);
		topPanel.add(tabGroup);

		add(topPanel, BorderLayout.NORTH);
		add(display, BorderLayout.CENTER);

		// Register for group change events
		eventBus.register(this);
		registered = true;

		// Poll relay connection status until connected, then stop
		connectionPoller = new Timer(5000, null);
		connectionPoller.addActionListener(e ->
		{
			boolean connected = plugin.isRelaySyncConnected();
			updateConnectionStatus(connected);
			if (connected)
			{
				connectionPoller.stop();
			}
		});
		connectionPoller.setRepeats(true);
		connectionPoller.start();
	}

	private Timer connectionPoller;
	private boolean registered;

	/**
	 * Release everything this panel holds open. Called from the plugin's shutDown.
	 *
	 * Dropping the reference is not enough: the event bus keeps a strong reference
	 * to a registered subscriber, so the whole panel tree stays alive and keeps
	 * handling events after the plugin is disabled, and re-enabling stacks another
	 * subscriber on top. The poller has the same problem - it only stopped itself
	 * once the relay reported connected, and with Cloud Sync off by default that
	 * never happens, so it ticked on the EDT for the rest of the session.
	 */
	public void deregister()
	{
		if (registered)
		{
			eventBus.unregister(this);
			registered = false;
		}
		if (connectionPoller != null)
		{
			connectionPoller.stop();
			connectionPoller = null;
		}
	}

	/**
	 * Refresh all panels (called when data changes).
	 */
	public void refresh()
	{
		SwingUtilities.invokeLater(() ->
		{
			// Ensure data is loaded for the active group BEFORE refreshing panels
			String activeGroupId = plugin.getGroupService().getCurrentGroupIdUnchecked();
			if (activeGroupId != null)
			{
				plugin.getDataService().loadGroupData(activeGroupId);
			}

			groupControlPanel.refresh();
			marketplacePanel.refresh();
			rosterPanel.refresh();
			historyPanel.refresh();
			settingsPanel.refresh();

			// Sync connection status on every refresh so the indicator is always current
			updateConnectionStatus(plugin.isRelaySyncConnected());
		});
	}

	/**
	 * Lightweight refresh for presence-only changes (a member coming online/offline
	 * or hopping worlds). Rebuilds just the roster — not the marketplace/history
	 * panels — so an unrelated presence ping doesn't reset the user's scroll or
	 * reload data from config on the whole UI.
	 */
	public void refreshRoster()
	{
		SwingUtilities.invokeLater(() ->
		{
			rosterPanel.refresh();
			updateConnectionStatus(plugin.isRelaySyncConnected());
		});
	}

	/**
	 * Update the connection status indicator (called from relay sync callback).
	 */
	public void updateConnectionStatus(boolean connected)
	{
		SwingUtilities.invokeLater(() ->
		{
			if (connectionDot != null)
			{
				connectionDot.setForeground(connected ? new Color(0, 200, 0) : new Color(200, 60, 60));
			}
			if (connectionLabel != null)
			{
				// "Offline" is wrong while a reconnect is in flight - the relay sleeps
				// after 15 minutes idle, so a wake can take up to a minute and the
				// plugin looked broken for the whole of it.
				String text = connected ? "Synced"
					: (plugin.isRelaySyncConnecting() ? "Connecting..." : "Offline");
				connectionLabel.setText(text);
				connectionLabel.setForeground(connected
					? new Color(0, 200, 0) : ColorScheme.LIGHT_GRAY_COLOR);
			}
		});
	}

	@Subscribe
	public void onGroupChangedEvent(GroupControlPanel.GroupChangedEvent event)
	{
		// Load data for the newly selected group
		if (event.getGroupId() != null) {
			plugin.getDataService().loadGroupData(event.getGroupId());

			// Restart sync for the newly selected group
			String playerName = plugin.getCurrentPlayerName();
			if (playerName != null) {
				plugin.getGroupService().startSync(event.getGroupId(), playerName);
			}
		}

		refresh();
	}

	/**
	 * Initialize tabs with drawn icon-based MaterialTabs.
	 */
	private void initializeTabs()
	{
		ImageIcon shopIcon = createShopIcon(ColorScheme.BRAND_ORANGE);
		ImageIcon teamIcon = createPeopleIcon(new Color(100, 149, 237));
		ImageIcon logIcon = createClockIcon(new Color(0, 170, 0));
		ImageIcon cfgIcon = createGearIcon(ColorScheme.MEDIUM_GRAY_COLOR);

		MaterialTab marketplaceTab = new MaterialTab(shopIcon, tabGroup, marketplacePanel);
		MaterialTab rosterTab = new MaterialTab(teamIcon, tabGroup, rosterPanel);
		MaterialTab historyTab = new MaterialTab(logIcon, tabGroup, historyPanel);
		MaterialTab settingsTab = new MaterialTab(cfgIcon, tabGroup, settingsPanel);

		marketplaceTab.setToolTipText("Marketplace");
		rosterTab.setToolTipText("Group Roster");
		historyTab.setToolTipText("History & Notifications");
		settingsTab.setToolTipText("Settings");

		tabGroup.addTab(marketplaceTab);
		tabGroup.addTab(rosterTab);
		tabGroup.addTab(historyTab);
		tabGroup.addTab(settingsTab);

		tabGroup.select(marketplaceTab);
	}

	private static Graphics2D createIconGraphics(BufferedImage img)
	{
		Graphics2D g = img.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setRenderingHint(RenderingHints.KEY_STROKE_CONTROL, RenderingHints.VALUE_STROKE_PURE);
		return g;
	}

	private static ImageIcon createShopIcon(Color color)
	{
		int size = 20;
		BufferedImage img = new BufferedImage(size, size, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = createIconGraphics(img);
		g.setColor(color);
		g.setStroke(new BasicStroke(1.8f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));

		// Bag body
		g.drawRoundRect(4, 7, 12, 10, 2, 2);
		// Handle (arc on top)
		g.drawArc(6, 2, 8, 10, 0, 180);

		g.dispose();
		return new ImageIcon(img);
	}

	private static ImageIcon createPeopleIcon(Color color)
	{
		int size = 20;
		BufferedImage img = new BufferedImage(size, size, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = createIconGraphics(img);
		g.setColor(color);

		// Front person - head
		g.fillOval(7, 2, 6, 6);
		// Front person - body
		g.fillArc(5, 9, 10, 10, 0, 180);

		// Back person (offset left, slightly behind) - head
		g.fillOval(2, 4, 5, 5);
		// Back person - body
		g.fillArc(0, 10, 9, 9, 0, 180);

		g.dispose();
		return new ImageIcon(img);
	}

	private static ImageIcon createClockIcon(Color color)
	{
		int size = 20;
		BufferedImage img = new BufferedImage(size, size, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = createIconGraphics(img);
		g.setColor(color);
		g.setStroke(new BasicStroke(1.8f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));

		// Clock face
		g.drawOval(2, 2, 16, 16);
		// Hour hand (pointing to 10 o'clock)
		g.drawLine(10, 10, 7, 5);
		// Minute hand (pointing to 2 o'clock)
		g.drawLine(10, 10, 14, 7);
		// Center dot
		g.fillOval(9, 9, 3, 3);

		g.dispose();
		return new ImageIcon(img);
	}

	private static ImageIcon createGearIcon(Color color)
	{
		int size = 20;
		BufferedImage img = new BufferedImage(size, size, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = createIconGraphics(img);
		g.setColor(color);

		int cx = 10, cy = 10;
		int outerR = 8, innerR = 5;
		int teeth = 8;

		// Build gear shape as polygon
		int points = teeth * 2;
		int[] xPoints = new int[points];
		int[] yPoints = new int[points];
		for (int i = 0; i < points; i++)
		{
			double angle = Math.PI * 2 * i / points - Math.PI / 2;
			int r = (i % 2 == 0) ? outerR : innerR;
			xPoints[i] = cx + (int) Math.round(r * Math.cos(angle));
			yPoints[i] = cy + (int) Math.round(r * Math.sin(angle));
		}
		g.fillPolygon(xPoints, yPoints, points);

		// Center hole
		g.setColor(new Color(0, 0, 0, 0));
		g.setComposite(AlphaComposite.Clear);
		g.fillOval(cx - 3, cy - 3, 6, 6);

		g.dispose();
		return new ImageIcon(img);
	}

	// Panel lifecycle (creation, disposal) is managed by RuneLite via NavigationButton.
}

