	private void generateInviteCode()
	{
		LendingGroup g = groupService.getActiveGroup();
		if (g == null) return;
		String user = getCurrentUsername();
		if (!groupService.canGenerateInviteCode(g.getId(), user))
		{
			JOptionPane.showMessageDialog(this, "You don't have permission to generate invite codes.",
				"Permission Denied", JOptionPane.WARNING_MESSAGE);
			return;
		}
		final String groupId = g.getId();
		// Publishing to the relay is a blocking network call (with cold-start retries), so run it
		// off the EDT and only present the code once we know whether it actually reached the server.
		generateCodeButton.setEnabled(false);
		final String origText = generateCodeButton.getText();
		generateCodeButton.setText("Publishing...");

		new SwingWorker<GroupService.InviteCodeResult, Void>()
		{
			@Override
			protected GroupService.InviteCodeResult doInBackground()
			{
				return groupService.generateAndPublishInviteCode(groupId);
			}

			@Override
			protected void done()
			{
				generateCodeButton.setText(origText);
				generateCodeButton.setEnabled(true);

				GroupService.InviteCodeResult r;
				try
				{
					r = get();
				}
				catch (Exception e)
				{
					log.error("Failed to generate invite code", e);
					JOptionPane.showMessageDialog(SettingsPanel.this,
						"Failed to generate code: " + e.getMessage(), "Error", JOptionPane.ERROR_MESSAGE);
					return;
				}

				if (r == null || r.code == null)
				{
					return;
				}

				inviteCodeLabel.setText(r.code);
				inviteCodeLabel.setForeground(ColorScheme.BRAND_ORANGE);
				copyCodeButton.setEnabled(true);
				inviteCodeStatusLabel.setText("Active — expires in ~24h");
				inviteCodeStatusLabel.setForeground(new Color(0, 200, 0));

				if (!r.syncEnabled)
				{
					JOptionPane.showMessageDialog(SettingsPanel.this,
						"Code generated, but Cloud Sync is OFF.\n\n"
							+ "This code only works for players on THIS computer. Turn on Settings -> Sync ->\n"
							+ "Enable Cloud Sync (the joining player needs it on too), then generate a fresh code.",
						"Cloud Sync Disabled", JOptionPane.WARNING_MESSAGE);
				}
				else if (!r.publishedToRelay)
				{
					JOptionPane.showMessageDialog(SettingsPanel.this,
						"Code generated, but it could NOT be published to the sync server (it may still be\n"
							+ "waking up). DON'T share this code yet - wait ~30 seconds and click Generate again\n"
							+ "to get a code that works across computers.",
						"Not Published Yet", JOptionPane.WARNING_MESSAGE);
				}
				// Published OK -> the code is live on the relay and safe to share.
			}
		}.execute();
	}

	private void copyInviteCode()
	{
		String code = inviteCodeLabel.getText();
		if (code != null && !code.equals("No active code"))
		{
			Toolkit.getDefaultToolkit().getSystemClipboard().setContents(new StringSelection(code), null);
			JOptionPane.showMessageDialog(this, "Invite code copied!", "Copied", JOptionPane.INFORMATION_MESSAGE);
		}
	}

	private void transferOwnership()
	{
		LendingGroup g = groupService.getActiveGroup();
		if (g == null) return;
		String user = getCurrentUsername();
		if (!groupService.isOwner(g.getId(), user))
		{
			JOptionPane.showMessageDialog(this, "Only the owner can transfer ownership!",
				"Permission Denied", JOptionPane.ERROR_MESSAGE);
			return;
		}
		String target = (String) transferOwnerDropdown.getSelectedItem();
		if (target == null || target.isEmpty() || target.equals("Select member..."))
		{
			JOptionPane.showMessageDialog(this, "Select a member first.",
				"No Selection", JOptionPane.WARNING_MESSAGE);
			return;
		}
		int confirm = JOptionPane.showConfirmDialog(this,
			String.format("Transfer ownership of '%s' to %s?\nYou will become Co-Owner. This cannot be easily undone!",
				g.getName(), target),
			"Confirm Transfer", JOptionPane.YES_NO_OPTION, JOptionPane.WARNING_MESSAGE);
		if (confirm != JOptionPane.YES_OPTION) return;

		try
		{
			if (groupService.transferOwnership(g.getId(), user, target))
			{
				JOptionPane.showMessageDialog(this,
					"Ownership transferred to " + target + "!\nYou are now Co-Owner.",
					"Transfer Complete", JOptionPane.INFORMATION_MESSAGE);
				plugin.refreshPanel();
			}
			else
			{
				JOptionPane.showMessageDialog(this, "Transfer failed.", "Error", JOptionPane.ERROR_MESSAGE);
			}
		}
		catch (Exception e)
		{
			log.error("Failed to transfer ownership", e);
			JOptionPane.showMessageDialog(this, "Transfer failed: " + e.getMessage(),
				"Error", JOptionPane.ERROR_MESSAGE);
		}
	}

	private void transferFounder()
