	public void refresh()
	{
		SwingUtilities.invokeLater(() ->
		{
			boolean isLoggedIn = false;
			try
			{
				if (plugin.getClient() != null && plugin.getClient().getLocalPlayer() != null)
				{
					String playerName = plugin.getClient().getLocalPlayer().getName();
					if (playerName != null && !playerName.isEmpty())
					{
						isLoggedIn = true;
					}
				}
			}
			catch (Exception e)
			{
				log.debug("Could not check login status", e);
			}

			if (!isLoggedIn)
			{
				headerLabel.setText("Group Roster");
				showMessage("<html><center><b style='color: #ff9900;'>Not Logged In</b><br><br>Please log in to your<br>OSRS account to see<br>group members.</center></html>");
				return;
			}

			LendingGroup activeGroup = groupService.getActiveGroup();
			if (activeGroup == null)
			{
				headerLabel.setText("No Group Selected");
				showMessage("<html><center><b>No Active Group</b><br><br>Create or join a group<br>to see group members</center></html>");
				return;
			}

			// Update header with group name
			headerLabel.setText(activeGroup.getName() + " Roster");

			// Get online players for status checking (maps lowercase name -> world number)
			Map<String, Integer> onlinePlayers = getOnlinePlayers();

			// Get group members
			List<GroupMember> members = activeGroup.getMembers();

			// Clear and rebuild member list
			memberListPanel.removeAll();
			allMemberRows.clear();

			if (members == null || members.isEmpty())
			{
				showMessage("<html><center>No members in this group<br><br>Invite members using<br>the Settings tab</center></html>");
			}
			else
			{
				// Sort members: online first, then by role rank, then alphabetically
				List<GroupMember> sortedMembers = new ArrayList<>(members);
				sortedMembers.sort((a, b) -> {
					boolean aOnline = onlinePlayers.containsKey(a.getName().toLowerCase());
					boolean bOnline = onlinePlayers.containsKey(b.getName().toLowerCase());

					if (aOnline != bOnline) return aOnline ? -1 : 1;

					int aRank = GroupService.getRoleRank(a.getRole());
					int bRank = GroupService.getRoleRank(b.getRole());
					if (aRank != bRank) return bRank - aRank;

					return a.getName().compareToIgnoreCase(b.getName());
				});

				for (GroupMember member : sortedMembers)
				{
					boolean isOnline = onlinePlayers.containsKey(member.getName().toLowerCase());
					Integer worldVal = onlinePlayers.get(member.getName().toLowerCase());
					int world = worldVal != null ? worldVal : 0;
					JPanel memberRow = createMemberRow(member, isOnline, world);
					allMemberRows.add(memberRow);
					memberListPanel.add(memberRow);
					memberListPanel.add(Box.createVerticalStrut(2));
				}
			}

			memberListPanel.revalidate();
			memberListPanel.repaint();
		});
	}

	private JPanel createMemberRow(GroupMember member, boolean isOnline, int world)
	{
		JPanel row = new JPanel(new BorderLayout(8, 0));
		row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		row.setBorder(new EmptyBorder(8, 10, 8, 10));
		row.setMaximumSize(new Dimension(Integer.MAX_VALUE, 45));

		// Left: Online indicator + Name + Status
		JPanel leftPanel = new JPanel(new FlowLayout(FlowLayout.LEFT, 5, 0));
		leftPanel.setBackground(ColorScheme.DARKER_GRAY_COLOR);

		// Online/Offline indicator (colored dot)
		JLabel statusDot = new JLabel("\u2022"); // Bullet character
		statusDot.setFont(new Font("Arial", Font.BOLD, 20));
		statusDot.setForeground(isOnline ? new Color(0, 200, 83) : new Color(150, 150, 150));

		// Get world number for online players from friends list
		String statusTooltip = "Offline";
		String worldText = "";
		if (isOnline)
		{
			if (world > 0)
			{
				worldText = " (W" + world + ")";
				statusTooltip = "Online - World " + world;
			}
			else
			{
				statusTooltip = "Online";
			}
		}
		statusDot.setToolTipText(statusTooltip);
		leftPanel.add(statusDot);

		// Player name with world if online
		JLabel nameLabel = new JLabel(member.getName() + worldText);
		nameLabel.setFont(FontManager.getRunescapeSmallFont());
		nameLabel.setForeground(isOnline ? Color.WHITE : ColorScheme.LIGHT_GRAY_COLOR);
		leftPanel.add(nameLabel);

		row.add(leftPanel, BorderLayout.WEST);

		// Right: Role badge
		String role = member.getRole() != null ? member.getRole() : "member";
		JLabel roleLabel = new JLabel(GroupService.formatRoleName(role));
		roleLabel.setFont(FontManager.getRunescapeSmallFont());
		roleLabel.setOpaque(true);
		roleLabel.setBorder(new EmptyBorder(2, 6, 2, 6));
		roleLabel.setBackground(GroupService.getRoleBackgroundColor(role));
		roleLabel.setForeground(GroupService.getRoleForegroundColor(role));

		row.add(roleLabel, BorderLayout.EAST);

		// Store the member name for filtering
		row.putClientProperty("memberName", member.getName().toLowerCase());

		// Right-click context menu
		row.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mousePressed(MouseEvent e)
			{
				maybeShowPopup(e);
			}

			@Override
			public void mouseReleased(MouseEvent e)
			{
				maybeShowPopup(e);
			}

			private void maybeShowPopup(MouseEvent e)
			{
				if (e.isPopupTrigger())
				{
					showMemberPopup(e.getComponent(), e.getX(), e.getY(), member, isOnline, world);
				}
			}
		});

		return row;
	}

	private Map<String, Integer> getOnlinePlayers()
	{
		Map<String, Integer> online = new HashMap<>();

		try
		{
			// Check Friends Chat members (world not available from FriendsChatMember)
			FriendsChatManager fcManager = plugin.getClient().getFriendsChatManager();
			if (fcManager != null)
			{
				FriendsChatMember[] fcMembers = fcManager.getMembers();
				if (fcMembers != null)
				{
					for (FriendsChatMember m : fcMembers)
					{
						if (m != null && m.getName() != null)
						{
							online.putIfAbsent(m.getName().toLowerCase(), 0);
						}
					}
				}
			}

			// Check friends list for online status (includes world number).
			// Container can be null early in login — an NPE here would abort the
			// whole method and lose the self-row and presence merge below.
			var friendContainer = plugin.getClient().getFriendContainer();
			Friend[] friends = friendContainer != null ? friendContainer.getMembers() : null;
			if (friends != null)
			{
				for (Friend f : friends)
				{
					if (f != null && f.getName() != null && f.getWorld() > 0)
					{
						online.put(f.getName().toLowerCase(), f.getWorld());
					}
				}
			}

			// Current player is always "online" on their current world.
			String localNameLower = null;
			if (plugin.getClient().getLocalPlayer() != null)
			{
				String localName = plugin.getClient().getLocalPlayer().getName();
				if (localName != null)
				{
					localNameLower = localName.toLowerCase();
					int currentWorld = plugin.getClient().getWorld();
					online.put(localNameLower, currentWorld);
				}
			}

			// Relay-authoritative presence: anyone with an open sync connection to the
			// group room is online, regardless of friends chat / friends list. The
			// relay reports their world too when it knows it. This is the primary
			// online signal — the friends-list pass above just enriches worlds.
			for (Map.Entry<String, Integer> e : groupService.getOnlineMembers().entrySet())
			{
				// Never override the local player's own row — the world we just read
				// from the client is fresher than the one captured at our last join.
				if (e.getKey().equals(localNameLower))
				{
					continue;
				}
				Integer w = e.getValue();
				if (w != null && w > 0)
				{
					online.put(e.getKey(), w);          // real world from presence
				}
				else
				{
					online.putIfAbsent(e.getKey(), 0);  // online, world unknown -> "Online"
				}
			}
		}
		catch (Exception e)
		{
			log.debug("Error getting online players", e);
		}

		return online;
	}

	private void showMemberPopup(Component component, int x, int y, GroupMember member, boolean isOnline, int world)
	{
		JPopupMenu popup = new JPopupMenu();

		// "View Activity" lived here. It only ever opened a dialog telling you to
		// open a "Log tab" that does not exist (the tab is History), and it could not
		// have worked anyway: HistoryPanel shows only the local player's own history,
		// has no per-player filter, and other members' completed loans are never
		// transmitted - only bare tombstone ids are. Removed rather than left as a
		// dead end. Reinstating it needs completed loans to actually sync.

		// Show world info for online players (informational, not actionable)
		if (isOnline && world > 0)
		{
			JMenuItem worldInfo = new JMenuItem("World " + world);
			worldInfo.setEnabled(false);
			popup.add(worldInfo);
		}

		// With View Activity gone the only entry is the world label, which appears
		// for online members only - showing an empty popup on right-click would look
		// broken, so suppress it.
		if (popup.getComponentCount() == 0) return;
		popup.show(component, x, y);
	}

	private void filterMembers(String query)
	{
		String lowerQuery = query.toLowerCase().trim();

		for (JPanel row : allMemberRows)
		{
			String memberName = (String) row.getClientProperty("memberName");
			boolean matches = lowerQuery.isEmpty() ||
				(memberName != null && memberName.contains(lowerQuery));
			row.setVisible(matches);
		}

		memberListPanel.revalidate();
		memberListPanel.repaint();
	}

	private void clearSearch()
	{
		searchBar.setText("");
		filterMembers("");
	}

	private void showMessage(String html)
	{
		memberListPanel.removeAll();
		allMemberRows.clear();

		JPanel panel = new JPanel(new BorderLayout());
		panel.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		panel.setBorder(new EmptyBorder(40, 20, 40, 20));

		JLabel label = new JLabel(html);
		label.setFont(FontManager.getRunescapeFont());
		label.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		label.setHorizontalAlignment(SwingConstants.CENTER);

		panel.add(label, BorderLayout.CENTER);
		memberListPanel.add(panel);

		memberListPanel.revalidate();
		memberListPanel.repaint();
	}
}

package com.guess34.lendingtracker.ui;

import lombok.extern.slf4j.Slf4j;
import net.runelite.client.eventbus.EventBus;
import com.guess34.lendingtracker.LendingTrackerPlugin;
import com.guess34.lendingtracker.model.LendingGroup;
import com.guess34.lendingtracker.services.GroupService;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

import javax.swing.*;
import javax.swing.border.EmptyBorder;
import java.awt.*;
import java.util.Collection;

/**
 * Persistent navigation header showing account info, group dropdown, and Create/Join buttons.
 */
@Slf4j
public class GroupControlPanel extends JPanel
{
	private final LendingTrackerPlugin plugin;
	private final GroupService groupService;
	private final EventBus eventBus;
	private final JLabel accountLabel;
	private final JComboBox<GroupItem> groupDropdown;
	private final JButton createGroupButton;
	private final JButton joinGroupButton;
	private boolean isUpdating = false;
	private volatile String cachedAccountName = null;

	public GroupControlPanel(LendingTrackerPlugin plugin, EventBus eventBus)
	{
		this.plugin = plugin;
		this.groupService = plugin.getGroupService();
		this.eventBus = eventBus;

		setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
		setBackground(ColorScheme.DARKER_GRAY_COLOR);
		setBorder(new EmptyBorder(8, 10, 8, 10));

		accountLabel = new JLabel("Not logged in");
		accountLabel.setFont(FontManager.getRunescapeSmallFont());
		accountLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		accountLabel.setMaximumSize(new Dimension(Integer.MAX_VALUE, 16));
		accountLabel.setAlignmentX(Component.LEFT_ALIGNMENT);
		add(accountLabel);
		add(Box.createVerticalStrut(4));

		JPanel groupRow = new JPanel(new BorderLayout(5, 0));
		groupRow.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		groupRow.setMaximumSize(new Dimension(Integer.MAX_VALUE, 28));
		JLabel groupLabel = new JLabel("Group:");
		groupLabel.setFont(FontManager.getRunescapeSmallFont());
		groupLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		groupLabel.setPreferredSize(new Dimension(55, 25));
		groupRow.add(groupLabel, BorderLayout.WEST);

		groupDropdown = new JComboBox<>();
		groupDropdown.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		groupDropdown.setForeground(Color.WHITE);
		groupDropdown.setFont(FontManager.getRunescapeSmallFont());
		groupDropdown.setFocusable(false);
		groupDropdown.setRenderer(new GroupItemRenderer());
		groupDropdown.addActionListener(e -> onGroupChanged());
		groupRow.add(groupDropdown, BorderLayout.CENTER);
		add(groupRow);
		add(Box.createVerticalStrut(8));

		JPanel buttonRow = new JPanel(new GridLayout(1, 2, 10, 0));
		buttonRow.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		buttonRow.setMaximumSize(new Dimension(Integer.MAX_VALUE, 30));
		createGroupButton = makeButton("Create", ColorScheme.BRAND_ORANGE, "Create a new group");
		createGroupButton.addActionListener(e -> showCreateGroupDialog());
		buttonRow.add(createGroupButton);
		joinGroupButton = makeButton("Join", ColorScheme.GRAND_EXCHANGE_PRICE, "Join an existing group");
		joinGroupButton.addActionListener(e -> showJoinGroupDialog());
		buttonRow.add(joinGroupButton);
		add(buttonRow);

		refresh();
	}

	public void refresh()
	{
		SwingUtilities.invokeLater(() ->
		{
			isUpdating = true;
			try
			{
				String currentAccount = getCurrentAccount();
				boolean loggedIn = currentAccount != null
					&& !currentAccount.equals("Not logged in")
					&& !currentAccount.equals("Loading...");

				accountLabel.setText(loggedIn ? ("\u2022 " + currentAccount) : "Not logged in");
				accountLabel.setForeground(loggedIn ? new Color(0, 200, 83) : ColorScheme.LIGHT_GRAY_COLOR);
				groupDropdown.removeAllItems();
				groupDropdown.setEnabled(loggedIn);
				createGroupButton.setEnabled(loggedIn);
				joinGroupButton.setEnabled(loggedIn);

				if (!loggedIn)
				{
					Collection<LendingGroup> groups = groupService.getAllGroups();
					if (groups.isEmpty())
					{
						groupDropdown.addItem(new GroupItem(null, "Log in to see groups"));
					}
					else
					{
						addGroupItems(groups);
						selectGroupById(groupService.getCurrentGroupIdUnchecked());
					}
				}
				else
				{
					Collection<LendingGroup> groups = groupService.getAllGroups();
					if (groups.isEmpty() && !groupService.hasCurrentAccount())
					{
						log.warn("No groups and no current account - triggering onAccountLogin for: {}", currentAccount);
						groupService.onAccountLogin(currentAccount);
						groups = groupService.getAllGroups();
					}
					if (groups.isEmpty())
					{
						groupDropdown.addItem(new GroupItem(null, "No groups - Create one!"));
					}
					else
					{
						addGroupItems(groups);
						LendingGroup active = groupService.getActiveGroupUnchecked();
						if (active != null)
						{
							selectGroupById(active.getId());
						}
					}
				}
			}
			finally
			{
				isUpdating = false;
			}
		});
	}

	public void setCurrentAccount(String accountName)
	{
		this.cachedAccountName = accountName;
	}

	public void clearCurrentAccount()
	{
		this.cachedAccountName = null;
	}

	private void addGroupItems(Collection<LendingGroup> groups)
	{
		for (LendingGroup g : groups)
		{
			groupDropdown.addItem(new GroupItem(g.getId(), g.getName()));
		}
	}

	private void selectGroupById(String targetId)
	{
		if (targetId == null) return;
		for (int i = 0; i < groupDropdown.getItemCount(); i++)
		{
			if (targetId.equals(groupDropdown.getItemAt(i).groupId))
			{
				groupDropdown.setSelectedIndex(i);
				return;
			}
		}
	}

	private String getCurrentAccount()
	{
		if (cachedAccountName != null && !cachedAccountName.isEmpty())
		{
			return cachedAccountName;
		}
		try
		{
			if (plugin.getClient() != null)
			{
				net.runelite.api.GameState gs = plugin.getClient().getGameState();
				if (gs == net.runelite.api.GameState.LOGGED_IN)
				{
					net.runelite.api.Player lp = plugin.getClient().getLocalPlayer();
					if (lp != null && lp.getName() != null && !lp.getName().isEmpty())
					{
						cachedAccountName = lp.getName();
						return cachedAccountName;
					}
					return "Loading...";
				}
			}
			if (plugin.getConfigManager() != null)
			{
				String stored = plugin.getConfigManager().getConfiguration("lendingtracker", "currentAccount");
				if (stored != null && !stored.isEmpty()) return stored;
			}
		}
		catch (Exception e)
		{
			log.debug("Could not get current account", e);
		}
		return "Not logged in";
	}

	private void onGroupChanged()
	{
		if (isUpdating) return;
		GroupItem selected = (GroupItem) groupDropdown.getSelectedItem();
		if (selected != null && selected.groupId != null)
		{
			groupService.setCurrentGroupId(selected.groupId);
			eventBus.post(new GroupChangedEvent(selected.groupId));
		}
	}

	private void showCreateGroupDialog()
	{
		String name = JOptionPane.showInputDialog(this, "Enter group name:", "Create Group",
			JOptionPane.PLAIN_MESSAGE);
		if (name == null || name.trim().isEmpty()) return;

		try
		{
			String groupId = groupService.createGroup(name.trim(),
				"Created via Lending Tracker", getCurrentAccount());
			if (groupId == null)
			{
				showError("A group with that name already exists!");
				return;
			}
			refresh();
			eventBus.post(new GroupChangedEvent(groupId));
			JOptionPane.showMessageDialog(this,
				String.format("Group '%s' created! You are now the owner.\n\n"
					+ "Invite members from group settings or right-click CC members.", name.trim()),
				"Group Created", JOptionPane.INFORMATION_MESSAGE);
		}
		catch (Exception e)
		{
			log.error("Failed to create group", e);
			showError("Failed to create group: " + e.getMessage());
		}
	}

	private void showJoinGroupDialog()
	{
		String playerName = getCurrentAccount();
		if (playerName == null || playerName.equals("Not logged in"))
		{
			JOptionPane.showMessageDialog(this, "You must be logged in to join a group.",
				"Not Logged In", JOptionPane.WARNING_MESSAGE);
			return;
		}

		String[] opts = {"Switch to Group", "Use Invite Code", "Cancel"};
		int choice = JOptionPane.showOptionDialog(this,
			"Switch to Group: enter name of group you're already in\n"
				+ "Use Invite Code: enter code to join a new group",
			"Join Group", JOptionPane.DEFAULT_OPTION, JOptionPane.QUESTION_MESSAGE,
			null, opts, opts[0]);

		if (choice == 0) handleSwitchToGroup(playerName);
		else if (choice == 1) handleJoinWithCode(playerName);
	}

	private void handleSwitchToGroup(String playerName)
	{
		String name = JOptionPane.showInputDialog(this,
			"Enter exact group name (case-sensitive):", "Switch to Group", JOptionPane.PLAIN_MESSAGE);
		if (name == null || name.trim().isEmpty()) return;

		try
		{
			String result = groupService.switchToGroup(name.trim(), playerName);
			switch (result)
			{
				case "success":
					refresh();
					eventBus.post(new GroupChangedEvent(groupService.getCurrentGroupId()));
					JOptionPane.showMessageDialog(this,
						String.format("Switched to group '%s'!", name.trim()),
						"Success", JOptionPane.INFORMATION_MESSAGE);
					break;
				case "not_member":
					showError("You are not a member of '" + name.trim()
						+ "'. You need an invite code from a group admin.");
					break;
				case "not_found":
					showError("Group '" + name.trim() + "' not found. Names are case-sensitive.");
					break;
			}
		}
		catch (Exception e)
		{
			log.error("Failed to switch group", e);
			showError("Failed to switch group: " + e.getMessage());
		}
	}

	private void handleJoinWithCode(String playerName)
	{
		String input = JOptionPane.showInputDialog(this,
			"Enter invite code:", "Join with Invite Code", JOptionPane.PLAIN_MESSAGE);
		if (input == null || input.trim().isEmpty()) return;

		final String code = input.trim();

		// The relay lookup is a blocking network call that can take up to a minute while a
		// spun-down Render server cold-starts. Run it off the EDT so the client doesn't freeze,
		// and give the button some "working" feedback in the meantime.
		joinGroupButton.setEnabled(false);
		final String originalText = joinGroupButton.getText();
		joinGroupButton.setText("Joining...");

		new SwingWorker<GroupService.JoinResult, Void>()
		{
			@Override
			protected GroupService.JoinResult doInBackground()
			{
				return groupService.useInviteCode(code, playerName);
			}

			@Override
			protected void done()
			{
				joinGroupButton.setText(originalText);
				joinGroupButton.setEnabled(true);

				GroupService.JoinResult result;
				try
				{
					result = get();
				}
				catch (Exception e)
				{
					log.error("Failed to join with invite code", e);
					showError("Failed to join group: " + e.getMessage());
					return;
				}

				switch (result.status)
				{
					case JOINED:
						refresh();
						eventBus.post(new GroupChangedEvent(result.groupId));
						JOptionPane.showMessageDialog(GroupControlPanel.this,
							String.format("Successfully joined group '%s'!",
								groupService.getGroupNameById(result.groupId)),
							"Joined Group", JOptionPane.INFORMATION_MESSAGE);
						break;
					case SERVER_UNREACHABLE:
						showError("Couldn't reach the sync server - it may be waking up "
							+ "(this can take 30-60s on first use). Please try the code again in a moment.");
						break;
					case SYNC_DISABLED:
						showError("Cloud Sync is off, so invite codes from other computers can't be checked.\n"
							+ "Enable it in Settings -> Sync -> Enable Cloud Sync, then try the code again.");
						break;
					case INVALID_CODE:
					default:
						showError("Invalid or expired invite code. Ask a group admin for a new one.");
						break;
				}
			}
		}.execute();
	}

	private void showError(String message)
	{
		JOptionPane.showMessageDialog(this, message, "Error", JOptionPane.ERROR_MESSAGE);
	}

	private static JButton makeButton(String text, Color bg, String tooltip)
	{
		JButton btn = new JButton(text);
		btn.setFont(FontManager.getRunescapeSmallFont());
		btn.setBackground(bg);
		btn.setForeground(Color.WHITE);
		btn.setFocusPainted(false);
		btn.setBorderPainted(false);
		btn.setToolTipText(tooltip);
		return btn;
	}

	private static class GroupItem
	{
		final String groupId;
		final String groupName;

		GroupItem(String groupId, String groupName)
		{
			this.groupId = groupId;
			this.groupName = groupName;
		}

		@Override
		public String toString() { return groupName; }
	}

	private static class GroupItemRenderer extends DefaultListCellRenderer
	{
		@Override
		public Component getListCellRendererComponent(JList<?> list, Object value,
			int index, boolean isSelected, boolean cellHasFocus)
		{
			super.getListCellRendererComponent(list, value, index, isSelected, cellHasFocus);
			setFont(FontManager.getRunescapeSmallFont());
			setForeground(Color.WHITE);
			setBackground(isSelected ? ColorScheme.BRAND_ORANGE : ColorScheme.DARKER_GRAY_COLOR);
			return this;
		}
	}

	public static class GroupChangedEvent
	{
		private final String groupId;

		public GroupChangedEvent(String groupId) { this.groupId = groupId; }

		public String getGroupId() { return groupId; }
	}
}

package com.guess34.lendingtracker.ui;

import lombok.extern.slf4j.Slf4j;
import net.runelite.client.game.ItemManager;
import com.guess34.lendingtracker.LendingTrackerPlugin;
import com.guess34.lendingtracker.model.LendingEntry;
import com.guess34.lendingtracker.services.DataService;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

import javax.swing.*;
import javax.swing.border.EmptyBorder;
import java.awt.*;
import java.util.List;

/**
 * HistoryPanel - Transaction history log for completed lending transactions
 * CHANGED: Removed notifications view (NotificationService deleted). History is now the sole view.
 */
@Slf4j
public class HistoryPanel extends JPanel
{
	private final LendingTrackerPlugin plugin;
	private final DataService dataService;
	private final ItemManager itemManager;

	private final JLabel totalHistoryLabel;
	private final JPanel historyListPanel;

	public HistoryPanel(LendingTrackerPlugin plugin)
	{
		this.plugin = plugin;
		this.dataService = plugin.getDataService();
		this.itemManager = plugin.getItemManager();

		setLayout(new BorderLayout());
		setBackground(ColorScheme.DARK_GRAY_COLOR);

		// === HISTORY HEADER ===
		JPanel historyHeader = new JPanel(new BorderLayout());
		historyHeader.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		historyHeader.setBorder(new EmptyBorder(10, 10, 10, 10));

		totalHistoryLabel = new JLabel("Total History: 0 entries");
		totalHistoryLabel.setFont(FontManager.getRunescapeBoldFont());
		totalHistoryLabel.setForeground(Color.WHITE);
		totalHistoryLabel.setHorizontalAlignment(SwingConstants.CENTER);
		historyHeader.add(totalHistoryLabel, BorderLayout.CENTER);

		add(historyHeader, BorderLayout.NORTH);

		// === HISTORY LIST ===
		historyListPanel = new JPanel();
		historyListPanel.setLayout(new BoxLayout(historyListPanel, BoxLayout.Y_AXIS));
		historyListPanel.setBackground(ColorScheme.DARK_GRAY_COLOR);

		JScrollPane historyScrollPane = new JScrollPane(historyListPanel);
		historyScrollPane.setBackground(ColorScheme.DARK_GRAY_COLOR);
		historyScrollPane.setBorder(new EmptyBorder(5, 5, 5, 5));
		historyScrollPane.setHorizontalScrollBarPolicy(ScrollPaneConstants.HORIZONTAL_SCROLLBAR_NEVER);
		historyScrollPane.setVerticalScrollBarPolicy(ScrollPaneConstants.VERTICAL_SCROLLBAR_AS_NEEDED);

		add(historyScrollPane, BorderLayout.CENTER);

		// Footer with clear old entries button
		add(createFooter(), BorderLayout.SOUTH);
	}

	/**
	 * Create footer with controls
	 */
	private JPanel createFooter()
	{
		JPanel footer = new JPanel(new FlowLayout(FlowLayout.CENTER));
		footer.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		footer.setBorder(new EmptyBorder(10, 10, 10, 10));

		JButton clearOldButton = new JButton("Clear Old Entries");
		clearOldButton.setBackground(ColorScheme.MEDIUM_GRAY_COLOR);
		clearOldButton.setForeground(Color.WHITE);
		clearOldButton.setFocusPainted(false);
		clearOldButton.addActionListener(e -> clearOldEntries());

		footer.add(clearOldButton);

		return footer;
	}

	/**
	 * Refresh the history with latest data
	 */
	public void refresh()
	{
		SwingUtilities.invokeLater(() ->
		{
			// Check login status first
			boolean isLoggedIn = false;
			try
			{
				if (plugin.getClient() != null && plugin.getClient().getLocalPlayer() != null)
				{
					String currentPlayer = plugin.getClient().getLocalPlayer().getName();
					if (currentPlayer != null && !currentPlayer.isEmpty())
					{
						isLoggedIn = true;
					}
				}
			}
			catch (Exception e)
			{
				log.debug("Could not check login status", e);
			}

			// Clear and rebuild history cards
			historyListPanel.removeAll();

			// If not logged in, show login message
			if (!isLoggedIn)
			{
				totalHistoryLabel.setText("Total History: 0 entries");

				JPanel emptyPanel = new JPanel(new BorderLayout());
				emptyPanel.setBackground(ColorScheme.DARKER_GRAY_COLOR);
				emptyPanel.setBorder(new EmptyBorder(40, 20, 40, 20));

				JLabel emptyLabel = new JLabel("<html><center><b style='color: #ff9900;'>Not Logged In</b><br><br>Please log in to your<br>OSRS account to view<br>transaction history.</center></html>");
				emptyLabel.setFont(FontManager.getRunescapeFont());
				emptyLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
				emptyLabel.setHorizontalAlignment(SwingConstants.CENTER);

				emptyPanel.add(emptyLabel, BorderLayout.CENTER);
				historyListPanel.add(emptyPanel);

				historyListPanel.revalidate();
				historyListPanel.repaint();
				return;
			}

			// Get history entries (with null safety) - only if logged in
			List<LendingEntry> historyEntries = dataService.getHistoryEntries();
			if (historyEntries == null)
			{
				historyEntries = java.util.Collections.emptyList();
			}

			// Update header label
			totalHistoryLabel.setText("Total History: " + historyEntries.size() + " entries");

			if (historyEntries.isEmpty())
			{
				// Show empty state
				JPanel emptyPanel = new JPanel(new BorderLayout());
				emptyPanel.setBackground(ColorScheme.DARKER_GRAY_COLOR);
				emptyPanel.setBorder(new EmptyBorder(40, 20, 40, 20));

				JLabel emptyLabel = new JLabel("<html><center><b>No History Yet</b><br><br>Completed lending transactions<br>will appear here</center></html>");
				emptyLabel.setFont(FontManager.getRunescapeFont());
				emptyLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
				emptyLabel.setHorizontalAlignment(SwingConstants.CENTER);

				emptyPanel.add(emptyLabel, BorderLayout.CENTER);
				historyListPanel.add(emptyPanel);
			}
			else
			{
				// Sort entries by date (most recent first)
				historyEntries.sort((e1, e2) -> Long.compare(e2.getLendDate(), e1.getLendDate()));

				// Create history cards
				for (LendingEntry entry : historyEntries)
				{
					HistoryCard card = new HistoryCard(entry, itemManager);
					historyListPanel.add(card);
					historyListPanel.add(Box.createVerticalStrut(2));
				}
			}

			historyListPanel.revalidate();
			historyListPanel.repaint();
		});
	}

	/**
	 * Clear old history entries
	 */
	private void clearOldEntries()
	{
		int confirm = JOptionPane.showConfirmDialog(
			this,
			"Are you sure you want to clear old history entries?\nThis will remove all completed transactions older than 30 days.",
			"Clear History",
			JOptionPane.YES_NO_OPTION,
			JOptionPane.WARNING_MESSAGE
		);

		if (confirm == JOptionPane.YES_OPTION)
		{
			try
			{
				long thirtyDaysAgo = System.currentTimeMillis() - (30L * 24 * 60 * 60 * 1000);

				// Remove old entries from DataService (unified store)
				int removedCount = dataService.removeOldHistoryEntries(thirtyDaysAgo);

				refresh();

				JOptionPane.showMessageDialog(
					this,
					String.format("Cleared %d old entries (older than 30 days)", removedCount),
					"Success",
					JOptionPane.INFORMATION_MESSAGE
				);
			}
			catch (Exception e)
			{
				log.error("Failed to clear old entries", e);
				JOptionPane.showMessageDialog(
					this,
					"Failed to clear old entries: " + e.getMessage(),
					"Error",
					JOptionPane.ERROR_MESSAGE
				);
			}
		}
	}
}

package com.guess34.lendingtracker.ui;

import java.time.Instant;
import java.time.ZoneId;
import java.time.format.DateTimeFormatter;
import javax.swing.JComponent;
import net.runelite.client.util.QuantityFormatter;

import com.guess34.lendingtracker.model.LendingEntry;

/**
 * LoanTooltip - shared hover tooltip for loan cards (Active Loans and History),
 * showing the full deal at a glance: borrower, dates, collateral, notes.
 */
final class LoanTooltip
{
	private static final DateTimeFormatter DATE_TIME_FORMAT = DateTimeFormatter.ofPattern("MMM d, yyyy HH:mm");

	private LoanTooltip()
	{
	}

	/** Apply the loan tooltip to every given component (tooltips don't inherit). */
	static void apply(LendingEntry loan, JComponent... components)
	{
		String html = html(loan);
		for (JComponent c : components)
		{
			if (c != null)
			{
				c.setToolTipText(html);
			}
		}
	}

	static String html(LendingEntry loan)
	{
		StringBuilder sb = new StringBuilder("<html><b>")
			.append(escape(loan.getItem()));
		if (loan.getQuantity() > 1)
		{
			sb.append(" x").append(loan.getQuantity());
		}
		sb.append("</b> — ").append(QuantityFormatter.quantityToStackSize(loan.getValue())).append(" GP");

		sb.append("<br>Borrower: <b>").append(escape(loan.getBorrower())).append("</b>");
		if (loan.getLender() != null && !loan.getLender().isEmpty())
		{
			sb.append("<br>Lender: ").append(escape(loan.getLender()));
		}

		if (loan.getLendDate() > 0)
		{
			sb.append("<br>Lent: ").append(formatDate(loan.getLendDate()));
		}
		sb.append("<br>Due: ").append(loan.getDueTime() <= 0 || loan.getDueTime() == Long.MAX_VALUE
			? "no due date" : formatDate(loan.getDueTime()));
		if (loan.getReturnedAt() > 0)
		{
			sb.append("<br>Returned: ").append(formatDate(loan.getReturnedAt()));
		}

		sb.append("<br>Collateral: ").append(escape(collateralText(loan)));

		// Running-tally state: what each side still needs to hand back. Only shown
		// while something is outstanding, so settled/legacy loans stay unchanged.
		if (loan.getReturnedAt() == 0)
		{
			int lentOut = loan.outstandingLentQty();
			int lentTotal = Math.max(1, loan.getQuantity());
			if (lentOut > 0 && lentOut < lentTotal)
			{
				sb.append("<br>Still out: <b>").append(lentOut).append(" of ")
					.append(lentTotal).append("</b> with ")
					.append(escape(loan.getBorrower()));
			}
			else if (lentOut == 0)
			{
				sb.append("<br><b>All items returned</b> — awaiting collateral hand-back");
			}
			String collatOut = loan.outstandingCollateralIds();
			long gpOut = loan.outstandingCollateralGp();
			boolean partialCollat = (loan.getCollateralItemIds() != null
				&& !loan.getCollateralItemIds().equals(collatOut))
				|| (loan.getCollateralValue() != null && loan.getCollateralValue() > 0
					&& gpOut < loan.getCollateralValue());
			if (partialCollat)
			{
				sb.append("<br>Collateral still held: ");
				int collatQty = 0;
				if (!collatOut.isEmpty())
				{
					for (String pair : collatOut.split(","))
					{
						int idx = pair.indexOf(':');
						try
						{
							collatQty += idx > 0 ? Integer.parseInt(pair.substring(idx + 1)) : 1;
						}
						catch (NumberFormatException ignored)
						{
							collatQty += 1;
						}
					}
					sb.append(collatQty).append(" item(s)");
				}
				if (gpOut > 0)
				{
					sb.append(collatOut.isEmpty() ? "" : " + ")
						.append(QuantityFormatter.quantityToStackSize(gpOut)).append(" GP");
				}
				if (collatOut.isEmpty() && gpOut == 0)
				{
					sb.append("none — all returned");
				}
			}
		}

		if (loan.getNotes() != null && !loan.getNotes().isEmpty())
		{
			sb.append("<br>Notes: ").append(escape(loan.getNotes()));
		}
		return sb.append("</html>").toString();
	}

	private static String collateralText(LendingEntry loan)
	{
		if (loan.getCollateralValue() != null && loan.getCollateralValue() > 0)
		{
			return QuantityFormatter.quantityToStackSize(loan.getCollateralValue()) + " GP";
		}
		if (loan.getCollateralItems() != null && !loan.getCollateralItems().isEmpty())
		{
			return loan.getCollateralItems();
		}
		if (loan.isAgreedNoCollateral())
		{
			return "None (agreed)";
		}
		return "None";
	}

	private static String formatDate(long epochMillis)
	{
		return DATE_TIME_FORMAT.format(Instant.ofEpochMilli(epochMillis).atZone(ZoneId.systemDefault()));
	}

	private static String escape(String s)
	{
		if (s == null)
		{
			return "";
		}
		return s.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
	}
}

